{"command":"cd /workspace && cat > src/xml.rs <<'EOF'
//! Minimal XML DOM parser with source positions.

use std::fmt;

#[derive(Debug, Clone)]
pub struct Element {
    pub name: String,
    pub attrs: Vec<(String, String)>,
    pub children: Vec<Element>,
    /// Concatenated text of direct text children (first text node semantics, see `text()`)
    pub texts: Vec<TextPart>,
    /// byte offset of '<' in the source
    pub pos: usize,
}

#[derive(Debug, Clone)]
pub enum TextPart {
    /// text node (index into children: text appearing before child `before`)
    Text { before: usize, text: String },
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct TextPos {
    pub row: u32,
    pub col: u32,
}

impl fmt::Display for TextPos {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(f, "{}:{}", self.row, self.col)
    }
}

#[derive(Debug)]
pub struct Document {
    pub root: Element,
    src: String,
}

impl Document {
    pub fn text_pos_at(&self, pos: usize) -> TextPos {
        let pos = pos.min(self.src.len());
        let before = &self.src[..pos];
        let row = before.matches('\n').count() as u32 + 1;
        let line_start = before.rfind('\n').map(|i| i + 1).unwrap_or(0);
        let col = before[line_start..].chars().count() as u32 + 1;
        TextPos { row, col }
    }
}

impl Element {
    pub fn attribute(&self, name: &str) -> Option<&str> {
        self.attrs
            .iter()
            .find(|(k, _)| k == name)
            .map(|(_, v)| v.as_str())
    }

    /// Text of the first child node if it is a text node (roxmltree `Node::text` semantics).
    pub fn text(&self) -> Option<&str> {
        for part in &self.texts {
            let TextPart::Text { before, text } = part;
            if *before == 0 {
                return Some(text.as_str());
            }
        }
        None
    }

    pub fn get_child(&self, name: &str) -> Option<&Element> {
        self.children.iter().find(|c| c.name == name)
    }

    pub fn children_named<'a>(&'a self, name: &'a str) -> impl Iterator<Item = &'a Element> + 'a {
        self.children.iter().filter(move |c| c.name == name)
    }
}

#[derive(Debug)]
pub struct Error {
    pub msg: String,
    pub pos: TextPos,
}

impl fmt::Display for Error {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(f, "{} at {}", self.msg, self.pos)
    }
}

impl std::error::Error for Error {}

#[derive(Debug)]
pub enum ParseError {
    NoRoot,
    Other(Error),
}

impl fmt::Display for ParseError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
