    fn skip_misc(&mut self) -> Result<(), ParseError> {
        loop {
            self.skip_ws();
            let start = self.pos;
            if self.starts_with("<!--") {
                self.pos += 4;
                self.skip_until("-->", start)?;
            } else if self.starts_with("<?") {
                self.pos += 2;
                self.skip_until("?>", start)?;
            } else if self.starts_with("<!DOCTYPE") {
                self.pos += 9;
                // skip to matching '>' (handle internal subset crudely)
                let mut depth = 0i32;
                loop {
                    match self.peek() {
                        None => return Err(self.err("unexpected end of stream", start)),
                        Some(b'[') => {
                            depth += 1;
                            self.pos += 1;
                        }
                        Some(b']') => {
                            depth -= 1;
                            self.pos += 1;
                        }
                        Some(b'>') if depth <= 0 => {
                            self.pos += 1;
                            break;
                        }
                        Some(_) => self.pos += 1,
                    }
                }
            } else {
