}

fn decode_entities(raw: &str, p: &Parser, base: usize) -> Result<String, ParseError> {
    if !raw.contains('&') {
        return Ok(normalize_newlines(raw));
    }
    let mut out = String::with_capacity(raw.len());
    let mut rest = raw;
    let mut offset = base;
    while let Some(i) = rest.find('&') {
        out.push_str(&rest[..i]);
        let after = &rest[i + 1..];
        match after.find(';') {
            Some(j) => {
                let ent = &after[..j];
                let decoded = match ent {
                    "lt" => Some('<'),
                    "gt" => Some('>'),
                    "amp" => Some('&'),
                    "quot" => Some('"'),
                    "apos" => Some('\''),
                    _ => {
                        if let Some(hex) = ent.strip_prefix("#x") {
                            u32::from_str_radix(hex, 16).ok().and_then(char::from_u32)
                        } else if let Some(dec) = ent.strip_prefix('#') {
                            dec.parse::<u32>().ok().and_then(char::from_u32)
                        } else {
                            None
                        }
                    }
                };
                match decoded {
                    Some(c) => out.push(c),
                    None => {
                        return Err(p.err(
                            &format!("unknown entity reference '{ent}'"),
                            offset + i + 1,
                        ))
                    }
                }
                offset += i + 1 + j + 1;
                rest = &after[j + 1..];
            }
            None => {
                return Err(p.err("invalid reference", offset + i));
            }
        }
    }
    out.push_str(rest);
    Ok(normalize_newlines(&out))
}

fn normalize_newlines(s: &str) -> String {
    if s.contains('\r') {
        s.replace("\r\n", "\n").replace('\r', "\n")
    } else {
        s.to_string()
    }
}

pub fn parse(src: &str) -> Result<Document, ParseError> {
    let mut p = Parser {
        src,
        bytes: src.as_bytes(),
        pos: 0,
    };
    let root = p.parse_document()?;
    Ok(Document {
        root,
        src: src.to_string(),
    })
}
