//! SVD XML parser (svd-parser compatible semantics)

use super::*;
use crate::xml::{self, Document, Element};

#[derive(Debug)]
pub struct SvdError {
    /// Position (byte offset) of the node the error belongs to
    pub pos: usize,
    pub tag: String,
    pub name: Option<String>,
    pub msg: String,
    /// contexts, innermost first
    pub contexts: Vec<String>,
}

impl SvdError {
    fn at(el: &Element, msg: String) -> Self {
        SvdError {
            pos: el.pos,
            tag: el.name.clone(),
            name: el.get_child("name").and_then(|n| n.text()).map(|s| s.to_string()),
            msg,
            contexts: Vec::new(),
        }
    }
}

type Result<T> = std::result::Result<T, SvdError>;

pub struct Config {
    pub validate_level: ValidateLevel,
}

trait ElementExt {
    fn get_child_elem(&self, name: &str) -> Result<&Element>;
    fn get_text(&self) -> Result<&str>;
    fn get_child_text_opt(&self, name: &str) -> Result<Option<String>>;
    fn get_child_text(&self, name: &str) -> Result<String>;
    fn get_child_u32(&self, name: &str) -> Result<u32>;
    fn get_child_u64(&self, name: &str) -> Result<u64>;
    fn get_child_bool(&self, name: &str) -> Result<bool>;
}

fn missing_tag(el: &Element, name: &str) -> SvdError {
    SvdError::at(el, format!("Expected a <{name}> tag, found none"))
}

impl ElementExt for Element {
    fn get_child_elem(&self, name: &str) -> Result<&Element> {
        self.get_child(name).ok_or_else(|| missing_tag(self, name))
    }
    fn get_text(&self) -> Result<&str> {
        match self.text() {
            Some(s) => Ok(s),
            None => Err(SvdError::at(
                self,
                format!("Expected content in <{}> tag, found none", self.name),
            )),
        }
    }
    fn get_child_text_opt(&self, name: &str) -> Result<Option<String>> {
        if let Some(child) = self.get_child(name) {
            child.get_text().map(|s| Some(s.to_string()))
        } else {
            Ok(None)
        }
    }
    fn get_child_text(&self, name: &str) -> Result<String> {
        self.get_child_text_opt(name)?
            .ok_or_else(|| missing_tag(self, name))
    }
    fn get_child_u32(&self, name: &str) -> Result<u32> {
        parse_u32(self.get_child_elem(name)?)
    }
    fn get_child_u64(&self, name: &str) -> Result<u64> {
        parse_u64(self.get_child_elem(name)?)
    }
    fn get_child_bool(&self, name: &str) -> Result<bool> {
        parse_bool(self.get_child_elem(name)?)
    }
}

fn parse_u64(el: &Element) -> Result<u64> {
    let text = el.get_text()?.trim();
    let res = if let Some(t) = text.strip_prefix("0x").or_else(|| text.strip_prefix("0X")) {
        u64::from_str_radix(t, 16)
    } else if let Some(t) = text.strip_prefix('#') {
        u64::from_str_radix(&t.to_lowercase().replace('x', "0"), 2)
    } else if let Some(t) = text.strip_prefix("0b") {
        u64::from_str_radix(&t.replace('x', "0"), 2)
    } else {
        text.parse::<u64>()
    };
    res.map_err(|e| SvdError::at(el, format!("Failed to parse `{e}`")))
}

fn parse_u32(el: &Element) -> Result<u32> {
    let text = el.get_text()?.trim();
    let res = if let Some(t) = text.strip_prefix("0x").or_else(|| text.strip_prefix("0X")) {
        u32::from_str_radix(t, 16)
    } else if let Some(t) = text.strip_prefix('#') {
        u32::from_str_radix(&t.to_lowercase().replace('x', "0"), 2)
    } else if let Some(t) = text.strip_prefix("0b") {
        u32::from_str_radix(&t.replace('x', "0"), 2)
    } else {
        text.parse::<u32>()
    };
    res.map_err(|e| SvdError::at(el, format!("Failed to parse `{e}`")))
}

fn parse_bool(el: &Element) -> Result<bool> {
    let text = el.get_text()?.trim();
    match text {
        "0" => Ok(false),
        "1" => Ok(true),
        _ => text.parse::<bool>().map_err(|e| {
            SvdError::at(
                el,
                format!("The content of the element could not be parsed to a boolean value {text}: {e}"),
            )
        }),
    }
}

fn optional<T>(name: &str, el: &Element, f: impl FnOnce(&Element) -> Result<T>) -> Result<Option<T>> {
    match el.get_child(name) {
        Some(c) => f(c).map(Some),
        None => Ok(None),
    }
}

fn opt_u32(el: &Element, name: &str) -> Result<Option<u32>> {
    optional(name, el, parse_u32)
}
fn opt_u64(el: &Element, name: &str) -> Result<Option<u64>> {
    optional(name, el, parse_u64)
}
fn opt_bool(el: &Element, name: &str) -> Result<Option<bool>> {
    optional(name, el, parse_bool)
}

/// Add "In {kind} `{name}`" context to errors coming from children of `el`.
fn in_context<T>(el: &Element, kind: &str, res: Result<T>) -> Result<T> {
    res.map_err(|mut e| {
        if e.pos != el.pos {
            let name = el
                .get_child("name")
                .and_then(|n| n.text())
                .unwrap_or("")
                .to_string();
            e.contexts.push(format!("In {kind} `{name}`"));
        }
        e
    })
}

fn svd_err(el: &Element, kind: &str, msg: impl std::fmt::Display) -> SvdError {
    SvdError::at(el, format!("`{kind} error: {msg}"))
}

