pub fn parse_access(el: &Element) -> Result<Access> {
    let text = el.get_text()?;
    match text.trim() {
        "read-only" => Ok(Access::ReadOnly),
        "read-write" => Ok(Access::ReadWrite),
        "read-writeOnce" => Ok(Access::ReadWriteOnce),
        "write-only" => Ok(Access::WriteOnly),
        "writeOnce" => Ok(Access::WriteOnce),
        _ => Err(SvdError::at(el, format!("unknown access variant '{text}' found"))),
    }
}

fn parse_protection(el: &Element) -> Result<Protection> {
    let text = el.get_text()?;
    match text.trim() {
        "s" => Ok(Protection::Secure),
        "n" => Ok(Protection::NonSecure),
        "p" => Ok(Protection::Privileged),
        _ => Err(SvdError::at(el, "Unknown protection variant".to_string())),
    }
}

fn parse_usage(el: &Element) -> Result<Usage> {
    let text = el.get_text()?;
    match text.trim() {
        "read" => Ok(Usage::Read),
        "write" => Ok(Usage::Write),
        "read-write" => Ok(Usage::ReadWrite),
        _ => Err(SvdError::at(el, "Unknown usage variant".to_string())),
    }
}

fn parse_endian(el: &Element) -> Result<Endian> {
    let text = el.get_text()?;
    match text.trim() {
        "little" => Ok(Endian::Little),
        "big" => Ok(Endian::Big),
        "selectable" => Ok(Endian::Selectable),
        "other" => Ok(Endian::Other),
        _ => Err(SvdError::at(el, format!("Unknown endianness `{text}`"))),
    }
}

fn parse_mwv(el: &Element) -> Result<ModifiedWriteValues> {
    use ModifiedWriteValues::*;
    let text = el.get_text()?;
    match text.trim() {
        "oneToClear" => Ok(OneToClear),
        "oneToSet" => Ok(OneToSet),
        "oneToToggle" => Ok(OneToToggle),
        "zeroToClear" => Ok(ZeroToClear),
        "zeroToSet" => Ok(ZeroToSet),
        "zeroToToggle" => Ok(ZeroToToggle),
        "clear" => Ok(Clear),
        "set" => Ok(Set),
        "modify" => Ok(Modify),
        _ => Err(SvdError::at(
            el,
            format!("Invalid modifiedWriteValues variant, found {text}"),
        )),
    }
}

fn parse_read_action(el: &Element) -> Result<ReadAction> {
    let text = el.get_text()?;
    match text.trim() {
        "clear" => Ok(ReadAction::Clear),
        "set" => Ok(ReadAction::Set),
        "modify" => Ok(ReadAction::Modify),
        "modifyExternal" => Ok(ReadAction::ModifyExternal),
        _ => Err(SvdError::at(el, "Unknown readAction variant".to_string())),
    }
}

fn parse_datatype(el: &Element) -> Result<DataType> {
    use DataType::*;
    let text = el.get_text()?;
    match text.trim() {
        "uint8_t" => Ok(U8),
        "uint16_t" => Ok(U16),
        "uint32_t" => Ok(U32),
        "uint64_t" => Ok(U64),
        "int8_t" => Ok(I8),
        "int16_t" => Ok(I16),
        "int32_t" => Ok(I32),
        "int64_t" => Ok(I64),
        "uint8_t *" => Ok(U8Ptr),
        "uint16_t *" => Ok(U16Ptr),
        "uint32_t *" => Ok(U32Ptr),
        "uint64_t *" => Ok(U64Ptr),
        "int8_t *" => Ok(I8Ptr),
        "int16_t *" => Ok(I16Ptr),
        "int32_t *" => Ok(I32Ptr),
        "int64_t *" => Ok(I64Ptr),
        _ => Err(SvdError::at(el, "Unknown datatype variant".to_string())),
    }
}

fn parse_address_block_usage(el: &Element) -> Result<AddressBlockUsage> {
    let text = el.get_text()?;
    match text.trim() {
        "registers" => Ok(AddressBlockUsage::Registers),
        "buffer" => Ok(AddressBlockUsage::Buffer),
        "reserved" => Ok(AddressBlockUsage::Reserved),
        _ => Err(SvdError::at(el, format!("unknown addressBlock usage variant '{text}' found"))),
    }
