fn parse_write_constraint(el: &Element) -> Result<WriteConstraint> {
    let children: Vec<&Element> = el.children.iter().collect();
    if children.len() == 1 {
        let c = children[0];
        match c.name.as_str() {
            "writeAsRead" => Ok(WriteConstraint::WriteAsRead(parse_bool(c)?)),
            "useEnumeratedValues" => Ok(WriteConstraint::UseEnumeratedValues(parse_bool(c)?)),
            "range" => Ok(WriteConstraint::Range(WriteConstraintRange {
                min: c.get_child_u64("minimum")?,
                max: c.get_child_u64("maximum")?,
            })),
            _ => Err(SvdError::at(el, "Unknown write constraint".to_string())),
        }
    } else {
        Err(SvdError::at(el, "Unknown write constraint".to_string()))
    }
}

fn parse_register_properties(el: &Element) -> Result<RegisterProperties> {
    Ok(RegisterProperties {
        size: opt_u32(el, "size")?,
        access: optional("access", el, parse_access)?,
        protection: optional("protection", el, parse_protection)?,
        reset_value: opt_u64(el, "resetValue")?,
        reset_mask: opt_u64(el, "resetMask")?,
    })
}

fn parse_cpu(el: &Element, _cfg: &Config) -> Result<Cpu> {
    if el.name != "cpu" {
        return Err(SvdError::at(el, "Expected a <cpu>, found ...".to_string()));
