    Ok(Cpu {
        name: el.get_child_text("name")?,
        revision: el.get_child_text("revision")?,
        endian: parse_endian(el.get_child_elem("endian")?)?,
        mpu_present: el.get_child_bool("mpuPresent")?,
        fpu_present: el.get_child_bool("fpuPresent")?,
        fpu_double_precision: opt_bool(el, "fpuDP")?,
        dsp_present: opt_bool(el, "dspPresent")?,
        icache_present: opt_bool(el, "icachePresent")?,
        dcache_present: opt_bool(el, "dcachePresent")?,
        itcm_present: opt_bool(el, "itcmPresent")?,
        dtcm_present: opt_bool(el, "dtcmPresent")?,
        vtor_present: opt_bool(el, "vtorPresent")?,
        nvic_priority_bits: el.get_child_u32("nvicPrioBits")?,
        has_vendor_systick: el.get_child_bool("vendorSystickConfig")?,
        device_num_interrupts: opt_u32(el, "deviceNumInterrupts")?,
        sau_num_regions: opt_u32(el, "sauNumRegions")?,
    })
}

fn parse_interrupt(el: &Element, cfg: &Config) -> Result<Interrupt> {
    let name = el.get_child_text("name")?;
    let i = Interrupt {
        name,
        description: el.get_child_text_opt("description")?,
        value: el.get_child_u32("value")?,
    };
    validate::interrupt(&i, cfg.validate_level).map_err(|m| svd_err(el, "Interrupt", m))?;
    Ok(i)
}

fn parse_address_block(el: &Element, cfg: &Config) -> Result<AddressBlock> {
    let ab = AddressBlock {
        offset: el.get_child_u32("offset")?,
        size: el.get_child_u32("size")?,
        usage: parse_address_block_usage(el.get_child_elem("usage")?)?,
        protection: optional("protection", el, parse_protection)?,
    };
    let _ = cfg;
    Ok(ab)
}

fn parse_dim_index(el: &Element, text: &str) -> Result<Vec<String>> {
    let text = text.trim();
    let err = || SvdError::at(el, "Failed to parse dimIndex".to_string());
    if text.contains('-') {
        let mut parts = text.split('-');
        let start = parts.next().ok_or_else(err)?;
        let end = parts.next().ok_or_else(err)?;
        if parts.next().is_some() {
            return Err(err());
        }
        if let (Ok(s), Ok(e)) = (start.parse::<u32>(), end.parse::<u32>()) {
            if s > e {
                return Err(err());
            }
            Ok((s..=e).map(|i| i.to_string()).collect())
        } else {
            let mut sc = start.chars();
            let mut ec = end.chars();
            match (sc.next(), sc.next(), ec.next(), ec.next()) {
                (Some(s), None, Some(e), None) if s <= e => {
                    Ok((s..=e).map(|c| c.to_string()).collect())
                }
                _ => Err(err()),
            }
        }
    } else {
        Ok(text.split(',').map(|s| s.trim().to_string()).collect())
    }
}

fn parse_dim_array_index(el: &Element, cfg: &Config) -> Result<DimArrayIndex> {
    let mut values = Vec::new();
    for c in el.children_named("enumeratedValue") {
        values.push(parse_enumerated_value(c, cfg)?);
    }
    Ok(DimArrayIndex {
        header_enum_name: el.get_child_text_opt("headerEnumName")?,
        values,
    })
}

fn parse_dim_element(el: &Element, cfg: &Config) -> Result<DimElement> {
    let dim = el.get_child_u32("dim")?;
    let dim_increment = el.get_child_u32("dimIncrement")?;
    let dim_index = match el.get_child("dimIndex") {
        Some(c) => Some(parse_dim_index(c, c.get_text()?)?),
        None => None,
    };
    let dim_name = el.get_child_text_opt("dimName")?;
    let dim_array_index = optional("dimArrayIndex", el, |c| parse_dim_array_index(c, cfg))?;
    let d = DimElement {
        dim,
        dim_increment,
        dim_index,
        dim_name,
        dim_array_index,
    };
    validate::dim_element(&d, cfg.validate_level).map_err(|m| svd_err(el, "DimElement", m))?;
    Ok(d)
}

fn check_has_placeholder(el: &Element, name: &str, tag: &str) -> Result<()> {
    if name.contains("%s") {
        Ok(())
    } else {
        Err(SvdError::at(
            el,
            format!("Name `{name}` in tag `{tag}` is missing a %s placeholder"),
        ))
    }
}

fn parse_array<T>(
    tag: &str,
    el: &Element,
    cfg: &Config,
    info: impl FnOnce(&Element, &Config) -> Result<T>,
    name_of: impl Fn(&T) -> &str,
) -> Result<MaybeArray<T>> {
    let info = info(el, cfg)?;
    if el.get_child("dimIncrement").is_some() {
        let dim = parse_dim_element(el, cfg)?;
        check_has_placeholder(el, name_of(&info), tag)?;
        if let Some(indexes) = &dim.dim_index {
            if dim.dim as usize != indexes.len() {
                return Err(SvdError::at(
                    el,
                    format!(
                        "dimIndex tag must contain {} indexes, found {}",
                        dim.dim,
                        indexes.len()
                    ),
                ));
            }
        }
        Ok(MaybeArray::Array(info, dim))
    } else {
        Ok(MaybeArray::Single(info))
    }
}

fn parse_enumerated_value(el: &Element, cfg: &Config) -> Result<EnumeratedValue> {
    in_context(el, "enumeratedValue", (|| {
        if el.name != "enumeratedValue" {
            return Err(SvdError::at(el, "Expected a <enumeratedValue>, found ...".to_string()));
        }
        let ev = EnumeratedValue {
            name: el.get_child_text("name")?,
            description: el.get_child_text_opt("description")?,
            value: opt_u64(el, "value")?,
            is_default: el.get_child_bool("isDefault").ok(),
        };
        validate::enumerated_value(&ev, cfg.validate_level)
            .map_err(|m| svd_err(el, "EnumeratedValue", m))?;
        Ok(ev)
    })())
}

fn parse_enumerated_values(el: &Element, cfg: &Config) -> Result<EnumeratedValues> {
    if el.name != "enumeratedValues" {
        return Err(SvdError::at(el, "Expected a <enumeratedValues>, found ...".to_string()));
    }
    let mut values = Vec::new();
    for c in &el.children {
        if c.name == "enumeratedValue" {
            values.push(parse_enumerated_value(c, cfg)?);
        }
    }
    let evs = EnumeratedValues {
        name: el.get_child_text_opt("name")?,
        usage: optional("usage", el, parse_usage)?,
        derived_from: el.attribute("derivedFrom").map(|s| s.to_string()),
        values,
    };
    validate::enumerated_values(&evs, cfg.validate_level)
        .map_err(|m| svd_err(el, "EnumeratedValues", m))?;
    Ok(evs)
}

fn parse_bit_range(el: &Element) -> Result<BitRange> {
    let inv = |what: &str| SvdError::at(el, format!("Bit range invalid, {what}"));
    let (end, start, range_type): (u32, u32, BitRangeType) =
        if let Some(range) = el.get_child("bitRange") {
            let text = range.get_text()?;
            let text = text.trim();
            if !text.starts_with('[') {
                return Err(inv("Syntax"));
            }
            if !text.ends_with(']') {
                return Err(inv("Syntax"));
            }
            let inner = &text[1..text.len() - 1];
            let mut parts = inner.split(':');
            let end = parts
                .next()
                .ok_or_else(|| inv("Syntax"))?
                .trim()
                .parse::<u32>()
                .map_err(|_| inv("ParseError"))?;
            let start = parts
                .next()
                .ok_or_else(|| inv("Syntax"))?
                .trim()
                .parse::<u32>()
                .map_err(|_| inv("ParseError"))?;
            (end, start, BitRangeType::BitRange)
        } else if let (Some(lsb), Some(msb)) = (el.get_child("lsb"), el.get_child("msb")) {
            (parse_u32(msb)?, parse_u32(lsb)?, BitRangeType::MsbLsb)
        } else if let (Some(offset), Some(width)) =
            (el.get_child("bitOffset"), el.get_child("bitWidth"))
        {
            let offset = parse_u32(offset)?;
            let width = parse_u32(width)?;
            return Ok(BitRange {
                offset,
                width,
                range_type: BitRangeType::OffsetWidth,
            });
        } else {
            return Err(inv("Syntax"));
        };
    if end < start {
        return Err(inv("Size"));
    }
    Ok(BitRange {
        offset: start,
        width: end - start + 1,
        range_type,
    })
}

fn parse_field_info(el: &Element, cfg: &Config) -> Result<FieldInfo> {
    if el.name != "field" {
        return Err(SvdError::at(el, "Expected a <field>, found ...".to_string()));
    }
    let name = el.get_child_text("name")?;
    in_context(el, "field", (|| {
        let bit_range = parse_bit_range(el)?;
        let mut enumerated_values = Vec::new();
        for c in &el.children {
            if c.name == "enumeratedValues" {
                enumerated_values.push(parse_enumerated_values(c, cfg)?);
            }
        }
        let f = FieldInfo {
            name: name.clone(),
            description: el.get_child_text_opt("description")?,
            bit_range,
            access: optional("access", el, parse_access)?,
            modified_write_values: optional("modifiedWriteValues", el, parse_mwv)?,
            write_constraint: optional("writeConstraint", el, parse_write_constraint)?,
            read_action: optional("readAction", el, parse_read_action)?,
            enumerated_values,
            derived_from: el.attribute("derivedFrom").map(|s| s.to_string()),
        };
        validate::field(&f, cfg.validate_level).map_err(|(k, m)| svd_err(el, k, m))?;
        Ok(f)
    })())
}

fn parse_field(el: &Element, cfg: &Config) -> Result<Field> {
    parse_array("field", el, cfg, parse_field_info, |f| &f.name)
}

fn parse_register_info(el: &Element, cfg: &Config) -> Result<RegisterInfo> {
    if el.name != "register" {
        return Err(SvdError::at(el, "Expected a <register>, found ...".to_string()));
    }
    let name = el.get_child_text("name")?;
    in_context(el, "register", (|| {
        let properties = parse_register_properties(el)?;
        let fields = match el.get_child("fields") {
            Some(fs) => {
                let mut v = Vec::new();
                for c in &fs.children {
                    v.push(parse_field(c, cfg)?);
                }
                Some(v)
            }
            None => None,
        };
        let r = RegisterInfo {
            name: name.clone(),
            display_name: el.get_child_text_opt("displayName")?,
            description: el.get_child_text_opt("description")?,
            alternate_group: el.get_child_text_opt("alternateGroup")?,
            alternate_register: el.get_child_text_opt("alternateRegister")?,
            address_offset: el.get_child_u32("addressOffset")?,
            properties,
            datatype: optional("dataType", el, parse_datatype)?,
            modified_write_values: optional("modifiedWriteValues", el, parse_mwv)?,
            write_constraint: optional("writeConstraint", el, parse_write_constraint)?,
            read_action: optional("readAction", el, parse_read_action)?,
            fields,
            derived_from: el.attribute("derivedFrom").map(|s| s.to_string()),
        };
        validate::register(&r, cfg.validate_level).map_err(|(k, m)| svd_err(el, k, m))?;
        Ok(r)
    })())
}

fn parse_register(el: &Element, cfg: &Config) -> Result<Register> {
    parse_array("register", el, cfg, parse_register_info, |r| &r.name)
}

fn parse_cluster_info(el: &Element, cfg: &Config) -> Result<ClusterInfo> {
    if el.name != "cluster" {
        return Err(SvdError::at(el, "Expected a <cluster>, found ...".to_string()));
    }
    let name = el.get_child_text("name")?;
    let mut children = Vec::new();
    for c in &el.children {
        if c.name == "register" || c.name == "cluster" {
            children.push(parse_register_cluster(c, cfg)?);
        }
    }
    let c = ClusterInfo {
        name,
        description: el.get_child_text_opt("description")?,
        alternate_cluster: el.get_child_text_opt("alternateCluster")?,
        header_struct_name: el.get_child_text_opt("headerStructName")?,
        address_offset: el.get_child_u32("addressOffset")?,
        default_register_properties: parse_register_properties(el)?,
        children,
        derived_from: el.attribute("derivedFrom").map(|s| s.to_string()),
    };
    validate::cluster(&c, cfg.validate_level).map_err(|(k, m)| svd_err(el, k, m))?;
    Ok(c)
}

fn parse_cluster(el: &Element, cfg: &Config) -> Result<Cluster> {
    parse_array("cluster", el, cfg, parse_cluster_info, |c| &c.name)
}

fn parse_register_cluster(el: &Element, cfg: &Config) -> Result<RegisterCluster> {
    match el.name.as_str() {
        "register" => Ok(RegisterCluster::Register(parse_register(el, cfg)?)),
        "cluster" => Ok(RegisterCluster::Cluster(parse_cluster(el, cfg)?)),
        other => Err(SvdError::at(
            el,
            format!("Invalid RegisterCluster (expected register or cluster), found {other}"),
        )),
    }
}

fn parse_peripheral_info(el: &Element, cfg: &Config) -> Result<PeripheralInfo> {
    if el.name != "peripheral" {
        return Err(SvdError::at(el, "Expected a <peripheral>, found ...".to_string()));
    }
    let name = el.get_child_text("name")?;
    in_context(el, "peripheral", (|| {
        let mut interrupt = Vec::new();
        for c in el.children_named("interrupt") {
            interrupt.push(parse_interrupt(c, cfg)?);
        }
        let address_block = {
            let v: Vec<AddressBlock> = el
                .children_named("addressBlock")
                .map(|c| parse_address_block(c, cfg))
                .collect::<Result<_>>()?;
            if v.is_empty() {
                None
            } else {
                Some(v)
            }
        };
        let registers = match el.get_child("registers") {
            Some(rs) => {
                let mut v = Vec::new();
                for c in &rs.children {
                    v.push(parse_register_cluster(c, cfg)?);
                }
                Some(v)
            }
            None => None,
        };
        let p = PeripheralInfo {
            name: name.clone(),
            display_name: el.get_child_text_opt("displayName")?,
            version: el.get_child_text_opt("version")?,
            description: el.get_child_text_opt("description")?,
            alternate_peripheral: el.get_child_text_opt("alternatePeripheral")?,
            group_name: el.get_child_text_opt("groupName")?,
            prepend_to_name: el.get_child_text_opt("prependToName")?,
            append_to_name: el.get_child_text_opt("appendToName")?,
            header_struct_name: el.get_child_text_opt("headerStructName")?,
            base_address: el.get_child_u64("baseAddress")?,
            default_register_properties: parse_register_properties(el)?,
            address_block,
            interrupt,
            registers,
            derived_from: el.attribute("derivedFrom").map(|s| s.to_string()),
        };
        validate::peripheral(&p, cfg.validate_level).map_err(|(k, m)| svd_err(el, k, m))?;
        Ok(p)
    })())
}

fn parse_peripheral(el: &Element, cfg: &Config) -> Result<Peripheral> {
    parse_array("peripheral", el, cfg, parse_peripheral_info, |p| &p.name)
}

fn parse_device(el: &Element, cfg: &Config) -> Result<Device> {
    if el.name != "device" {
        return Err(SvdError::at(el, "Expected a <device>, found ...".to_string()));
    }
    let name = el.get_child_text("name")?;
    in_context(el, "device", (|| {
        let peripherals = {
            let ps = el.get_child_elem("peripherals")?;
            let mut v = Vec::new();
            for c in &ps.children {
                v.push(parse_peripheral(c, cfg)?);
            }
            v
        };
        let d = Device {
            vendor: el.get_child_text_opt("vendor")?,
            vendor_id: el.get_child_text_opt("vendorID")?,
            name: name.clone(),
            series: el.get_child_text_opt("series")?,
            version: el.get_child_text_opt("version")?,
            description: el.get_child_text_opt("description")?,
            license_text: el.get_child_text_opt("licenseText")?,
            cpu: optional("cpu", el, |c| parse_cpu(c, cfg))?,
            header_system_filename: el.get_child_text_opt("headerSystemFilename")?,
            header_definitions_prefix: el.get_child_text_opt("headerDefinitionsPrefix")?,
            address_unit_bits: opt_u32(el, "addressUnitBits")?,
            width: opt_u32(el, "width")?,
            default_register_properties: parse_register_properties(el)?,
            peripherals,
            xmlns_xs: el.attribute("xmlns:xs").unwrap_or("").to_string(),
            no_namespace_schema_location: el
                .attribute("xs:noNamespaceSchemaLocation")
                .unwrap_or("")
                .to_string(),
            schema_version: el.attribute("schemaVersion").unwrap_or("").to_string(),
        };
        validate::device(&d, cfg.validate_level).map_err(|(k, m)| svd_err(el, k, m))?;
        Ok(d)
    })())
}

pub fn parse_with_config(xml: &str, cfg: &Config) -> anyhow::Result<Device> {
    let doc: Document = xml::parse(xml).map_err(|e| anyhow::anyhow!("{e}"))?;
    let root = &doc.root;
    if root.name != "device" {
        // roxmltree root node is the document; `get_child("device")` on it
        let err = SvdError {
            pos: 0,
            tag: String::new(),
            name: None,
            msg: "Expected a <device> tag, found none".to_string(),
            contexts: vec![],
        };
        return Err(to_anyhow(&doc, err, false));
    }
    match parse_device(root, cfg) {
        Ok(d) => Ok(d),
        Err(e) => Err(to_anyhow(&doc, e, true)),
    }
}

fn to_anyhow(doc: &Document, e: SvdError, with_pos: bool) -> anyhow::Error {
    let mut err = anyhow::anyhow!("{}", e.msg);
    if with_pos {
        let pos = doc.text_pos_at(e.pos);
        let ctx = match &e.name {
            Some(n) => format!("Parsing {} `{}` at {}", e.tag, n, pos),
            None => format!("Parsing unknown {} at {}", e.tag, pos),
        };
        err = err.context(ctx);
    }
    for c in e.contexts {
        err = err.context(c);
    }
    err
}
