//! SVD XML parser (svd-parser compatible semantics)

use super::*;
use crate::xml::{self, Document, Element};

#[derive(Debug)]
pub struct SvdError {
    /// Position (byte offset) of the node the error belongs to
    pub pos: usize,
    pub tag: String,
    pub name: Option<String>,
    pub msg: String,
    /// contexts, innermost first
    pub contexts: Vec<String>,
}

impl SvdError {
    fn at(el: &Element, msg: String) -> Self {
        SvdError {
            pos: el.pos,
            tag: el.name.clone(),
            name: el.get_child("name").and_then(|n| n.text()).map(|s| s.to_string()),
            msg,
            contexts: Vec::new(),
        }
    }
}

type Result<T> = std::result::Result<T, SvdError>;

pub struct Config {
    pub validate_level: ValidateLevel,
}

trait ElementExt {
    fn get_child_elem(&self, name: &str) -> Result<&Element>;
    fn get_text(&self) -> Result<&str>;
    fn get_child_text_opt(&self, name: &str) -> Result<Option<String>>;
    fn get_child_text(&self, name: &str) -> Result<String>;
    fn get_child_u32(&self, name: &str) -> Result<u32>;
    fn get_child_u64(&self, name: &str) -> Result<u64>;
    fn get_child_bool(&self, name: &str) -> Result<bool>;
}

fn missing_tag(el: &Element, name: &str) -> SvdError {
    SvdError::at(el, format!("Expected a <{name}> tag, found none"))
}

impl ElementExt for Element {
    fn get_child_elem(&self, name: &str) -> Result<&Element> {
        self.get_child(name).ok_or_else(|| missing_tag(self, name))
    }
    fn get_text(&self) -> Result<&str> {
        match self.text() {
            Some(s) => Ok(s),
            None => Err(SvdError::at(
                self,
                format!("Expected content in <{}> tag, found none", self.name),
            )),
        }
    }
    fn get_child_text_opt(&self, name: &str) -> Result<Option<String>> {
        if let Some(child) = self.get_child(name) {
            child.get_text().map(|s| Some(s.to_string()))
        } else {
            Ok(None)
        }
    }
    fn get_child_text(&self, name: &str) -> Result<String> {
        self.get_child_text_opt(name)?
            .ok_or_else(|| missing_tag(self, name))
    }
    fn get_child_u32(&self, name: &str) -> Result<u32> {
        parse_u32(self.get_child_elem(name)?)
    }
    fn get_child_u64(&self, name: &str) -> Result<u64> {
        parse_u64(self.get_child_elem(name)?)
    }
    fn get_child_bool(&self, name: &str) -> Result<bool> {
        parse_bool(self.get_child_elem(name)?)
    }
}

fn parse_u64(el: &Element) -> Result<u64> {
    let text = el.get_text()?.trim();
    let res = if let Some(t) = text.strip_prefix("0x").or_else(|| text.strip_prefix("0X")) {
        u64::from_str_radix(t, 16)
    } else if let Some(t) = text.strip_prefix('#') {
        u64::from_str_radix(&t.to_lowercase().replace('x', "0"), 2)
    } else if let Some(t) = text.strip_prefix("0b") {
        u64::from_str_radix(&t.replace('x', "0"), 2)
    } else {
        text.parse::<u64>()
    };
    res.map_err(|e| SvdError::at(el, format!("Failed to parse `{e}`")))
}

fn parse_u32(el: &Element) -> Result<u32> {
    let text = el.get_text()?.trim();
    let res = if let Some(t) = text.strip_prefix("0x").or_else(|| text.strip_prefix("0X")) {
        u32::from_str_radix(t, 16)
    } else if let Some(t) = text.strip_prefix('#') {
        u32::from_str_radix(&t.to_lowercase().replace('x', "0"), 2)
    } else if let Some(t) = text.strip_prefix("0b") {
        u32::from_str_radix(&t.replace('x', "0"), 2)
    } else {
        text.parse::<u32>()
    };
    res.map_err(|e| SvdError::at(el, format!("Failed to parse `{e}`")))
}

fn parse_bool(el: &Element) -> Result<bool> {
    let text = el.get_text()?.trim();
    match text {
        "0" => Ok(false),
        "1" => Ok(true),
        _ => text.parse::<bool>().map_err(|e| {
            SvdError::at(
                el,
                format!("The content of the element could not be parsed to a boolean value {text}: {e}"),
            )
        }),
    }
}

fn optional<T>(name: &str, el: &Element, f: impl FnOnce(&Element) -> Result<T>) -> Result<Option<T>> {
    match el.get_child(name) {
        Some(c) => f(c).map(Some),
        None => Ok(None),
    }
}

fn opt_u32(el: &Element, name: &str) -> Result<Option<u32>> {
    optional(name, el, parse_u32)
}
fn opt_u64(el: &Element, name: &str) -> Result<Option<u64>> {
    optional(name, el, parse_u64)
}
fn opt_bool(el: &Element, name: &str) -> Result<Option<bool>> {
    optional(name, el, parse_bool)
}

/// Add "In {kind} `{name}`" context to errors coming from children of `el`.
fn in_context<T>(el: &Element, kind: &str, res: Result<T>) -> Result<T> {
    res.map_err(|mut e| {
        if e.pos != el.pos {
            let name = el
                .get_child("name")
                .and_then(|n| n.text())
                .unwrap_or("")
                .to_string();
            e.contexts.push(format!("In {kind} `{name}`"));
        }
        e
    })
}

fn svd_err(el: &Element, kind: &str, msg: impl std::fmt::Display) -> SvdError {
    SvdError::at(el, format!("`{kind} error: {msg}"))
}

// ---------------------------------------------------------------------------

pub fn parse_access(el: &Element) -> Result<Access> {
    let text = el.get_text()?;
    match text.trim() {
        "read-only" => Ok(Access::ReadOnly),
        "read-write" => Ok(Access::ReadWrite),
        "read-writeOnce" => Ok(Access::ReadWriteOnce),
        "write-only" => Ok(Access::WriteOnly),
        "writeOnce" => Ok(Access::WriteOnce),
        _ => Err(SvdError::at(el, format!("unknown access variant '{text}' found"))),
    }
}

fn parse_protection(el: &Element) -> Result<Protection> {
    let text = el.get_text()?;
    match text.trim() {
        "s" => Ok(Protection::Secure),
        "n" => Ok(Protection::NonSecure),
        "p" => Ok(Protection::Privileged),
        _ => Err(SvdError::at(el, "Unknown protection variant".to_string())),
    }
}

fn parse_usage(el: &Element) -> Result<Usage> {
    let text = el.get_text()?;
    match text.trim() {
        "read" => Ok(Usage::Read),
        "write" => Ok(Usage::Write),
        "read-write" => Ok(Usage::ReadWrite),
        _ => Err(SvdError::at(el, "Unknown usage variant".to_string())),
    }
}

fn parse_endian(el: &Element) -> Result<Endian> {
    let text = el.get_text()?;
    match text.trim() {
        "little" => Ok(Endian::Little),
        "big" => Ok(Endian::Big),
        "selectable" => Ok(Endian::Selectable),
        "other" => Ok(Endian::Other),
        _ => Err(SvdError::at(el, format!("Unknown endianness `{text}`"))),
    }
}

fn parse_mwv(el: &Element) -> Result<ModifiedWriteValues> {
    use ModifiedWriteValues::*;
    let text = el.get_text()?;
    match text.trim() {
        "oneToClear" => Ok(OneToClear),
        "oneToSet" => Ok(OneToSet),
        "oneToToggle" => Ok(OneToToggle),
        "zeroToClear" => Ok(ZeroToClear),
        "zeroToSet" => Ok(ZeroToSet),
        "zeroToToggle" => Ok(ZeroToToggle),
        "clear" => Ok(Clear),
        "set" => Ok(Set),
        "modify" => Ok(Modify),
        _ => Err(SvdError::at(
            el,
            format!("Invalid modifiedWriteValues variant, found {text}"),
        )),
    }
}

fn parse_read_action(el: &Element) -> Result<ReadAction> {
    let text = el.get_text()?;
    match text.trim() {
        "clear" => Ok(ReadAction::Clear),
        "set" => Ok(ReadAction::Set),
        "modify" => Ok(ReadAction::Modify),
        "modifyExternal" => Ok(ReadAction::ModifyExternal),
        _ => Err(SvdError::at(el, "Unknown readAction variant".to_string())),
    }
}

fn parse_datatype(el: &Element) -> Result<DataType> {
    use DataType::*;
    let text = el.get_text()?;
    match text.trim() {
        "uint8_t" => Ok(U8),
        "uint16_t" => Ok(U16),
        "uint32_t" => Ok(U32),
        "uint64_t" => Ok(U64),
        "int8_t" => Ok(I8),
        "int16_t" => Ok(I16),
        "int32_t" => Ok(I32),
        "int64_t" => Ok(I64),
        "uint8_t *" => Ok(U8Ptr),
        "uint16_t *" => Ok(U16Ptr),
        "uint32_t *" => Ok(U32Ptr),
        "uint64_t *" => Ok(U64Ptr),
        "int8_t *" => Ok(I8Ptr),
        "int16_t *" => Ok(I16Ptr),
        "int32_t *" => Ok(I32Ptr),
        "int64_t *" => Ok(I64Ptr),
        _ => Err(SvdError::at(el, "Unknown datatype variant".to_string())),
    }
}

fn parse_address_block_usage(el: &Element) -> Result<AddressBlockUsage> {
    let text = el.get_text()?;
    match text.trim() {
        "registers" => Ok(AddressBlockUsage::Registers),
        "buffer" => Ok(AddressBlockUsage::Buffer),
        "reserved" => Ok(AddressBlockUsage::Reserved),
        _ => Err(SvdError::at(el, format!("unknown addressBlock usage variant '{text}' found"))),
    }
}

fn parse_write_constraint(el: &Element) -> Result<WriteConstraint> {
    let children: Vec<&Element> = el.children.iter().collect();
    if children.len() == 1 {
        let c = children[0];
        match c.name.as_str() {
            "writeAsRead" => Ok(WriteConstraint::WriteAsRead(parse_bool(c)?)),
            "useEnumeratedValues" => Ok(WriteConstraint::UseEnumeratedValues(parse_bool(c)?)),
            "range" => Ok(WriteConstraint::Range(WriteConstraintRange {
                min: c.get_child_u64("minimum")?,
                max: c.get_child_u64("maximum")?,
            })),
            _ => Err(SvdError::at(el, "Unknown write constraint".to_string())),
        }
    } else {
        Err(SvdError::at(el, "Unknown write constraint".to_string()))
    }
}

fn parse_register_properties(el: &Element) -> Result<RegisterProperties> {
    Ok(RegisterProperties {
        size: opt_u32(el, "size")?,
        access: optional("access", el, parse_access)?,
        protection: optional("protection", el, parse_protection)?,
        reset_value: opt_u64(el, "resetValue")?,
        reset_mask: opt_u64(el, "resetMask")?,
    })
}

fn parse_cpu(el: &Element, _cfg: &Config) -> Result<Cpu> {
    if el.name != "cpu" {
