fn parse_dim_index(el: &Element, text: &str) -> Result<Vec<String>> {
    let text = text.trim();
    let err = || SvdError::at(el, "Failed to parse dimIndex".to_string());
    if text.contains('-') {
        let mut parts = text.split('-');
        let start = parts.next().ok_or_else(err)?;
        let end = parts.next().ok_or_else(err)?;
        if parts.next().is_some() {
            return Err(err());
        }
        if let (Ok(s), Ok(e)) = (start.parse::<u32>(), end.parse::<u32>()) {
            if s > e {
                return Err(err());
            }
            Ok((s..=e).map(|i| i.to_string()).collect())
        } else {
            let mut sc = start.chars();
            let mut ec = end.chars();
            match (sc.next(), sc.next(), ec.next(), ec.next()) {
                (Some(s), None, Some(e), None) if s <= e => {
                    Ok((s..=e).map(|c| c.to_string()).collect())
                }
                _ => Err(err()),
            }
        }
    } else {
        Ok(text.split(',').map(|s| s.trim().to_string()).collect())
    }
}

fn parse_dim_array_index(el: &Element, cfg: &Config) -> Result<DimArrayIndex> {
    let mut values = Vec::new();
    for c in el.children_named("enumeratedValue") {
        values.push(parse_enumerated_value(c, cfg)?);
    }
    Ok(DimArrayIndex {
        header_enum_name: el.get_child_text_opt("headerEnumName")?,
        values,
    })
}

fn parse_dim_element(el: &Element, cfg: &Config) -> Result<DimElement> {
    let dim = el.get_child_u32("dim")?;
    let dim_increment = el.get_child_u32("dimIncrement")?;
    let dim_index = match el.get_child("dimIndex") {
        Some(c) => Some(parse_dim_index(c, c.get_text()?)?),
        None => None,
    };
    let dim_name = el.get_child_text_opt("dimName")?;
    let dim_array_index = optional("dimArrayIndex", el, |c| parse_dim_array_index(c, cfg))?;
    let d = DimElement {
        dim,
        dim_increment,
        dim_index,
        dim_name,
        dim_array_index,
    };
    validate::dim_element(&d, cfg.validate_level).map_err(|m| svd_err(el, "DimElement", m))?;
    Ok(d)
}

fn check_has_placeholder(el: &Element, name: &str, tag: &str) -> Result<()> {
    if name.contains("%s") {
        Ok(())
    } else {
        Err(SvdError::at(
            el,
            format!("Name `{name}` in tag `{tag}` is missing a %s placeholder"),
        ))
    }
}

fn parse_array<T>(
    tag: &str,
    el: &Element,
    cfg: &Config,
    info: impl FnOnce(&Element, &Config) -> Result<T>,
    name_of: impl Fn(&T) -> &str,
) -> Result<MaybeArray<T>> {
    let info = info(el, cfg)?;
    if el.get_child("dimIncrement").is_some() {
        let dim = parse_dim_element(el, cfg)?;
        check_has_placeholder(el, name_of(&info), tag)?;
        if let Some(indexes) = &dim.dim_index {
            if dim.dim as usize != indexes.len() {
                return Err(SvdError::at(
                    el,
                    format!(
                        "dimIndex tag must contain {} indexes, found {}",
                        dim.dim,
                        indexes.len()
                    ),
                ));
            }
        }
        Ok(MaybeArray::Array(info, dim))
    } else {
        Ok(MaybeArray::Single(info))
    }
}

fn parse_enumerated_value(el: &Element, cfg: &Config) -> Result<EnumeratedValue> {
    in_context(el, "enumeratedValue", (|| {
        if el.name != "enumeratedValue" {
            return Err(SvdError::at(el, "Expected a <enumeratedValue>, found ...".to_string()));
        }
        let ev = EnumeratedValue {
            name: el.get_child_text("name")?,
            description: el.get_child_text_opt("description")?,
            value: opt_u64(el, "value")?,
            is_default: el.get_child_bool("isDefault").ok(),
        };
        validate::enumerated_value(&ev, cfg.validate_level)
            .map_err(|m| svd_err(el, "EnumeratedValue", m))?;
        Ok(ev)
    })())
}

fn parse_enumerated_values(el: &Element, cfg: &Config) -> Result<EnumeratedValues> {
    if el.name != "enumeratedValues" {
        return Err(SvdError::at(el, "Expected a <enumeratedValues>, found ...".to_string()));
    }
    let mut values = Vec::new();
    for c in &el.children {
        if c.name == "enumeratedValue" {
            values.push(parse_enumerated_value(c, cfg)?);
        }
    }
    let evs = EnumeratedValues {
        name: el.get_child_text_opt("name")?,
        usage: optional("usage", el, parse_usage)?,
        derived_from: el.attribute("derivedFrom").map(|s| s.to_string()),
        values,
    };
    validate::enumerated_values(&evs, cfg.validate_level)
        .map_err(|m| svd_err(el, "EnumeratedValues", m))?;
    Ok(evs)
}

fn parse_bit_range(el: &Element) -> Result<BitRange> {
    let inv = |what: &str| SvdError::at(el, format!("Bit range invalid, {what}"));
    let (end, start, range_type): (u32, u32, BitRangeType) =
        if let Some(range) = el.get_child("bitRange") {
            let text = range.get_text()?;
            let text = text.trim();
            if !text.starts_with('[') {
                return Err(inv("Syntax"));
            }
            if !text.ends_with(']') {
                return Err(inv("Syntax"));
            }
            let inner = &text[1..text.len() - 1];
            let mut parts = inner.split(':');
            let end = parts
                .next()
                .ok_or_else(|| inv("Syntax"))?
                .trim()
                .parse::<u32>()
                .map_err(|_| inv("ParseError"))?;
            let start = parts
                .next()
                .ok_or_else(|| inv("Syntax"))?
                .trim()
                .parse::<u32>()
                .map_err(|_| inv("ParseError"))?;
            (end, start, BitRangeType::BitRange)
        } else if let (Some(lsb), Some(msb)) = (el.get_child("lsb"), el.get_child("msb")) {
            (parse_u32(msb)?, parse_u32(lsb)?, BitRangeType::MsbLsb)
        } else if let (Some(offset), Some(width)) =
            (el.get_child("bitOffset"), el.get_child("bitWidth"))
        {
            let offset = parse_u32(offset)?;
            let width = parse_u32(width)?;
            return Ok(BitRange {
                offset,
                width,
                range_type: BitRangeType::OffsetWidth,
            });
        } else {
            return Err(inv("Syntax"));
        };
    if end < start {
        return Err(inv("Size"));
    }
    Ok(BitRange {
        offset: start,
        width: end - start + 1,
        range_type,
    })
}

fn parse_field_info(el: &Element, cfg: &Config) -> Result<FieldInfo> {
    if el.name != "field" {
        return Err(SvdError::at(el, "Expected a <field>, found ...".to_string()));
    }
    let name = el.get_child_text("name")?;
    in_context(el, "field", (|| {
        let bit_range = parse_bit_range(el)?;
        let mut enumerated_values = Vec::new();
        for c in &el.children {
            if c.name == "enumeratedValues" {
                enumerated_values.push(parse_enumerated_values(c, cfg)?);
            }
        }
        let f = FieldInfo {
            name: name.clone(),
            description: el.get_child_text_opt("description")?,
            bit_range,
            access: optional("access", el, parse_access)?,
            modified_write_values: optional("modifiedWriteValues", el, parse_mwv)?,
            write_constraint: optional("writeConstraint", el, parse_write_constraint)?,
            read_action: optional("readAction", el, parse_read_action)?,
            enumerated_values,
            derived_from: el.attribute("derivedFrom").map(|s| s.to_string()),
        };
        validate::field(&f, cfg.validate_level).map_err(|(k, m)| svd_err(el, k, m))?;
        Ok(f)
    })())
}

fn parse_field(el: &Element, cfg: &Config) -> Result<Field> {
    parse_array("field", el, cfg, parse_field_info, |f| &f.name)
}

fn parse_register_info(el: &Element, cfg: &Config) -> Result<RegisterInfo> {
    if el.name != "register" {
        return Err(SvdError::at(el, "Expected a <register>, found ...".to_string()));
    }
    let name = el.get_child_text("name")?;
    in_context(el, "register", (|| {
        let properties = parse_register_properties(el)?;
        let fields = match el.get_child("fields") {
            Some(fs) => {
                let mut v = Vec::new();
                for c in &fs.children {
                    v.push(parse_field(c, cfg)?);
