        };
        let r = RegisterInfo {
            name: name.clone(),
            display_name: el.get_child_text_opt("displayName")?,
            description: el.get_child_text_opt("description")?,
            alternate_group: el.get_child_text_opt("alternateGroup")?,
            alternate_register: el.get_child_text_opt("alternateRegister")?,
            address_offset: el.get_child_u32("addressOffset")?,
            properties,
            datatype: optional("dataType", el, parse_datatype)?,
            modified_write_values: optional("modifiedWriteValues", el, parse_mwv)?,
            write_constraint: optional("writeConstraint", el, parse_write_constraint)?,
            read_action: optional("readAction", el, parse_read_action)?,
            fields,
            derived_from: el.attribute("derivedFrom").map(|s| s.to_string()),
        };
        validate::register(&r, cfg.validate_level).map_err(|(k, m)| svd_err(el, k, m))?;
