}

fn parse_register_cluster(el: &Element, cfg: &Config) -> Result<RegisterCluster> {
    match el.name.as_str() {
        "register" => Ok(RegisterCluster::Register(parse_register(el, cfg)?)),
        "cluster" => Ok(RegisterCluster::Cluster(parse_cluster(el, cfg)?)),
        other => Err(SvdError::at(
            el,
            format!("Invalid RegisterCluster (expected register or cluster), found {other}"),
        )),
    }
}

fn parse_peripheral_info(el: &Element, cfg: &Config) -> Result<PeripheralInfo> {
    if el.name != "peripheral" {
        return Err(SvdError::at(el, "Expected a <peripheral>, found ...".to_string()));
    }
    let name = el.get_child_text("name")?;
    in_context(el, "peripheral", (|| {
        let mut interrupt = Vec::new();
        for c in el.children_named("interrupt") {
            interrupt.push(parse_interrupt(c, cfg)?);
        }
        let address_block = {
            let v: Vec<AddressBlock> = el
                .children_named("addressBlock")
                .map(|c| parse_address_block(c, cfg))
                .collect::<Result<_>>()?;
            if v.is_empty() {
                None
            } else {
                Some(v)
            }
        };
        let registers = match el.get_child("registers") {
            Some(rs) => {
                let mut v = Vec::new();
                for c in &rs.children {
                    v.push(parse_register_cluster(c, cfg)?);
                }
                Some(v)
            }
            None => None,
        };
        let p = PeripheralInfo {
            name: name.clone(),
            display_name: el.get_child_text_opt("displayName")?,
            version: el.get_child_text_opt("version")?,
            description: el.get_child_text_opt("description")?,
            alternate_peripheral: el.get_child_text_opt("alternatePeripheral")?,
            group_name: el.get_child_text_opt("groupName")?,
            prepend_to_name: el.get_child_text_opt("prependToName")?,
            append_to_name: el.get_child_text_opt("appendToName")?,
            header_struct_name: el.get_child_text_opt("headerStructName")?,
            base_address: el.get_child_u64("baseAddress")?,
            default_register_properties: parse_register_properties(el)?,
            address_block,
            interrupt,
            registers,
            derived_from: el.attribute("derivedFrom").map(|s| s.to_string()),
        };
        validate::peripheral(&p, cfg.validate_level).map_err(|(k, m)| svd_err(el, k, m))?;
        Ok(p)
    })())
}

fn parse_peripheral(el: &Element, cfg: &Config) -> Result<Peripheral> {
    parse_array("peripheral", el, cfg, parse_peripheral_info, |p| &p.name)
}

fn parse_device(el: &Element, cfg: &Config) -> Result<Device> {
    if el.name != "device" {
        return Err(SvdError::at(el, "Expected a <device>, found ...".to_string()));
    }
    let name = el.get_child_text("name")?;
    in_context(el, "device", (|| {
        let peripherals = {
            let ps = el.get_child_elem("peripherals")?;
