            header_system_filename: el.get_child_text_opt("headerSystemFilename")?,
            header_definitions_prefix: el.get_child_text_opt("headerDefinitionsPrefix")?,
            address_unit_bits: opt_u32(el, "addressUnitBits")?,
            width: opt_u32(el, "width")?,
