pub fn parse_with_config(xml: &str, cfg: &Config) -> anyhow::Result<Device> {
    let doc: Document = xml::parse(xml).map_err(|e| anyhow::anyhow!("{e}"))?;
    let root = &doc.root;
    if root.name != "device" {
        // roxmltree root node is the document; `get_child("device")` on it
        let err = SvdError {
            pos: 0,
            tag: String::new(),
            name: None,
            msg: "Expected a <device> tag, found none".to_string(),
            contexts: vec![],
        };
        return Err(to_anyhow(&doc, err, false));
    }
    match parse_device(root, cfg) {
        Ok(d) => Ok(d),
        Err(e) => Err(to_anyhow(&doc, e, true)),
    }
}

fn to_anyhow(doc: &Document, e: SvdError, with_pos: bool) -> anyhow::Error {
    let mut err = anyhow::anyhow!("{}", e.msg);
    if with_pos {
        let pos = doc.text_pos_at(e.pos);
        let ctx = match &e.name {
            Some(n) => format!("Parsing {} `{}` at {}", e.tag, n, pos),
            None => format!("Parsing unknown {} at {}", e.tag, pos),
        };
        err = err.context(ctx);
    }
    for c in e.contexts {
        err = err.context(c);
    }
    err
}
