//! Validation rules (svd-rs compatible)

use super::*;

pub type VResult = std::result::Result<(), (&'static str, String)>;

fn is_name_char(c: char) -> bool {
    c == '_' || c.is_ascii_alphanumeric()
}

fn is_name_start(c: char) -> bool {
    c == '_' || c.is_ascii_alphabetic()
}

/// `^[_A-Za-z0-9]*$`
pub fn check_name(name: &str) -> std::result::Result<(), (&'static str, String)> {
    if name.chars().all(is_name_char) {
        Ok(())
    } else {
        Err(("Name check", format!("Name `{name}` contains unexpected symbol")))
    }
}

/// `^(((%s)|(%s)[_A-Za-z]{1}[_A-Za-z0-9]*)|([_A-Za-z]{1}[_A-Za-z0-9]*(\[%s\])?)|([_A-Za-z]{1}[_A-Za-z0-9]*(%s)?[_A-Za-z0-9]*))$`
pub fn check_dimable_name(name: &str) -> std::result::Result<(), (&'static str, String)> {
    let ok = dimable_ok(name);
    if ok {
        Ok(())
    } else {
        Err(("Name check", format!("Name `{name}` contains unexpected symbol")))
    }
}

fn ident_like(s: &str) -> bool {
    let mut chars = s.chars();
    match chars.next() {
        Some(c) if is_name_start(c) => chars.all(is_name_char),
        _ => false,
    }
}

fn dimable_ok(name: &str) -> bool {
    if name == "%s" {
        return true;
    }
    if let Some(rest) = name.strip_prefix("%s") {
        if ident_like(rest) {
            return true;
        }
    }
    if let Some(rest) = name.strip_suffix("[%s]") {
        if ident_like(rest) {
            return true;
        }
    }
    if ident_like(name) {
        return true;
    }
    // [_A-Za-z]{1}[_A-Za-z0-9]*(%s)?[_A-Za-z0-9]*
    if let Some(idx) = name.find("%s") {
        let (a, b) = name.split_at(idx);
        let b = &b[2..];
        if ident_like(a) && b.chars().all(is_name_char) && !b.contains("%s") {
            return true;
        }
    }
    false
}

pub fn check_derived_name(name: &str) -> std::result::Result<(), (&'static str, String)> {
    for x in name.split('.') {
        check_dimable_name(x)?;
    }
    Ok(())
}

pub fn device(d: &Device, lvl: ValidateLevel) -> VResult {
    if lvl.is_strict() {
        check_name(&d.name)?;
        if d.version.is_none() {
            return Err(("Build", "`version` must be initialized".into()));
        }
        if d.description.is_none() {
            return Err(("Build", "`description` must be initialized".into()));
        }
        if d.address_unit_bits.is_none() {
            return Err(("Build", "`addressUnitBits` must be initialized".into()));
        }
        if d.width.is_none() {
            return Err(("Build", "`width` must be initialized".into()));
        }
    }
    if !lvl.is_disabled() && d.peripherals.is_empty() {
        return Err(("Device", "Device must contain at least one peripheral".into()));
    }
    Ok(())
}

pub fn peripheral(p: &PeripheralInfo, lvl: ValidateLevel) -> VResult {
    if lvl.is_disabled() {
        return Ok(());
    }
    if lvl.is_strict() {
        check_dimable_name(&p.name)?;
        if let Some(name) = p.derived_from.as_ref() {
            check_derived_name(name)?;
        } else if let Some(registers) = p.registers.as_ref() {
            if registers.is_empty() {
                return Err((
                    "Peripheral",
                    "Peripheral have `registers` tag, but it is empty".into(),
                ));
            }
        }
    }
    Ok(())
}

pub fn cluster(c: &ClusterInfo, lvl: ValidateLevel) -> VResult {
    if lvl.is_disabled() {
        return Ok(());
    }
    if lvl.is_strict() {
        check_dimable_name(&c.name)?;
        if let Some(name) = c.derived_from.as_ref() {
            check_derived_name(name)?;
        } else if c.children.is_empty() {
            return Err((
                "Cluster",
                "Cluster must contain at least one Register or Cluster".into(),
            ));
        }
    }
    Ok(())
}

pub fn register(r: &RegisterInfo, lvl: ValidateLevel) -> VResult {
    if lvl.is_disabled() {
        return Ok(());
    }
    if lvl.is_strict() {
        check_dimable_name(&r.name)?;
        if let Some(name) = r.alternate_group.as_ref() {
            check_name(name)?;
        }
        if let Some(name) = r.alternate_register.as_ref() {
            check_dimable_name(name)?;
        }
        if let Some(name) = r.derived_from.as_ref() {
            check_derived_name(name)?;
        } else if let Some(fields) = r.fields.as_ref() {
            if fields.is_empty() {
                return Err((
                    "Register",
