    if lvl.is_disabled() {
        return Ok(());
    }
    if lvl.is_strict() {
        check_name(&e.name)?;
    }
    if e.value.is_none() && e.is_default.is_none() {
        return Err((
            "EnumeratedValue",
            "EnumeratedValue has no `value` or `is_default`".into(),
        ));
    }
    Ok(())
}

pub fn interrupt(_i: &Interrupt, _lvl: ValidateLevel) -> std::result::Result<(), String> {
    Ok(())
}

pub fn dim_element(d: &DimElement, lvl: ValidateLevel) -> std::result::Result<(), String> {
