use std::borrow::Cow;
use std::collections::HashMap;

use proc_macro2::{Ident, Literal, Span, TokenStream};
use quote::{quote, ToTokens};

pub use crate::config::{Case, Config, IdentFormat, IdentFormats, Target};
use crate::svd::{Access, Field, RegisterInfo, RegisterProperties};

pub const BITS_PER_BYTE: u32 = 8;

/// List of chars that some vendors use in their peripheral/field names but
/// that are not valid in Rust ident
pub const BLACKLIST_CHARS: &[char] = &['(', ')', '[', ']', '/', ' ', '-'];

const KEYWORDS: &[&str] = &[
    "abstract", "alignof", "as", "async", "await", "become", "box", "break", "const", "continue",
    "crate", "do", "dyn", "else", "enum", "extern", "false", "final", "fn", "for", "gen", "if",
    "impl", "in", "let", "loop", "macro", "match", "mod", "move", "mut", "offsetof", "override",
    "priv", "proc", "pub", "pure", "ref", "return", "self", "sizeof", "static", "struct", "super",
    "trait", "true", "try", "type", "typeof", "unsafe", "unsized", "use", "virtual", "where",
    "while", "yield", "set_bit", "clear_bit", "bit", "bits",
];

pub fn sanitize_keyword(sc: Cow<str>) -> Cow<str> {
    if KEYWORDS.contains(&sc.as_ref()) {
        sc + "_"
    } else {
        sc
    }
}

// ---------------------------------------------------------------------------
// Case conversion (inflections-like semantics)

fn is_pascal_case(s: &str) -> bool {
    let mut prev: Option<char> = None;
    for (i, c) in s.chars().enumerate() {
        if i == 0 {
            if c.is_lowercase() {
                return false;
            }
        } else if c == '_' {
            return false;
        }
        if c.is_uppercase() {
            if let Some(p) = prev {
                if p.is_uppercase() || p.is_ascii_digit() {
                    return false;
                }
            }
        }
        prev = Some(c);
    }
    true
}

fn capitalize(w: &str) -> String {
    let mut out = String::with_capacity(w.len());
    let mut chars = w.chars();
    if let Some(c) = chars.next() {
        out.extend(c.to_uppercase());
    }
    for c in chars {
        out.extend(c.to_lowercase());
    }
    out
}

fn split_lower_upper(piece: &str) -> Vec<String> {
    let mut words = Vec::new();
    let mut cur = String::new();
    let mut prev: Option<char> = None;
    for c in piece.chars() {
        if let Some(p) = prev {
            if c.is_uppercase() && p.is_lowercase() {
                words.push(std::mem::take(&mut cur));
            }
        }
        cur.push(c);
        prev = Some(c);
    }
    if !cur.is_empty() {
        words.push(cur);
    }
    words
}

fn convert_pascal(s: &str) -> String {
    let mut out = String::new();
    for piece in s.split('_') {
        if piece.is_empty() {
            if !out.ends_with('_') {
                out.push('_');
            }
            continue;
        }
        for w in split_lower_upper(piece) {
            let starts_digit = w.chars().next().map_or(false, |c| c.is_ascii_digit());
            if starts_digit && out.chars().last().map_or(false, |c| c.is_ascii_digit()) {
                out.push('_');
            }
            out.push_str(&capitalize(&w));
        }
    }
    out
}

pub fn to_pascal_case(s: &str) -> Cow<str> {
    if is_pascal_case(s) {
        Cow::Borrowed(s)
    } else {
        Cow::Owned(convert_pascal(s))
    }
}

pub fn to_snake_case(s: &str) -> Cow<str> {
    let mut out = String::with_capacity(s.len() + 4);
    let mut prev: Option<char> = None;
    let mut changed = false;
    for c in s.chars() {
        if c.is_uppercase() {
            if let Some(p) = prev {
                if p.is_lowercase() {
                    out.push('_');
                }
            }
            out.extend(c.to_lowercase());
            changed = true;
        } else {
            out.push(c);
        }
        prev = Some(c);
    }
    if changed {
        Cow::Owned(out)
    } else {
        Cow::Borrowed(s)
    }
}

pub fn to_constant_case(s: &str) -> Cow<str> {
    let snake = to_snake_case(s);
    if snake.chars().any(|c| c.is_lowercase()) {
        Cow::Owned(snake.to_uppercase())
    } else {
        snake
    }
}

impl Case {
    pub fn cow_to_case<'a>(&self, cow: Cow<'a, str>) -> Cow<'a, str> {
        match self {
            Case::Constant => match cow {
                Cow::Borrowed(s) => to_constant_case(s),
                Cow::Owned(s) => Cow::Owned(to_constant_case(&s).into_owned()),
            },
            Case::Pascal => match cow {
                Cow::Borrowed(s) => to_pascal_case(s),
                Cow::Owned(s) => Cow::Owned(to_pascal_case(&s).into_owned()),
            },
            Case::Snake => match cow {
                Cow::Borrowed(s) => to_snake_case(s),
                Cow::Owned(s) => Cow::Owned(to_snake_case(&s).into_owned()),
            },
        }
    }

    pub fn sanitize<'a>(&self, s: &'a str) -> Cow<'a, str> {
        let s = sanitize_chars(s);
        self.cow_to_case(s)
    }
}

pub fn sanitize_chars(s: &str) -> Cow<str> {
    if s.contains(BLACKLIST_CHARS) {
        Cow::Owned(s.replace(BLACKLIST_CHARS, ""))
    } else {
        Cow::Borrowed(s)
    }
}

impl IdentFormat {
    pub fn apply<'a>(&self, name: &'a str) -> Cow<'a, str> {
        let name = match &self.case {
            Some(case) => case.sanitize(name),
            None => sanitize_chars(name),
        };
        if self.prefix.is_empty() && self.suffix.is_empty() {
            name
        } else {
            Cow::Owned(format!("{}{}{}", self.prefix, name, self.suffix))
        }
    }
}

pub fn ident_str(name: &str, config: &Config, fmt_type: &str) -> String {
    let fmt = config
        .ident_formats
        .get(fmt_type)
        .cloned()
        .unwrap_or_default();
    let s = fmt.apply(name);
    let s = match s.chars().next().unwrap_or('\0') {
        '0'..='9' => Cow::Owned(format!("_{s}")),
        _ => s,
    };
    sanitize_keyword(s).into_owned()
}

pub fn ident(name: &str, config: &Config, fmt_type: &str, span: Span) -> Ident {
    Ident::new(&ident_str(name, config, fmt_type), span)
}

// ---------------------------------------------------------------------------

pub trait ToSanitizedCase {
    fn to_sanitized_pascal_case(&self) -> Cow<str>;
    fn to_sanitized_constant_case(&self) -> Cow<str>;
    fn to_sanitized_snake_case(&self) -> Cow<str>;
}

impl ToSanitizedCase for str {
    fn to_sanitized_pascal_case(&self) -> Cow<str> {
        let s = Case::Pascal.sanitize(self);
        match s.chars().next().unwrap_or('\0') {
            '0'..='9' => Cow::Owned(format!("_{s}")),
            _ => s,
        }
    }
    fn to_sanitized_constant_case(&self) -> Cow<str> {
        let s = Case::Constant.sanitize(self);
        match s.chars().next().unwrap_or('\0') {
            '0'..='9' => Cow::Owned(format!("_{s}")),
            _ => s,
        }
    }
    fn to_sanitized_snake_case(&self) -> Cow<str> {
        let s = Case::Snake.sanitize(self);
        let s = match s.chars().next().unwrap_or('\0') {
            '0'..='9' => Cow::Owned(format!("_{s}")),
            _ => s,
        };
        sanitize_keyword(s)
    }
}

pub fn respace(s: &str) -> String {
    s.split_whitespace().collect::<Vec<_>>().join(" ")
}

pub fn escape_brackets(s: &str) -> String {
    let s = s.split('[').fold("".to_string(), |acc, x| {
        if acc.is_empty() {
            x.to_string()
        } else if acc.ends_with('\\') {
            format!("{acc}[{x}")
        } else {
            format!("{acc}\\[{x}")
        }
    });
    s.split(']').fold("".to_string(), |acc, x| {
        if acc.is_empty() {
            x.to_string()
        } else if acc.ends_with('\\') {
            format!("{acc}]{x}")
        } else {
            format!("{acc}\\]{x}")
        }
    })
}

/// Escape basic html tags and brackets
pub fn escape_special_chars(s: &str) -> String {
    escape_brackets(s)
}

pub fn name_of<T: FullName>(maybe_array: &T, ignore_group: bool) -> Cow<str> {
    maybe_array.fullname(ignore_group)
}

pub trait FullName {
    fn fullname(&self, ignore_group: bool) -> Cow<str>;
}

impl FullName for RegisterInfo {
    fn fullname(&self, ignore_group: bool) -> Cow<str> {
        match &self.alternate_group {
            Some(group) if !ignore_group => format!("{group}_{}", self.name).into(),
            _ => self.name.as_str().into(),
        }
    }
}

impl FullName for crate::svd::PeripheralInfo {
    fn fullname(&self, _ignore_group: bool) -> Cow<str> {
        self.name.as_str().into()
    }
}

impl FullName for crate::svd::ClusterInfo {
    fn fullname(&self, _ignore_group: bool) -> Cow<str> {
        self.name.as_str().into()
    }
}

impl FullName for crate::svd::FieldInfo {
    fn fullname(&self, _ignore_group: bool) -> Cow<str> {
        self.name.as_str().into()
    }
}

pub fn access_of(properties: &RegisterProperties, fields: Option<&[Field]>) -> Access {
    properties.access.unwrap_or_else(|| {
        if let Some(fields) = fields {
            if fields.iter().all(|f| f.access == Some(Access::ReadOnly)) {
                Access::ReadOnly
            } else if fields.iter().all(|f| f.access == Some(Access::WriteOnly)) {
                Access::WriteOnly
            } else if fields.iter().all(|f| f.access == Some(Access::ReadWriteOnce)) {
                Access::ReadWriteOnce
            } else {
                Access::ReadWrite
            }
        } else {
            Access::ReadWrite
        }
    })
}

pub fn digit_or_hex(n: u64) -> Literal {
    if n < 10 {
        unsuffixed(n)
    } else {
        hex(n)
    }
}

/// Turns `n` into an unsuffixed separated hex token
pub fn hex(n: u64) -> Literal {
    let (h4, h3, h2, h1) = (
        (n >> 48) & 0xffff,
        (n >> 32) & 0xffff,
        (n >> 16) & 0xffff,
        n & 0xffff,
    );
    let s = if h4 != 0 {
        format!("0x{h4:04x}_{h3:04x}_{h2:04x}_{h1:04x}")
    } else if h3 != 0 {
        format!("0x{h3:04x}_{h2:04x}_{h1:04x}")
    } else if h2 != 0 {
        format!("0x{h2:04x}_{h1:04x}")
    } else if h1 & 0xff00 != 0 {
        format!("0x{h1:04x}")
    } else if h1 != 0 {
        format!("0x{:02x}", h1 & 0xff)
    } else {
        "0".to_string()
    };
    syn_lit(&s)
}

fn syn_lit(s: &str) -> Literal {
    s.parse::<Literal>().unwrap()
}

/// Turns `n` into an unsuffixed token
pub fn unsuffixed(n: u64) -> Literal {
    Literal::u64_unsuffixed(n)
}

pub fn unsuffixed_or_bool(n: u64, width: u32) -> TokenStream {
    if width == 1 {
        let b = n != 0;
        quote!(#b)
    } else {
        let lit = unsuffixed(n);
        quote!(#lit)
    }
}

pub trait U32Ext {
    fn size_to_str(&self) -> anyhow::Result<&str>;
    fn to_ty(&self) -> anyhow::Result<Ident>;
    fn to_ty_width(&self) -> anyhow::Result<u32>;
}

impl U32Ext for u32 {
    fn size_to_str(&self) -> anyhow::Result<&str> {
        Ok(match *self {
            8 => "u8",
            16 => "u16",
            32 => "u32",
            64 => "u64",
            _ => {
                return Err(anyhow::anyhow!(
                    "can't convert {self} bits into register size type"
                ))
            }
        })
    }

    fn to_ty(&self) -> anyhow::Result<Ident> {
        Ok(Ident::new(
            match *self {
                1 => "bool",
                2..=8 => "u8",
                9..=16 => "u16",
