/// Turns `n` into an unsuffixed separated hex token
pub fn hex(n: u64) -> Literal {
    let (h4, h3, h2, h1) = (
        (n >> 48) & 0xffff,
        (n >> 32) & 0xffff,
        (n >> 16) & 0xffff,
        n & 0xffff,
    );
    let s = if h4 != 0 {
        format!("0x{h4:04x}_{h3:04x}_{h2:04x}_{h1:04x}")
    } else if h3 != 0 {
        format!("0x{h3:04x}_{h2:04x}_{h1:04x}")
    } else if h2 != 0 {
        format!("0x{h2:04x}_{h1:04x}")
    } else if h1 & 0xff00 != 0 {
        format!("0x{h1:04x}")
    } else if h1 != 0 {
        format!("0x{:02x}", h1 & 0xff)
    } else {
        "0".to_string()
    };
    syn_lit(&s)
