use crate::svd::Peripheral;
use proc_macro2::{Ident, Span, TokenStream};
use quote::quote;
use std::collections::BTreeMap;
use std::fmt::Write;

use crate::util::{self, ident, Config, Target, ToSanitizedCase};
use anyhow::Result;

/// Generates code for `src/interrupt.rs`
pub fn render(
    target: Target,
    peripherals: &[Peripheral],
    device_x: &mut String,
    config: &Config,
) -> Result<TokenStream> {
    let interrupts = {
        let mut interrupts = BTreeMap::new();
        for p in peripherals {
            for i in &p.interrupt {
                interrupts.insert(i.value, (i, p));
            }
        }
        interrupts.into_values().collect::<Vec<_>>()
    };

    let mut root = TokenStream::new();
    let mut from_arms = TokenStream::new();
    let mut elements = TokenStream::new();
    let mut names = vec![];
    let mut names_cfg_attr = vec![];
    let mut variants = TokenStream::new();

    // Current position in the vector table
    let mut pos = 0;
    let mut mod_items = TokenStream::new();
    for (interrupt, p) in &interrupts {
        while pos < interrupt.value {
            elements.extend(quote!(Vector { _reserved: 0 },));
            pos += 1;
        }
        pos += 1;

        let i_ty = ident(&interrupt.name, config, "interrupt", Span::call_site());
        let description = format!(
            "{} - {}",
            interrupt.value,
            interrupt
                .description
                .as_ref()
                .map(|s| util::respace(s))
                .as_ref()
                .map(|s| util::escape_special_chars(s))
                .unwrap_or_else(|| interrupt.name.clone())
        );

        let value = util::unsuffixed(interrupt.value as u64);

        let mut feature_attribute_flag = false;
        let mut feature_attribute = TokenStream::new();
        let mut not_feature_attribute = TokenStream::new();
        if config.feature_group && p.group_name.is_some() {
            let feature_name = p.group_name.as_ref().unwrap().to_sanitized_snake_case();
            feature_attribute.extend(quote! { #[cfg(feature = #feature_name)] });
            not_feature_attribute.extend(quote! { feature = #feature_name, });
            feature_attribute_flag = true;
        }
        if config.feature_peripheral {
            let feature_name = p.name.to_sanitized_snake_case();
            feature_attribute.extend(quote! { #[cfg(feature = #feature_name)] });
            not_feature_attribute.extend(quote! { feature = #feature_name, });
            feature_attribute_flag = true;
        }

        variants.extend(quote! {
            #[doc = #description]
            #feature_attribute
            #i_ty = #value,
        });

        from_arms.extend(quote! {
            #feature_attribute
            #value => Ok(Interrupt::#i_ty),
