//! Paths & index for derivedFrom resolution (svd-rs compatible)

use std::collections::HashMap;

use crate::svd::*;
use crate::util::replace_suffix;

#[derive(Clone, Debug, PartialEq, Eq, Hash)]
pub struct BlockPath {
    pub peripheral: String,
    pub path: Vec<String>,
}

impl BlockPath {
    pub fn new(p: impl Into<String>) -> Self {
        Self {
            peripheral: p.into(),
            path: Vec::new(),
        }
    }
    pub fn new_cluster(&self, name: impl Into<String>) -> Self {
        let mut p = self.clone();
        p.path.push(name.into());
        p
    }
    pub fn new_register(&self, name: impl Into<String>) -> RegisterPath {
        RegisterPath::new(self.clone(), name)
    }
    pub fn parse_str(s: &str) -> (Option<Self>, &str) {
        if let Some((block, name)) = s.rsplit_once('.') {
            let mut it = block.split('.');
            let mut path = Self::new(it.next().unwrap());
            for p in it {
                path = path.new_cluster(p);
            }
            (Some(path), name)
        } else {
            (None, s)
        }
    }
    pub fn parent(&self) -> Option<Self> {
        let mut p = self.clone();
        p.path.pop()?;
        Some(p)
    }
    pub fn name(&self) -> &str {
        self.path.last().unwrap_or(&self.peripheral)
    }
}

impl std::fmt::Display for BlockPath {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.write_str(&self.peripheral)?;
        for p in &self.path {
            f.write_str(".")?;
            f.write_str(p)?;
        }
        Ok(())
    }
}

#[derive(Clone, Debug, PartialEq, Eq, Hash)]
pub struct RegisterPath {
    pub block: BlockPath,
    pub name: String,
}

impl RegisterPath {
    pub fn new(block: BlockPath, name: impl Into<String>) -> Self {
        Self {
            block,
            name: name.into(),
        }
    }
    pub fn new_field(&self, name: impl Into<String>) -> FieldPath {
        FieldPath::new(self.clone(), name)
    }
    pub fn parse_str(s: &str) -> (Option<BlockPath>, &str) {
        BlockPath::parse_str(s)
    }
    pub fn parse_vec(v: Vec<&str>) -> (Option<BlockPath>, String) {
        let mut v = v;
        let name = v.pop().unwrap().to_string();
        if v.is_empty() {
            (None, name)
        } else {
            let mut it = v.into_iter();
            let mut path = BlockPath::new(it.next().unwrap());
            for p in it {
                path = path.new_cluster(p);
            }
            (Some(path), name)
        }
    }
    pub fn peripheral(&self) -> &str {
        &self.block.peripheral
    }
}

impl std::fmt::Display for RegisterPath {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        write!(f, "{}.{}", self.block, self.name)
    }
}

#[derive(Clone, Debug, PartialEq, Eq, Hash)]
pub struct FieldPath {
    pub register: RegisterPath,
    pub name: String,
