fn field_accessor(name: &str, config: &Config, span: Span) -> Ident {
    const INTERNALS: [&str; 2] = ["set", "bits"];
    let sc = util::ident_str(name, config, "field_accessor");
    let sc = if INTERNALS.contains(&sc.as_str()) {
        format!("{sc}_")
