    let sc = util::ident_str(name, config, "enum_value_accessor");
    let sc = if writer && INTERNALS.contains(&sc.as_str()) {
        format!("{sc}_")
    } else {
        sc
    };
    Ident::new(&sc, span)
}

pub fn render(
    register: &Register,
    path: &BlockPath,
    dpath: Option<RegisterPath>,
    index: &Index,
    config: &Config,
) -> Result<TokenStream> {
    let mut name = util::name_of(&**register, config.ignore_groups);
    // Rename if this is a derived array
    if dpath.is_some() {
        if let MaybeArray::Array(info, array_info) = register {
            if let Some(dim_index) = &array_info.dim_index {
                let index: Cow<str> = dim_index.first().unwrap().into();
                name = info
                    .fullname(config.ignore_groups)
                    .replace("%s", &index)
                    .into();
            }
        }
    }
    let name = util::replace_suffix(&name, "");
    let span = Span::call_site();
    let reg_ty = ident(&name, config, "register", span);
    let doc_alias = (reg_ty.to_string().as_str() != name).then(|| quote!(#[doc(alias = #name)]));
    let mod_ty = ident(&name, config, "register_mod", span);
    let description = util::escape_special_chars(&util::respace(
        &register.description.clone().unwrap_or_else(|| {
            warn!("Missing description for register {}", register.name);
            Default::default()
        }),
    ));

    if let Some(dpath) = dpath.as_ref() {
        let mut derived = if &dpath.block == path {
            type_path(Punctuated::new())
        } else {
            util::block_path_to_ty(&dpath.block, config, span)
        };
        let dname = util::replace_suffix(
            &util::name_of(&***index.registers.get(dpath).unwrap(), config.ignore_groups),
            "",
        );
        let mut mod_derived = derived.clone();
        derived
            .path
            .segments
            .push(path_segment(ident(&dname, config, "register", span)));
        mod_derived
            .path
            .segments
            .push(path_segment(ident(&dname, config, "register_mod", span)));

        Ok(quote! {
            pub use #derived as #reg_ty;
            pub use #mod_derived as #mod_ty;
        })
    } else {
        let access = util::access_of(&register.properties, register.fields.as_deref());
        let accs = if access.can_read() && access.can_write() {
            "rw"
        } else if access.can_write() {
            "w"
        } else if access.can_read() {
            "r"
        } else {
            return Err(anyhow!(
                "Register {} has invalid access {:?}",
                register.name,
                access
            ));
        };

        let alias_doc = format!(
            "{name} ({accs}) register accessor: {description}{}",
            api_docs(
                access.can_read(),
                access.can_write(),
                register.properties.reset_value.is_some(),
                &mod_ty,
                false,
                register.read_action,
            )?
        );
        let mut out = TokenStream::new();
        let regspec_ty = regspec(&name, config, span);
        out.extend(quote! {
            #[doc = #alias_doc]
            #doc_alias
            pub type #reg_ty = crate::Reg<#mod_ty::#regspec_ty>;
        });
        let mod_items = render_register_mod(
            register,
            access,
            &name,
            &path.new_register(&register.name),
            index,
            config,
        )?;

        let open = Punct::new('{', Spacing::Alone);
        let close = Punct::new('}', Spacing::Alone);
        out.extend(quote! {
            #[doc = #description]
            pub mod #mod_ty #open
        });
        out.extend(mod_items);
        close.to_tokens(&mut out);

        Ok(out)
    }
}

fn api_docs(
    can_read: bool,
    can_write: bool,
    can_reset: bool,
    module: &Ident,
    inmodule: bool,
    read_action: Option<ReadAction>,
) -> Result<String, std::fmt::Error> {
    fn method(s: &str) -> String {
        format!("[`{s}`](crate::Reg::{s})")
    }

    let mut doc = String::from("\n\n");

    if can_read {
        write!(
            doc,
            "You can {} this register and get [`{module}::R`]{}. ",
            method("read"),
            if inmodule { "(R)" } else { "" }
        )?;
    }

    if can_write {
        let mut methods = Vec::new();
        if can_reset {
            methods.push("reset");
            methods.push("write");
        }
        methods.push("write_with_zero");
        write!(
            doc,
            "You can {} this register using [`{module}::W`]{}. ",
            methods
                .iter()
                .map(|m| method(m))
                .collect::<Vec<_>>()
                .join(", "),
            if inmodule { "(W)" } else { "" }
        )?;
    }

    if can_read && can_write {
        write!(doc, "You can also {} this register. ", method("modify"))?;
    }

    doc.push_str("See [API](https://docs.rs/svd2rust/#read--modify--write-api).");

    if let Some(action) = read_action {
        doc.push_str("\n\n<div class=\"warning\">");
        doc.push_str(match action {
            ReadAction::Clear => "The register is <b>cleared</b> (set to zero) following a read operation.",
            ReadAction::Set => "The register is <b>set</b> (set to ones) following a read operation.",
            ReadAction::Modify => "The register is <b>modified</b> in some way after a read operation.",
            ReadAction::ModifyExternal => "One or more dependent resources other than the current register are immediately affected by a read operation.",
        });
        doc.push_str("</div>");
    }

    if !inmodule {
        write!(
            doc,
            "\n\nFor information about available fields see [`mod@{module}`] module"
        )?;
    }
    Ok(doc)
}

pub fn render_register_mod(
    register: &Register,
    access: Access,
    name: &str,
    rpath: &RegisterPath,
    index: &Index,
    config: &Config,
) -> Result<TokenStream> {
    let properties = &register.properties;
    let span = Span::call_site();
    let regspec_ty = regspec(name, config, span);
    let mod_ty = ident(name, config, "register_mod", span);
    let rsize = properties
        .size
        .ok_or_else(|| anyhow!("Register {} has no `size` field", register.name))?;
    let rsize = if rsize < 8 {
        8
    } else if rsize.is_power_of_two() {
        rsize
    } else {
        rsize.next_power_of_two()
    };
    let rty = rsize.to_ty()?;
    let description = util::escape_special_chars(&util::respace(
        &register.description.clone().unwrap_or_else(|| {
            warn!("Missing description for register {}", register.name);
            Default::default()
        }),
    ));

    let mut mod_items = TokenStream::new();

    let can_read = access.can_read();
    let can_write = access.can_write();
    let can_reset = properties.reset_value.is_some();

    if can_read {
        let desc = format!("Register `{}` reader", register.name);
        mod_items.extend(quote! {
            #[doc = #desc]
            pub type R = crate::R<#regspec_ty>;
        });
    }

    if can_write {
        let desc = format!("Register `{}` writer", register.name);
        mod_items.extend(quote! {
            #[doc = #desc]
            pub type W = crate::W<#regspec_ty>;
        });
    }

    let mut r_impl_items = TokenStream::new();
    let mut r_debug_impl = TokenStream::new();
    let mut w_impl_items = TokenStream::new();
    let mut zero_to_modify_fields_bitmap = 0;
    let mut one_to_modify_fields_bitmap = 0;

    let debug_feature = config
        .impl_debug_feature
        .as_ref()
        .map(|feature| quote!(#[cfg(feature=#feature)]));

    if let Some(cur_fields) = register.fields.as_ref() {
        // filter out all reserved fields, as we should not generate code for them
        let cur_fields: Vec<&Field> = cur_fields
            .iter()
            .filter(|field| field.name.to_lowercase() != "reserved")
            .collect();

        if !cur_fields.is_empty() {
            if config.impl_debug {
                r_debug_impl.extend(render_register_mod_debug(
                    register,
                    &access,
                    &cur_fields,
                    name,
                    &regspec_ty,
                    config,
                )?)
            }
            (
                r_impl_items,
                w_impl_items,
                zero_to_modify_fields_bitmap,
                one_to_modify_fields_bitmap,
            ) = fields(
                cur_fields,
                &regspec_ty,
                register.modified_write_values,
                access,
                properties,
                &mut mod_items,
                rpath,
                index,
                config,
            )?;
        }
    } else if !access.can_read() || register.read_action.is_some() {
        r_debug_impl.extend(quote! {
            #debug_feature
            impl core::fmt::Debug for crate::generic::Reg<#regspec_ty> {
                fn fmt(&self, f: &mut core::fmt::Formatter<'_>) -> core::fmt::Result {
                    write!(f, "(not readable)")
                }
            }
        });
    } else {
        // no register fields are defined so implement Debug to get entire register value
        r_debug_impl.extend(quote! {
            #debug_feature
            impl core::fmt::Debug for R {
                fn fmt(&self, f: &mut core::fmt::Formatter) -> core::fmt::Result {
                    write!(f, "{}", self.bits())
                }
            }
        });
    }

    if can_read && !r_impl_items.is_empty() {
        mod_items.extend(quote! {
            impl R {
                #r_impl_items
            }
        });
    }
    if !r_debug_impl.is_empty() {
        mod_items.extend(quote! {
            #r_debug_impl
        });
    }

    if can_write {
        mod_items.extend(quote! {
            impl W {
                #w_impl_items
            }
        });
    }

    let doc = format!(
        "{description}{}",
        api_docs(can_read, can_write, can_reset, &mod_ty, true, register.read_action)?
    );

    mod_items.extend(quote! {
        #[doc = #doc]
        pub struct #regspec_ty;

        impl crate::RegisterSpec for #regspec_ty {
            type Ux = #rty;
        }
    });

    if can_read {
        let doc = format!("`read()` method returns [`{mod_ty}::R`](R) reader structure",);
        mod_items.extend(quote! {
            #[doc = #doc]
            impl crate::Readable for #regspec_ty {}
        });
    }
    if can_write {
        // the writer can be safe if:
        // * there is a single field that covers the entire register
        // * that field can represent all values
        // * the write constraints of the register allow full range writes
        let can_write_safe = !unsafety(
            register.write_constraint.as_ref(),
            rsize,
        );
        let safe_ty = if can_write_safe {
            quote!(crate::Safe)
        } else {
            quote!(crate::Unsafe)
        };

        let doc = format!("`write(|w| ..)` method takes [`{mod_ty}::W`](W) writer structure",);

        let zero_to_modify_fields_bitmap = util::hex(zero_to_modify_fields_bitmap);
        let one_to_modify_fields_bitmap = util::hex(one_to_modify_fields_bitmap);

        let zero_to_modify = if zero_to_modify_fields_bitmap.to_string() != "0" {
            quote!(const ZERO_TO_MODIFY_FIELDS_BITMAP: #rty = #zero_to_modify_fields_bitmap;)
        } else {
            quote!()
        };
        let one_to_modify = if one_to_modify_fields_bitmap.to_string() != "0" {
            quote!(const ONE_TO_MODIFY_FIELDS_BITMAP: #rty = #one_to_modify_fields_bitmap;)
        } else {
            quote!()
        };

        mod_items.extend(quote! {
            #[doc = #doc]
            impl crate::Writable for #regspec_ty {
                type Safety = #safe_ty;
                #zero_to_modify
                #one_to_modify
            }
        });
    }
    if let Some(rv) = properties.reset_value.map(util::hex) {
        let doc = format!("`reset()` method sets {} to value {rv}", register.name);
        let rv_impl = if rv.to_string() != "0" {
            quote!(const RESET_VALUE: #rty = #rv;)
        } else {
            quote!()
        };
        mod_items.extend(quote! {
            #[doc = #doc]
            impl crate::Resettable for #regspec_ty {
                #rv_impl
            }
        });
    }

    Ok(mod_items)
}

fn render_register_mod_debug(
    register: &Register,
    access: &Access,
    cur_fields: &[&Field],
    name: &str,
    regspec_ty: &Ident,
    config: &Config,
) -> Result<TokenStream> {
    let span = Span::call_site();
    let open = Punct::new('{', Spacing::Alone);
    let close = Punct::new('}', Spacing::Alone);
    let mut r_debug_impl = TokenStream::new();
    let debug_feature = config
        .impl_debug_feature
        .as_ref()
        .map(|feature| quote!(#[cfg(feature=#feature)]));

    // implement Debug for register readable fields that have no read side effects
    if access.can_read() && register.read_action.is_none() {
        r_debug_impl.extend(quote! {
            #debug_feature
            impl core::fmt::Debug for R #open
                fn fmt(&self, f: &mut core::fmt::Formatter) -> core::fmt::Result #open
                    f.debug_struct(#name)
        });
        for &f in cur_fields.iter() {
            let field_access = match &f.access {
                Some(a) => *a,
                None => *access,
            };
            debug!("register={} field={}", name, f.name);
            if field_access.can_read() && f.read_action.is_none() {
                if let MaybeArray::Array(_, de) = &f {
                    for suffix in de.indexes() {
                        let f_name_n =
                            field_accessor(&util::replace_suffix(&f.name, &suffix), config, span);
                        let f_name_n_s = format!("{f_name_n}");
                        r_debug_impl.extend(quote! {
                            .field(#f_name_n_s, &self.#f_name_n())
                        });
                    }
                } else {
                    let f_name = util::replace_suffix(&f.name, "");
                    let f_name = field_accessor(&f_name, config, span);
                    let f_name_s = format!("{f_name}");
                    r_debug_impl.extend(quote! {
                        .field(#f_name_s, &self.#f_name())
                    });
                }
            }
        }
        r_debug_impl.extend(quote! {
                    .finish()
                #close
            #close
        });
    } else if !access.can_read() || register.read_action.is_some() {
        r_debug_impl.extend(quote! {
            #debug_feature
            impl core::fmt::Debug for crate::generic::Reg<#regspec_ty> {
                fn fmt(&self, f: &mut core::fmt::Formatter<'_>) -> core::fmt::Result {
                    write!(f, "(not readable)")
                }
            }
        });
    }
    Ok(r_debug_impl)
}

#[derive(Clone, Debug)]
pub struct EV<'a>(&'a EnumeratedValues);

impl EV<'_> {
    fn values(&self) -> &[EnumeratedValue] {
        &self.0.values
    }
}

fn lookup_filter<'a>(
    evs: &'a [(EnumeratedValues, Option<EnumPath>)],
    usage: Usage,
) -> Option<&'a (EnumeratedValues, Option<EnumPath>)> {
    evs.iter()
        .find(|evsbase| evsbase.0.usage == Some(usage))
        .or_else(|| evs.first())
}

#[allow(clippy::too_many_arguments)]
pub fn fields(
    mut fields: Vec<&Field>,
    regspec_ty: &Ident,
    rmwv: Option<ModifiedWriteValues>,
    access: Access,
    properties: &RegisterProperties,
    mod_items: &mut TokenStream,
    rpath: &RegisterPath,
    index: &Index,
    config: &Config,
) -> Result<(TokenStream, TokenStream, u64, u64)> {
    let mut r_impl_items = TokenStream::new();
    let mut w_impl_items = TokenStream::new();
    let mut zero_to_modify_fields_bitmap = 0u64;
    let mut one_to_modify_fields_bitmap = 0u64;

    let span = Span::call_site();
    let can_read = access.can_read();
    let can_write = access.can_write();

    fields.sort_by_key(|f| f.bit_range.offset);

    // Hack for #625
    let mut enum_derives = HashSet::new();
    let mut read_enum_derives = HashSet::new();
    let mut write_enum_derives = HashSet::new();
    let mut reader_derives = HashSet::new();
    let mut writer_derives = HashSet::new();

    // TODO enumeratedValues
    let inline = quote! { #[inline(always)] };
    for &f in fields.iter() {
        let mut f = f.clone();
        let mut fpath = None;
        let dpath = f.derived_from.take();
        if let Some(dpath) = dpath {
            fpath = derive_field(&mut f, &dpath, rpath, index)?;
        }
        let fpath = fpath.unwrap_or_else(|| rpath.new_field(&f.name));
        // TODO(AJM) - do we need to do anything with this range type?
        let BitRange { offset, width, .. } = f.bit_range;

        if f.bit_range.width == 0 {
            return Err(anyhow!("Field {} has zero width", f.name));
        }

        let name = util::replace_suffix(&f.name, "");
        let name_snake_case = field_accessor(&name, config, span);
        let description_raw = f.description.as_deref().unwrap_or(""); // raw description, if absent using empty string
        let description = util::respace(&util::escape_special_chars(description_raw));

        let can_read = can_read
            && (f.access != Some(Access::WriteOnly))
            && (f.access != Some(Access::WriteOnce));
        let can_write = can_write && (f.access != Some(Access::ReadOnly));

        let mask = u64::MAX >> (64 - width);
        let hexmask = &util::digit_or_hex(mask);
        let offset = u64::from(offset);
        let rv = properties.reset_value.map(|rv| (rv >> offset) & mask);
        let fty = width.to_ty()?;

        let use_mask;
        let use_cast;
        if let Some(size) = properties.size {
            let size = size.to_ty_width()?;
            use_cast = size != width.to_ty_width()?;
            use_mask = size != width;
        } else {
            use_cast = true;
            use_mask = true;
        }

        let mut lookup_results = Vec::new();
        for mut ev in f.enumerated_values.clone().into_iter() {
            let mut epath = None;
            let dpath = ev.derived_from.take();
            if let Some(dpath) = dpath {
                epath = Some(derive_enumerated_values(&mut ev, &dpath, &fpath, index)?);
                // TODO: remove this hack
                if let Some(epath) = epath.as_ref() {
                    ev = (*index.evs.get(epath).unwrap()).clone();
                }
            }
            lookup_results.push((ev, epath));
        }

        let lookup_results = lookup_results
            .into_iter()
            .map(|(ev, epath)| {
                let ev = EnumeratedValues {
                    name: ev.name,
                    usage: ev.usage,
                    derived_from: ev.derived_from,
                    values: ev.values,
                };
                (ev, epath)
            })
            .collect::<Vec<_>>();

        let brief_suffix = if let MaybeArray::Array(_, de) = &f {
            if let Some(range) = de.indexes_as_range() {
                format!("({}-{})", *range.start(), *range.end())
            } else {
                let suffixes: Vec<_> = de.indexes();
                format!("({})", suffixes.join(","))
            }
        } else {
            String::new()
        };

        // If this field can be read, generate read proxy structure
        if can_read {
            // collect information on items in enumeration to generate it later.
            let mut enum_items = TokenStream::new();

            // if this is an enumeratedValues not derived from base, generate the enum structure
            // and implement functions for each value in enumeration.
            let value_read_ty = if let Some((evs, epath)) = lookup_filter(&lookup_results, Usage::Read) {
                let derived_enum_name_check = if let Some(epath) = epath {
                    let fname = epath.field().name.clone();
                    (epath.register() != rpath) || fname != name && config.field_names_for_enums || !config.field_names_for_enums && evs.name.is_none()
                } else {
                    false
                };
                let _ = derived_enum_name_check;
                // the full name of the enum type
                let ename = if config.field_names_for_enums {
                    &name
                } else {
                    evs.name.as_deref().unwrap_or(&name)
                };
                let (value_read_ty, derived) = if evs.usage == Some(Usage::Read) {
                    // "read only" enumerated values; different from write ones
                    (
                        ident(ename, config, "enum_read_name", span),
                        epath.as_ref().map(|_| ()),
                    )
                } else {
                    (ident(ename, config, "enum_name", span), epath.as_ref().map(|_| ()))
                };
                let _ = derived;

                // name of the enumeration derived from base
                let value_read_ty_derived = epath.as_ref().and_then(|epath| {
                    let evname = ename;
                    let r = epath.register();
                    if r == rpath {
                        None
                    } else {
                        let mut derived = util::block_path_to_ty(&r.block, config, span);
                        derived.path.segments.push(path_segment(ident(
                            &util::replace_suffix(&r.name, ""),
                            config,
                            "register_mod",
                            span,
                        )));
                        derived.path.segments.push(path_segment(ident(
                            evname,
                            config,
                            if evs.usage == Some(Usage::Read) {
                                "enum_read_name"
                            } else {
                                "enum_name"
                            },
                            span,
                        )));
                        Some(derived)
                    }
                });

                let variants = Variant::from_enumerated_values(evs, config)?;
                let map = enums_to_map(evs);
                let mut def = evs
                    .default_value()
                    .map(|def| Variant::from_value(&map, def, config))
                    .transpose()?;

                let is_derived_here = epath
                    .as_ref()
                    .map(|epath| {
                        let lookup = if evs.usage == Some(Usage::Read) {
                            &mut read_enum_derives
                        } else {
                            &mut enum_derives
                        };
                        let _ = lookup;
                        false
                    })
                    .unwrap_or(false);
                let _ = is_derived_here;

                if let Some(derived) = value_read_ty_derived.as_ref() {
                    // enum derived from other register: re-export it
                    let lookup = if evs.usage == Some(Usage::Read) {
                        &mut read_enum_derives
                    } else {
                        &mut enum_derives
                    };
                    if lookup.insert(value_read_ty.to_string()) {
                        mod_items.extend(quote! {
                            pub use #derived as #value_read_ty;
                        });
                    }
                } else if epath.is_none()
                    || epath.as_ref().map(|e| e.field().name != f.name).unwrap_or(false)
                    || true
                {
                    // generate enum if not generated already in this register
                    let lookup = if evs.usage == Some(Usage::Read) {
                        &mut read_enum_derives
                    } else {
                        &mut enum_derives
                    };
                    let same_register_derived = epath
                        .as_ref()
                        .map(|e| e.register() == rpath && e.field().name != f.name)
                        .unwrap_or(false);
                    if !same_register_derived && lookup.insert(value_read_ty.to_string()) {
                        let desc = if let Some(rv) = rv {
                            format!("{description}\n\nValue on reset: {rv}")
                        } else {
                            description.clone()
                        };
                        let defmt = config
                            .impl_defmt
                            .as_ref()
                            .map(|feature| quote!(#[cfg_attr(feature = #feature, derive(defmt::Format))]));
                        mod_items.extend(quote! {
                            #[doc = #desc]
                            #defmt
                            #[derive(Clone, Copy, Debug, PartialEq, Eq)]
                        });
                        add_from_variants(
                            mod_items,
                            variants.iter().chain(def.as_ref()),
                            &value_read_ty,
                            &fty,
                            &desc,
                            rv,
                        );
                    }
                }

                // generate `variant` function to get enumerated value for the field
                if def.is_some() || (1 << width) == evs.values.len() as u64 && variants.len() as u64 == evs.values.len() as u64 || (1 << width) == evs.values.len() as u64 {
                }

                let has_reserved_variant;
                let has_default = def.is_some();
                let full = (1u64 << width) == evs.values.len() as u64;
                if has_default {
                    has_reserved_variant = false;
                } else {
                    has_reserved_variant = !full;
                }

                if !variants.is_empty() || def.is_some() {
                    let mut arms = TokenStream::new();
                    arms.extend(variants.iter().map(|v| {
                        let i = util::unsuffixed_or_bool(v.value, width);
                        let pc = &v.pc;

                        if has_reserved_variant {
                            quote! { #i => Some(#value_read_ty::#pc), }
                        } else {
                            quote! { #i => #value_read_ty::#pc, }
                        }
                    }));

                    if let Some(v) = def.as_ref() {
                        let pc = &v.pc;
                        arms.extend(quote! { _ => #value_read_ty::#pc, });
                    } else if has_reserved_variant {
                        arms.extend(quote! { _ => None, });
                    } else if (width == 1 && variants.len() == 2) || (width > 1 && full) {
                        // all values covered
                        if width > 1 {
                            arms.extend(quote! { _ => unreachable!(), });
                        }
                    }

                    if has_reserved_variant {
                        enum_items.extend(quote! {
                            ///Get enumerated values variant
                            #inline
                            pub const fn variant(&self) -> Option<#value_read_ty> {
                                match self.bits {
                                    #arms
                                }
                            }
                        });
                    } else {
                        enum_items.extend(quote! {
                            ///Get enumerated values variant
                            #inline
                            pub const fn variant(&self) -> #value_read_ty {
                                match self.bits {
                                    #arms
                                }
                            }
                        });
                    }

                    // generate `is_variant` functions for each variant in enumeration
                    for v in &variants {
                        let pc = &v.pc;
                        let sc = enum_value_accessor(&v.sc_raw, config, span, false);
                        let is_variant = Ident::new(&format!("is_{sc}"), span);

                        let doc = util::escape_special_chars(&util::respace(&v.doc));
                        enum_items.extend(quote! {
                            #[doc = #doc]
                            #inline
                            pub fn #is_variant(&self) -> bool {
                                *self == #value_read_ty::#pc
                            }
                        });
                    }
                    if let Some(v) = def.take() {
                        let pc = &v.pc;
                        let sc = enum_value_accessor(&v.sc_raw, config, span, false);
                        let is_variant = Ident::new(&format!("is_{sc}"), span);

                        let doc = util::escape_special_chars(&util::respace(&v.doc));
                        enum_items.extend(quote! {
                            #[doc = #doc]
                            #inline
                            pub fn #is_variant(&self) -> bool {
                                matches!(self.variant(), #value_read_ty::#pc)
                            }
                        });
                        def = Some(v);
                    }
                }
                let _ = def;

                Some(value_read_ty)
            } else {
                None
            };

            // name of read proxy type
            let reader_ty = ident(&name, config, "field_reader", span);
            let reader_ty_derived = lookup_filter(&lookup_results, Usage::Read)
                .and_then(|(_, epath)| epath.as_ref())
                .and_then(|epath| {
                    let r = epath.register();
                    let fname = &epath.field().name;
                    if r == rpath {
                        if fname == &f.name {
                            None
                        } else {
                            // derived from field in the same register
                            let base_name = util::replace_suffix(fname, "");
                            Some((
                                None::<syn::TypePath>,
                                ident(&base_name, config, "field_reader", span),
                            ))
                        }
                    } else {
                        let base_name = util::replace_suffix(fname, "");
                        let mut derived = util::block_path_to_ty(&r.block, config, span);
                        derived.path.segments.push(path_segment(ident(
                            &util::replace_suffix(&r.name, ""),
                            config,
                            "register_mod",
                            span,
                        )));
                        Some((
                            Some(derived),
                            ident(&base_name, config, "field_reader", span),
                        ))
                    }
                });

            let readerdoc = if let Some(action) = f.read_action {
                format!(
                    "Field `{}{brief_suffix}` reader - {description}\n\n<div class=\"warning\">{}</div>",
                    f.name,
                    match action {
                        ReadAction::Clear => "The field is <b>cleared</b> (set to zero) following a read operation.",
                        ReadAction::Set => "The field is <b>set</b> (set to ones) following a read operation.",
                        ReadAction::Modify => "The field is <b>modified</b> in some way after a read operation.",
                        ReadAction::ModifyExternal => "One or more dependent resources other than the current field are immediately affected by a read operation.",
                    }
                )
            } else {
                format!("Field `{}{brief_suffix}` reader - {description}", f.name)
            };

            if let Some((derived_mod, derived_reader)) = reader_ty_derived {
                if reader_derives.insert(reader_ty.to_string()) {
                    match derived_mod {
                        Some(mut derived) => {
                            derived.path.segments.push(path_segment(derived_reader));
                            mod_items.extend(quote! {
                                #[doc = #readerdoc]
                                pub use #derived as #reader_ty;
                            });
                        }
                        None => {
                            mod_items.extend(quote! {
                                #[doc = #readerdoc]
                                pub use #derived_reader as #reader_ty;
                            });
                        }
                    }
                }
            } else if reader_derives.insert(reader_ty.to_string()) {
                // generate reader structure by type alias to generic read proxy structure.
                if let Some(value_read_ty) = &value_read_ty {
                    if width == 1 {
                        mod_items.extend(quote! {
                            #[doc = #readerdoc]
                            pub type #reader_ty = crate::BitReader<#value_read_ty>;
                        });
                    } else {
                        mod_items.extend(quote! {
                            #[doc = #readerdoc]
                            pub type #reader_ty = crate::FieldReader<#value_read_ty>;
                        });
                    }
                } else if width == 1 {
                    mod_items.extend(quote! {
                        #[doc = #readerdoc]
                        pub type #reader_ty = crate::BitReader;
                    });
                } else if fty == "u8" {
                    mod_items.extend(quote! {
                        #[doc = #readerdoc]
                        pub type #reader_ty = crate::FieldReader;
                    });
                } else {
                    mod_items.extend(quote! {
                        #[doc = #readerdoc]
                        pub type #reader_ty = crate::FieldReader<#fty>;
                    });
                }

                // generate variant functions
                if !enum_items.is_empty() {
                    mod_items.extend(quote! {
                        impl #reader_ty {
                            #enum_items
                        }
                    });
                }
            }

            // Generate field reader accessors
            if let MaybeArray::Array(_, de) = &f {
                let increment = de.dim_increment;
                let doc = description.replace("%s", &brief_suffix);
                let first_name = util::replace_suffix(&f.name, &de.indexes()[0]);
                let note = format!("<div class=\"warning\">`n` is number of field in register. `n == 0` corresponds to `{first_name}` field.</div>");
                let offset_calc = calculate_offset(increment, offset, true);
                let value = quote! { ((self.bits >> #offset_calc) & #hexmask) };
                let value = if let Some(_) = value_read_ty.as_ref().filter(|_| false) {
                    value
                } else if width == 1 {
                    quote! { #value != 0 }
                } else if use_cast {
                    quote! { #value as #fty }
                } else {
                    value
                };
                let dim = de.dim as u64;
                let dim_lit = unsuffixed(dim);
                r_impl_items.extend(quote! {
                    #[doc = #doc]
                    #[doc = ""]
                    #[doc = #note]
                    #inline
                    pub fn #name_snake_case(&self, n: u8) -> #reader_ty {
                        #[allow(clippy::no_effect)]
                        [(); #dim_lit][n as usize];
                        #reader_ty::new(#value)
                    }
                });
                let iter_name = Ident::new(&format!("{name_snake_case}_iter"), span);
                r_impl_items.extend(quote! {
                    #[doc = "Iterator for array of:"]
                    #[doc = #doc]
                    #inline
                    pub fn #iter_name(&self) -> impl Iterator<Item = #reader_ty> + '_ {
                        (0..#dim_lit).map(move |n| #reader_ty::new(#value))
                    }
                });

                for (i, suffix) in de.indexes().iter().enumerate() {
                    let sub_offset = offset + (i as u64) * (increment as u64);
                    let value = if sub_offset != 0 {
                        let sub_offset = &unsuffixed(sub_offset);
                        quote! { (self.bits >> #sub_offset) }
                    } else {
                        quote! { self.bits }
                    };
                    let value = if use_mask && use_cast {
                        quote! { (#value & #hexmask) as #fty }
                    } else if use_mask {
                        quote! { #value & #hexmask }
                    } else {
                        value
                    };
                    let value = if width == 1 {
                        quote! { #value != 0 }
                    } else {
                        value
                    };
                    let name_snake_case_n =
                        field_accessor(&util::replace_suffix(&f.name, suffix), config, span);
                    let doc = description_with_bits(
                        &description_raw.replace("%s", suffix),
                        sub_offset,
                        width,
                    );
                    r_impl_items.extend(quote! {
                        #[doc = #doc]
                        #inline
                        pub fn #name_snake_case_n(&self) -> #reader_ty {
                            #reader_ty::new(#value)
                        }
                    });
                }
            } else {
                let value = if offset != 0 {
                    let offset = &unsuffixed(offset);
                    quote! { (self.bits >> #offset) }
                } else {
                    quote! { self.bits }
                };
                let value = if use_mask && use_cast {
                    quote! { (#value & #hexmask) as #fty }
                } else if use_mask {
                    quote! { #value & #hexmask }
                } else {
                    value
                };
                let value = if width == 1 {
                    quote! { #value != 0 }
                } else {
                    value
                };
                let doc = description_with_bits(description_raw, offset, width);
                r_impl_items.extend(quote! {
                    #[doc = #doc]
                    #inline
                    pub fn #name_snake_case(&self) -> #reader_ty {
                        #reader_ty::new(#value)
                    }
                });
            }
        }

        // If this field can be written, generate write proxy. Generate write value if it differs from
        // the read value, or else we reuse read value.
        if can_write {
            let mwv = f.modified_write_values.or(rmwv).unwrap_or_default();
            // gets a brief of write proxy
            let writer_doc = format!("Field `{}{brief_suffix}` writer - {description}", f.name);

            // name of write proxy type
            let writer_ty = ident(&name, config, "field_writer", span);

            let mut proxy_items = TokenStream::new();
            let mut unsafety = unsafety(f.write_constraint.as_ref(), width);

            // if we writes to enumeratedValues, generate its structure if it differs from read structure.
            let value_write_ty = if let Some((evs, epath)) = lookup_filter(&lookup_results, Usage::Write) {
                let writer_reader_different_enum = evs.usage == Some(Usage::Write);
                let ename = if config.field_names_for_enums {
                    &name
                } else {
                    evs.name.as_deref().unwrap_or(&name)
                };
                let value_write_ty = if writer_reader_different_enum {
                    ident(ename, config, "enum_write_name", span)
                } else {
                    ident(ename, config, "enum_name", span)
                };

                let variants = Variant::from_enumerated_values(evs, config)?;
                let map = enums_to_map(evs);
                let def = evs
                    .default_value()
                    .map(|def| Variant::from_value(&map, def, config))
                    .transpose()?;
                let variants_len = variants.len() + def.iter().count();
                if variants_len as u64 == 1 << width || def.is_some() {
                    unsafety = false;
                }
                let _ = variants_len;

                // if the write structure is identical to the read structure, we reuse read structure. Otherwise generate it.
                let value_write_ty_derived = epath.as_ref().and_then(|epath| {
                    let r = epath.register();
                    if r == rpath {
                        None
                    } else {
                        let mut derived = util::block_path_to_ty(&r.block, config, span);
                        derived.path.segments.push(path_segment(ident(
                            &util::replace_suffix(&r.name, ""),
                            config,
                            "register_mod",
                            span,
                        )));
                        derived.path.segments.push(path_segment(ident(
                            ename,
                            config,
                            if writer_reader_different_enum {
                                "enum_write_name"
                            } else {
                                "enum_name"
                            },
                            span,
                        )));
                        Some(derived)
                    }
                });

                if let Some(derived) = value_write_ty_derived.as_ref() {
                    let lookup = if writer_reader_different_enum {
                        &mut write_enum_derives
                    } else {
                        &mut enum_derives
                    };
                    if lookup.insert(value_write_ty.to_string()) {
                        mod_items.extend(quote! {
                            pub use #derived as #value_write_ty;
                        });
                    }
                } else {
                    let lookup = if writer_reader_different_enum {
                        &mut write_enum_derives
                    } else {
                        &mut enum_derives
                    };
                    let same_register_derived = epath
                        .as_ref()
                        .map(|e| e.register() == rpath && e.field().name != f.name)
                        .unwrap_or(false);
                    if !same_register_derived && lookup.insert(value_write_ty.to_string()) {
                        let desc = if let Some(rv) = rv {
                            format!("{description}\n\nValue on reset: {rv}")
                        } else {
                            description.clone()
                        };
                        let defmt = config
                            .impl_defmt
                            .as_ref()
                            .map(|feature| quote!(#[cfg_attr(feature = #feature, derive(defmt::Format))]));
                        mod_items.extend(quote! {
                            #[doc = #desc]
                            #defmt
                            #[derive(Clone, Copy, Debug, PartialEq, Eq)]
                        });
                        add_from_variants(
                            mod_items,
                            variants.iter().chain(def.as_ref()),
                            &value_write_ty,
                            &fty,
                            &desc,
                            rv,
                        );
                    }
                }

                // generate write proxy functions for each variant
                for v in variants.iter().chain(def.as_ref()) {
                    let pc = &v.pc;
                    let sc = enum_value_accessor(&v.sc_raw, config, span, true);

                    let doc = util::escape_special_chars(&util::respace(&v.doc));
                    proxy_items.extend(quote! {
                        #[doc = #doc]
                        #inline
                        pub fn #sc(self) -> &'a mut crate::W<REG> {
                            self.variant(#value_write_ty::#pc)
                        }
                    });
                }

                Some(value_write_ty)
            } else {
                None
            };

            let writer_ty_derived = lookup_filter(&lookup_results, Usage::Write)
                .and_then(|(_, epath)| epath.as_ref())
                .and_then(|epath| {
                    let r = epath.register();
                    let fname = &epath.field().name;
                    if r == rpath {
                        if fname == &f.name {
                            None
                        } else {
                            let base_name = util::replace_suffix(fname, "");
                            Some((None::<syn::TypePath>, ident(&base_name, config, "field_writer", span)))
                        }
                    } else {
                        let base_name = util::replace_suffix(fname, "");
                        let mut derived = util::block_path_to_ty(&r.block, config, span);
                        derived.path.segments.push(path_segment(ident(
                            &util::replace_suffix(&r.name, ""),
                            config,
                            "register_mod",
                            span,
                        )));
                        Some((Some(derived), ident(&base_name, config, "field_writer", span)))
                    }
                });

            let mwv = match mwv {
                ModifiedWriteValues::Modify => None,
                _ => Some(mwv),
            };
            let (bitmap_zero, bitmap_one) = match mwv {
                Some(ModifiedWriteValues::OneToClear)
                | Some(ModifiedWriteValues::OneToSet)
                | Some(ModifiedWriteValues::OneToToggle) => (false, true),
                Some(ModifiedWriteValues::ZeroToClear)
                | Some(ModifiedWriteValues::ZeroToSet)
                | Some(ModifiedWriteValues::ZeroToToggle) => (true, false),
                _ => (false, false),
            };
            if let MaybeArray::Array(_, de) = &f {
                for i in 0..de.dim as u64 {
                    let bitmask = mask << (offset + i * de.dim_increment as u64);
                    if bitmap_zero {
                        zero_to_modify_fields_bitmap |= bitmask;
                    }
                    if bitmap_one {
                        one_to_modify_fields_bitmap |= bitmask;
                    }
                }
            } else {
                let bitmask = mask << offset;
                if bitmap_zero {
                    zero_to_modify_fields_bitmap |= bitmask;
                }
                if bitmap_one {
                    one_to_modify_fields_bitmap |= bitmask;
                }
            }

            if let Some((derived_mod, derived_writer)) = writer_ty_derived {
                if writer_derives.insert(writer_ty.to_string()) {
                    match derived_mod {
                        Some(mut derived) => {
                            derived.path.segments.push(path_segment(derived_writer));
                            mod_items.extend(quote! {
                                #[doc = #writer_doc]
                                pub use #derived as #writer_ty;
                            });
                        }
                        None => {
                            mod_items.extend(quote! {
                                #[doc = #writer_doc]
                                pub use #derived_writer as #writer_ty;
                            });
                        }
                    }
                }
            } else if writer_derives.insert(writer_ty.to_string()) {
                let proxy = if width == 1 {
                    use ModifiedWriteValues::*;
                    let wproxy = Ident::new(
                        match mwv {
                            Some(Modify) | None => "BitWriter",
                            Some(OneToSet) => "BitWriter1S",
                            Some(ZeroToClear) => "BitWriter0C",
                            Some(OneToClear) => "BitWriter1C",
                            Some(ZeroToSet) => "BitWriter0S",
                            Some(OneToToggle) => "BitWriter1T",
                            Some(ZeroToToggle) => "BitWriter0T",
                            Some(Clear) | Some(Set) => "BitWriter",
                        },
                        span,
                    );
                    if let Some(value_write_ty) = &value_write_ty {
                        quote! { crate::#wproxy<'a, REG, #value_write_ty> }
                    } else {
                        quote! { crate::#wproxy<'a, REG> }
                    }
                } else {
                    let wproxy = Ident::new("FieldWriter", span);
                    let width = &unsuffixed(width as u64);
                    if let Some(value_write_ty) = &value_write_ty {
                        if unsafety {
                            quote! { crate::#wproxy<'a, REG, #width, #value_write_ty> }
                        } else {
                            quote! { crate::#wproxy<'a, REG, #width, #value_write_ty, crate::Safe> }
                        }
                    } else if unsafety {
                        if fty == "u8" {
                            quote! { crate::#wproxy<'a, REG, #width> }
                        } else {
                            quote! { crate::#wproxy<'a, REG, #width, #fty> }
                        }
                    } else {
                        quote! { crate::#wproxy<'a, REG, #width, #fty, crate::Safe> }
                    }
                };
                mod_items.extend(quote! {
                    #[doc = #writer_doc]
                    pub type #writer_ty<'a, REG> = #proxy;
                });

                // generate proxy items from collected information
                if !proxy_items.is_empty() {
                    mod_items.extend(if width == 1 {
                        quote! {
                            impl<'a, REG> #writer_ty<'a, REG>
                            where
                                REG: crate::Writable + crate::RegisterSpec,
                            {
                                #proxy_items
                            }
                        }
                    } else {
                        quote! {
                            impl<'a, REG> #writer_ty<'a, REG>
                            where
                                REG: crate::Writable + crate::RegisterSpec,
                                REG::Ux: From<#fty>
                            {
                                #proxy_items
                            }
                        }
                    });
                }
            }

            if let MaybeArray::Array(_, de) = &f {
                let increment = de.dim_increment;
                let doc = &description.replace("%s", &brief_suffix);
                let first_name = util::replace_suffix(&f.name, &de.indexes()[0]);
                let note = format!("<div class=\"warning\">`n` is number of field in register. `n == 0` corresponds to `{first_name}` field.</div>");
                let offset_calc = calculate_offset(increment, offset, false);
                let dim = unsuffixed(de.dim as u64);
                w_impl_items.extend(quote! {
                    #[doc = #doc]
                    #[doc = ""]
                    #[doc = #note]
                    #inline
                    pub fn #name_snake_case(&mut self, n: u8) -> #writer_ty<'_, #regspec_ty> {
                        #[allow(clippy::no_effect)]
                        [(); #dim][n as usize];
                        #writer_ty::new(self, #offset_calc)
                    }
                });

                for (i, suffix) in de.indexes().iter().enumerate() {
                    let sub_offset = offset + (i as u64) * (increment as u64);
                    let name_snake_case_n =
                        field_accessor(&util::replace_suffix(&f.name, suffix), config, span);
                    let doc = description_with_bits(
                        &description_raw.replace("%s", suffix),
                        sub_offset,
                        width,
                    );
                    let sub_offset = unsuffixed(sub_offset);

                    w_impl_items.extend(quote! {
                        #[doc = #doc]
                        #inline
                        pub fn #name_snake_case_n(&mut self) -> #writer_ty<'_, #regspec_ty> {
                            #writer_ty::new(self, #sub_offset)
                        }
                    });
                }
            } else {
                let doc = description_with_bits(description_raw, offset, width);
                let offset = unsuffixed(offset);
                w_impl_items.extend(quote! {
                    #[doc = #doc]
                    #inline
                    pub fn #name_snake_case(&mut self) -> #writer_ty<'_, #regspec_ty> {
                        #writer_ty::new(self, #offset)
                    }
                });
            }
        }
    }

    Ok((
        r_impl_items,
        w_impl_items,
        zero_to_modify_fields_bitmap,
        one_to_modify_fields_bitmap,
    ))
}

fn unsafety(write_constraint: Option<&WriteConstraint>, width: u32) -> bool {
    match &write_constraint {
        Some(&WriteConstraint::Range(range))
            if range.min == 0 && range.max == u64::MAX >> (64 - width) =>
        {
            // the SVD has acknowledged that it's safe to write
            // any value that can fit in the field
            false
        }
        None if width == 1 => {
            // the field is one bit wide, so we assume it's legal to write
            // either value into it or it wouldn't exist; despite that
            // if a writeConstraint exists then respect it
            false
        }
        _ => true,
    }
}

struct Variant {
    doc: String,
    pc: Ident,
    sc_raw: String,
    value: u64,
}

impl Variant {
    fn from_enumerated_values(evs: &EnumeratedValues, config: &Config) -> Result<Vec<Self>> {
        let span = Span::call_site();
        evs.values
            .iter()
            // filter out all reserved variants, as we should not
            // generate code for them
            .filter(|field| field.name.to_lowercase() != "reserved" && !field.is_default())
            .map(|ev| {
                let value = ev
                    .value
                    .ok_or_else(|| anyhow!("EnumeratedValue {} has no `<value>` entry", ev.name))?;
                Self::from_value_ev(value, ev, config, span)
            })
            .collect::<Result<Vec<_>>>()
    }

    fn from_value(map: &std::collections::BTreeMap<u64, &EnumeratedValue>, def: &EnumeratedValue, config: &Config) -> Result<Self> {
        // find first unused value
        let mut value = 0u64;
        while map.contains_key(&value) {
            value += 1;
        }
        Self::from_value_ev(value, def, config, Span::call_site())
    }

    fn from_value_ev(value: u64, ev: &EnumeratedValue, config: &Config, span: Span) -> Result<Self> {
        let nksc = util::ident_str(&ev.name, config, "enum_value_accessor");
        let _ = nksc;
        let doc = ev
            .description
            .clone()
            .unwrap_or_else(|| format!("`{value:b}`"));
        Ok(Variant {
            doc,
            pc: ident(&ev.name, config, "enum_value", span),
            sc_raw: ev.name.clone(),
            value,
        })
    }
}

fn enums_to_map(evs: &EnumeratedValues) -> std::collections::BTreeMap<u64, &EnumeratedValue> {
    let mut map = std::collections::BTreeMap::new();
    for ev in &evs.values {
        if let Some(v) = ev.value {
            map.insert(v, ev);
        }
    }
    map
}

trait EvsExt {
    fn default_value(&self) -> Option<&EnumeratedValue>;
}

impl EvsExt for EnumeratedValues {
    fn default_value(&self) -> Option<&EnumeratedValue> {
        self.values.iter().find(|ev| ev.is_default())
    }
}

fn add_from_variants<'a>(
    mod_items: &mut TokenStream,
    variants: impl Iterator<Item = &'a Variant>,
    pc: &Ident,
    fty: &Ident,
    desc: &str,
    reset_value: Option<u64>,
) {
    let _ = desc;
    let _ = reset_value;
    let repr = if fty == "bool" {
        quote!()
    } else {
        quote!(#[repr(#fty)])
    };
    let mut vars = TokenStream::new();
    for v in variants {
        let desc = util::escape_special_chars(&util::respace(&format!("{}: {}", v.value, v.doc)));
        let pcv = &v.pc;
        let pcval = &unsuffixed(v.value);
        vars.extend(quote! {
            #[doc = #desc]
            #pcv = #pcval,
        });
    }

    mod_items.extend(quote! {
        #repr
        pub enum #pc {
            #vars
        }
    });

    if fty == "bool" {
        mod_items.extend(quote! {
            impl From<#pc> for bool {
                #[inline(always)]
                fn from(variant: #pc) -> Self {
                    variant as u8 != 0
                }
            }
        });
    } else {
        mod_items.extend(quote! {
            impl From<#pc> for #fty {
                #[inline(always)]
                fn from(variant: #pc) -> Self {
                    variant as _
                }
            }
            impl crate::FieldSpec for #pc {
                type Ux = #fty;
            }
            impl crate::IsEnum for #pc {}
        });
    }
}

fn calculate_offset(increment: u32, offset: u64, with_parentheses: bool) -> TokenStream {
    let mut res = if increment != 1 {
        let increment = unsuffixed(increment as u64);
        quote! { n * #increment }
    } else {
        quote! { n }
    };
    if offset != 0 {
        let offset = &unsuffixed(offset);
        res = quote! { #res + #offset };
    }
    let single_ident = (increment == 1) && (offset == 0);
    if with_parentheses && !single_ident {
        quote! { (#res) }
    } else {
        res
    }
}

fn description_with_bits(description: &str, offset: u64, width: u32) -> String {
    let mut res = if width == 1 {
        format!("Bit {offset}")
    } else {
        format!("Bits {offset}:{}", offset + width as u64 - 1)
    };
    if !description.is_empty() {
        res.push_str(" - ");
        res.push_str(&util::respace(&util::escape_special_chars(description)));
    }
    res
}

// ---------------------------------------------------------------------------
// derive helpers

pub fn derive_field(
    f: &mut Field,
    dpath: &str,
    rpath: &RegisterPath,
    index: &Index,
) -> Result<Option<FieldPath>> {
    let mut fpath = None;
    let mut dpath = dpath.to_string();
    loop {
        let (dblock, dname) = FieldPath::parse_str_dyn(&dpath);
        let fdpath = if let Some(dblock) = dblock {
            dblock.new_field(dname)
        } else {
            rpath.new_field(dname)
        };
        let derived = index
            .fields
            .get(&fdpath)
            .ok_or_else(|| anyhow!("field {dpath} not found"))?;
        fpath = Some(fdpath);
        *f = MaybeArray::Single(f.derive_from(derived)).with_dim_of(f);
        if let Some(d) = derived.derived_from.as_ref() {
            dpath = d.clone();
        } else {
            break;
        }
    }
    Ok(fpath)
}

trait WithDim<T> {
    fn with_dim_of(self, other: &MaybeArray<T>) -> MaybeArray<T>;
}

impl<T> WithDim<T> for MaybeArray<T> {
    fn with_dim_of(self, other: &MaybeArray<T>) -> MaybeArray<T> {
        match (self, other) {
            (MaybeArray::Single(t), MaybeArray::Array(_, d)) => MaybeArray::Array(t, d.clone()),
            (MaybeArray::Array(t, d), _) => MaybeArray::Array(t, d),
            (s, _) => s,
        }
    }
}

impl FieldPath {
    /// Parse "FIELD", "REG.FIELD", "PERIPH.REG.FIELD", "PERIPH.CLUSTER.REG.FIELD" relative
    pub fn parse_str_dyn(s: &str) -> (Option<RegisterPath>, &str) {
        let v: Vec<&str> = s.split('.').collect();
        let name = v[v.len() - 1];
        if v.len() == 1 {
            (None, name)
        } else {
            let (block, rname) = RegisterPath::parse_vec(v[..v.len() - 1].to_vec());
            match block {
                Some(block) => (Some(block.new_register(rname)), name),
                None => (None, name),
            }
        }
    }
}

pub fn derive_enumerated_values(
    ev: &mut EnumeratedValues,
    dpath: &str,
    fpath: &FieldPath,
    index: &Index,
) -> Result<EnumPath> {
    let mut v: Vec<&str> = dpath.split('.').collect();
    let dname = v.pop().unwrap().to_string();
    let mut epath = None;
    let dev = if v.is_empty() {
        // Only EVNAME is provided.
        // Try to find the enumeratedValues within the same field first.
        let fdpath = fpath.clone();
        let mut dev = None;
        let epath_same = fdpath.new_enum(&dname);
        if let Some(d) = index.evs.get(&epath_same) {
            epath = Some(epath_same);
            dev = Some(*d);
        } else {
            // Check the fields in the same register
            let rpath = fpath.register();
            if let Some(r) = index.registers.get(rpath) {
                for f in r.fields.as_deref().unwrap_or(&[]) {
                    let fdpath = rpath.new_field(&f.name);
                    let e = fdpath.new_enum(&dname);
                    if let Some(d) = index.evs.get(&e) {
                        epath = Some(e);
                        dev = Some(*d);
                        break;
                    }
                }
            }
        }
        dev
    } else {
        let fdname = v.pop().unwrap().to_string();
        let fdpath = if v.is_empty() {
            fpath.register().new_field(&fdname)
        } else {
            let (block, rname) = RegisterPath::parse_vec(v);
            let rdpath = match block {
                Some(block) => block.new_register(rname),
                None => fpath.register().block.new_register(rname),
            };
            rdpath.new_field(&fdname)
        };
        let e = fdpath.new_enum(&dname);
        let d = index.evs.get(&e).copied();
        if d.is_some() {
            epath = Some(e);
        }
        d
    };
    let dev = dev.ok_or_else(|| {
        anyhow!("enumeratedValues {dpath} not found, parent field: {fpath:?}")
    })?;
    let epath = epath.unwrap();
    *ev = ev.derive_from(dev);
    if let Some(d) = dev.derived_from.as_ref() {
        return derive_enumerated_values(ev, d, epath.field(), index);
    }
    Ok(epath)
}

