use crate::svd::{Device, MaybeArray};
use log::debug;
use proc_macro2::{Ident, Span, TokenStream};
use quote::quote;

use crate::config::{Edition, Target};
use crate::generate::paths::Index;
use crate::util::{self, ident, Config, ToSanitizedCase};
use anyhow::{Context, Result};

use crate::generate::{generic, interrupt, peripheral, riscv};

pub const COMMIT_INFO: &str = " (63c65c2 2026-06-11)";
pub const VERSION: &str = "0.37.1";

/// Whole device generation
pub fn render(d: &Device, config: &Config, device_x: &mut String) -> Result<TokenStream> {
    let mut out = TokenStream::new();

    let doc = format!(
        "Peripheral access API for {0} microcontrollers \
         (generated using svd2rust v{1}{2})\n\n\
         You can find an overview of the generated API [here].\n\n\
         API features to be included in the [next] svd2rust \
         release can be generated by cloning the svd2rust [repository], \
         checking out the above commit, and running `cargo doc --open`.\n\n\
         [here]: https://docs.rs/svd2rust/{1}/svd2rust/#peripheral-api\n\
         [next]: https://github.com/rust-embedded/svd2rust/blob/master/CHANGELOG.md#unreleased\n\
         [repository]: https://github.com/rust-embedded/svd2rust",
        d.name.to_uppercase(),
        VERSION,
        COMMIT_INFO,
    );

    if config.target == Target::Msp430 {
        out.extend(quote! {
            #![feature(abi_msp430_interrupt)]
        });
    }

    if !config.skip_crate_attributes {
        out.extend(quote! { #![doc = #doc] });
    }
    if !config.make_mod && !config.skip_crate_attributes {
        out.extend(quote! {
            // Explicitly allow a few warnings that may be verbose
            #![allow(non_camel_case_types)]
            #![allow(non_snake_case)]
            #![no_std]
            #![cfg_attr(docsrs, feature(doc_cfg))]
        });
    }

    let index = Index::create(d);

    let core_peripherals: &[&str];
    let fpu_present = d.cpu.as_ref().map(|cpu| cpu.fpu_present).unwrap_or(true);
    if fpu_present {
        core_peripherals = &[
            "CBP", "CPUID", "DCB", "DWT", "FPB", "FPU", "ITM", "MPU", "NVIC", "SCB", "SYST", "TPIU",
        ];
    } else {
        core_peripherals = &[
            "CBP", "CPUID", "DCB", "DWT", "FPB", "ITM", "MPU", "NVIC", "SCB", "SYST", "TPIU",
        ];
    }

    let mut fields = TokenStream::new();
    let mut exprs = TokenStream::new();

    let mut riscv_items = None;
    if config.target == Target::RISCV {
        if config.settings.riscv_config.is_some() {
            debug!("Rendering RISC-V specific code");
            riscv_items = Some(riscv::render(&d.peripherals, device_x, config)?);
        } else {
            log::warn!("No settings file provided for RISC-V target. Using legacy interrupts rendering");
            log::warn!("Please, consider migrating your PAC to riscv 0.12.0 or later");
        }
    }

    if let Some(cpu) = d.cpu.as_ref() {
        let bits = util::unsuffixed(cpu.nvic_priority_bits as u64);

        out.extend(quote! {
            ///Number available in the NVIC for configuring priority
            pub const NVIC_PRIO_BITS: u8 = #bits;
        });
    }

    if config.target == Target::CortexM {
        if config.reexport_core_peripherals {
            let fields = core_peripherals
                .iter()
                .map(|p| Ident::new(p, Span::call_site()))
                .collect::<Vec<_>>();
            out.extend(quote! {
                pub use cortex_m::peripheral::Peripherals as CorePeripherals;
                pub use cortex_m::peripheral::{#(#fields,)*};
            });
        }
        if config.reexport_interrupt {
            out.extend(quote! {
                #[cfg(feature = "rt")]
                pub use cortex_m_rt::interrupt;
                #[cfg(feature = "rt")]
                pub use self::Interrupt as interrupt;
            });
        }
    }

    let generic_file = generic::generic_text(config);
    if config.generic_mod {
        out.extend(quote! {
            #[allow(unused_imports)]
            use generic::*;
            #[doc = "Common register and bit access and modify traits"]
            pub mod generic;
        });
        let _ = generic_file;
    } else {
        out.extend(quote! {
            #[allow(unused_imports)]
            use generic::*;
        });
        out.extend(generic::render(config)?);
    }

    if let Some(items) = riscv_items {
        out.extend(items);
    } else {
        debug!("Rendering interrupts");
        out.extend(interrupt::render(
            config.target,
            &d.peripherals,
            device_x,
            config,
        )?);
    }

    for p in &d.peripherals {
        if config.target == Target::CortexM
            && core_peripherals.contains(&p.name.to_uppercase().as_ref())
        {
            // Core peripherals are handled above
            continue;
        }

        debug!("Rendering peripheral {}", p.name);
        let periph = peripheral::render(p, &index, config).with_context(|| {
            let group_name = p.group_name.as_deref().unwrap_or("No group name");
            if let Some(dname) = p.derived_from.as_ref() {
                format!(
                    "can't render peripheral '{}', group '{group_name}', derived from: '{dname}'",
                    p.name
                )
            } else {
                format!("can't render peripheral '{}', group '{group_name}'", p.name)
            }
        })?;
        out.extend(periph);

        if p.registers
            .as_ref()
            .map(|v| v.is_empty())
            .unwrap_or(true)
            && p.derived_from.is_none()
        {
            // No register block will be generated so don't put this peripheral
            // in the `Peripherals` struct
            continue;
        }

        let mut feature_attribute = TokenStream::new();
        if config.feature_group && p.group_name.is_some() {
            let feature_name = p.group_name.as_ref().unwrap().to_sanitized_snake_case();
            feature_attribute.extend(quote! { #[cfg(feature = #feature_name)] });
        }
        match p {
            MaybeArray::Single(_p) => {
                let p_name = &p.name;
                let p_snake = ident(p_name, config, "peripheral_singleton", Span::call_site());
                let p_ty = ident(p_name, config, "peripheral", Span::call_site());
                if config.feature_peripheral {
                    let feature_name = p.name.to_sanitized_snake_case();
                    feature_attribute.extend(quote! { #[cfg(feature = #feature_name)] });
                }
                fields.extend(quote! {
                    #[doc = #p_name]
                    #feature_attribute
                    pub #p_snake: #p_ty,
                });
                exprs.extend(quote!(#feature_attribute #p_snake: #p_ty::steal(),));
            }
            MaybeArray::Array(p, dim) => {
                for pi in crate::generate::peripheral::expand_peripheral(p, dim) {
                    let p_name = &pi.name;
                    let p_snake = ident(p_name, config, "peripheral_singleton", Span::call_site());
                    let p_ty = ident(p_name, config, "peripheral", Span::call_site());
                    if config.feature_peripheral {
                        let feature_name = p_name.to_sanitized_snake_case();
                        feature_attribute.extend(quote! { #[cfg(feature = #feature_name)] });
                    }
                    fields.extend(quote! {
                        #[doc = #p_name]
                        #feature_attribute
                        pub #p_snake: #p_ty,
                    });
                    exprs.extend(quote!(#feature_attribute #p_snake: #p_ty::steal(),));
                }
            }
        }
    }

    let span = Span::call_site();
    let take = match config.target {
        Target::CortexM | Target::Msp430 | Target::RISCV | Target::XtensaLX | Target::Mips | Target::None => {
            Some(Ident::new("critical_section", span))
        }
    }
    .map(|cs| {
        quote! {
            ///Returns all the peripherals *once*.
            #[cfg(feature = "critical-section")]
            #[inline]
            pub fn take() -> Option<Self> {
                #cs::with(|_| {
                    // SAFETY: We are in a critical section, so we have exclusive access
                    // to `DEVICE_PERIPHERALS`.
                    if unsafe { DEVICE_PERIPHERALS } {
                        return None
                    }

                    // SAFETY: `DEVICE_PERIPHERALS` is set to `true` by `steal`,
                    // ensuring the peripherals can only be returned once.
                    Some(unsafe { Peripherals::steal() })
                })
            }
        }
    });

    let no_mangle_attr = interrupt::no_mangle_attr(config);
    let (set_true, exprs) = if config.edition == Edition::E2024 {
        let mut e = TokenStream::new();
        // wrap each steal in unsafe
        e.extend(wrap_steals_unsafe(exprs));
        (quote!(unsafe { DEVICE_PERIPHERALS = true }), e)
    } else {
        (quote!(DEVICE_PERIPHERALS = true;), exprs)
    };

    out.extend(quote! {
        // NOTE `no_mangle` is used here to prevent linking different minor versions of the device
        // crate as that would let you `take` the device peripherals more than once (one per minor
        // version)
        #no_mangle_attr
        static mut DEVICE_PERIPHERALS: bool = false;

        /// All the peripherals.
        #[allow(non_snake_case)]
        pub struct Peripherals {
            #fields
        }

        impl Peripherals {
            #take

            ///Unchecked version of `Peripherals::take`.
            ///
            ///# Safety
            ///
            ///Each of the returned peripherals must be used at most once.
            #[inline]
            pub unsafe fn steal() -> Self {
                #set_true

                Peripherals {
                    #exprs
                }
            }
        }
    });

    Ok(out)
}

/// For edition 2024: `p : P :: steal () ,` -> `p : unsafe { P :: steal () } ,`
fn wrap_steals_unsafe(exprs: TokenStream) -> TokenStream {
    use proc_macro2::{Delimiter, Group, TokenTree};
    let mut out = TokenStream::new();
    let tokens: Vec<TokenTree> = exprs.into_iter().collect();
    let mut i = 0;
    while i < tokens.len() {
        // find pattern: ident ':' ... ',' where ... is `Ty :: steal ()`
        if let TokenTree::Punct(p) = &tokens[i] {
            if p.as_char() == ':' && i + 1 < tokens.len() {
                // check if previous is ident (field name) and this is a single ':' (not '::')
                let next_is_colon = matches!(&tokens[i + 1], TokenTree::Punct(q) if q.as_char() == ':');
                let prev_is_colon = i > 0 && matches!(&tokens[i - 1], TokenTree::Punct(q) if q.as_char() == ':');
                if !next_is_colon && !prev_is_colon {
                    out.extend(std::iter::once(tokens[i].clone()));
                    // collect until ',' at top level
                    let mut j = i + 1;
                    let mut inner = TokenStream::new();
                    while j < tokens.len() {
                        if let TokenTree::Punct(q) = &tokens[j] {
                            if q.as_char() == ',' {
                                break;
                            }
                        }
                        inner.extend(std::iter::once(tokens[j].clone()));
                        j += 1;
                    }
                    let g = Group::new(Delimiter::Brace, inner);
                    out.extend(quote!(unsafe));
                    out.extend(std::iter::once(TokenTree::Group(g)));
                    i = j;
                    continue;
                }
            }
        }
        out.extend(std::iter::once(tokens[i].clone()));
        i += 1;
    }
    out
}
