pub fn expand_peripheral<'a>(
    info: &'a PeripheralInfo,
    dim: &'a DimElement,
) -> impl Iterator<Item = PeripheralInfo> + 'a {
    dim.indexes().into_iter().enumerate().map(move |(i, idx)| {
        let mut pi = info.clone();
        pi.name = replace_suffix(&info.name, &idx);
        pi.description = info.description.as_ref().map(|d| d.replace("%s", &idx));
        pi.display_name = info.display_name.as_ref().map(|d| d.replace("%s", &idx));
        pi.base_address = info.base_address + (i as u64) * dim.dim_increment as u64;
        pi
    })
}

pub fn render(p_original: &Peripheral, index: &Index, config: &Config) -> Result<TokenStream> {
    let mut out = TokenStream::new();

    let mut p = p_original.clone();
    let mut path = None;
    let dpath = p.derived_from.take();
    if let Some(dpath) = dpath {
        path = derive_peripheral(&mut p, &dpath, index)?;
    }
    let span = Span::call_site();
    let p_name = replace_suffix(&p.name, "");
    let p_ty = ident(&p_name, config, "peripheral", span);
    let doc = util::escape_special_chars(
        util::respace(p.description.as_ref().unwrap_or(&p.name)).as_ref(),
    );

    let mod_ty = ident(&p_name, config, "peripheral_mod", span);
    let (derive_regs, base, path) = if let Some(path) = path {
        (
            true,
            ident(&replace_suffix(&path.peripheral, ""), config, "peripheral_mod", span),
            path,
        )
    } else {
        (false, mod_ty.clone(), BlockPath::new(&p.name))
    };

    let mut feature_attribute = TokenStream::new();
    if config.feature_group && p.group_name.is_some() {
        let feature_name = p.group_name.as_ref().unwrap().to_sanitized_snake_case();
        feature_attribute.extend(quote! { #[cfg(feature = #feature_name)] })
    };

    let phtml = config.settings.html_url.as_ref().map(|url| {
        let doc = format!("See peripheral [structure]({url}#{})", &path.peripheral);
        quote!(#[doc = ""] #[doc = #doc])
    });

    let per_to_tokens = |out: &mut TokenStream,
                         feature_attribute: &TokenStream,
                         description: &str,
                         p_ty: &Ident,
                         doc_alias: Option<TokenStream>,
                         address: proc_macro2::Literal| {
        let p_spec = Ident::new(
            &util::ident_str(&p_ty.to_string(), config, "peripheral_spec"),
            span,
        );
        let name_str = p_ty.to_string();
        out.extend(quote! {
            #[doc = #description]
            #phtml
            #doc_alias
            #feature_attribute
            pub type #p_ty = crate::Periph<#p_spec>;

            #feature_attribute
            pub struct #p_spec;

            #feature_attribute
            impl crate::PeripheralSpec for #p_spec {
                type RB = #base::RegisterBlock;
                const ADDRESS: usize = #address;
                const NAME: &'static str = #name_str;
            }
        });
    };

    match &p {
        MaybeArray::Array(pinfo, dim) => {
            let mut feature_names = Vec::with_capacity(dim.dim as _);
            for pi in expand_peripheral(pinfo, dim) {
                let name = &pi.name;
                let description = util::escape_special_chars(
                    util::respace(pi.description.as_deref().unwrap_or(&pinfo.name)).as_ref(),
                );
                let p_ty = ident(name, config, "peripheral", span);
                let doc_alias =
                    (&p_ty.to_string() != name).then(|| quote!(#[doc(alias = #name)]));
                let address = util::hex(pi.base_address + config.base_address_shift);
                let mut feature_attribute_n = feature_attribute.clone();
                if config.feature_peripheral {
                    let p_feature = name.to_sanitized_snake_case();
                    feature_names.push(p_feature.to_string());
                    feature_attribute_n.extend(quote! { #[cfg(feature = #p_feature)] })
                };
                // Insert the peripherals structure
                per_to_tokens(
                    &mut out,
                    &feature_attribute_n,
                    &description,
                    &p_ty,
                    doc_alias,
                    address,
                );
            }

            let feature_any_attribute = if config.feature_peripheral {
                quote! {#[cfg(any(#(feature = #feature_names),*))]}
            } else {
                quote!()
            };

            // Derived peripherals may not require re-implementation, and will instead
            // use a single definition of the non-derived version.
            if derive_regs {
                // re-export the base peripheral's mod
                out.extend(quote! {
                    #[doc = #doc]
                    #feature_attribute
                    #feature_any_attribute
                    pub use self::#base as #mod_ty;
                });
                return Ok(out);
            }
            feature_attribute.extend(feature_any_attribute);
        }
        MaybeArray::Single(_) => {
            let name = &p.name;
            let doc_alias = (&p_ty.to_string() != name).then(|| quote!(#[doc(alias = #name)]));
            let address = util::hex(p.base_address + config.base_address_shift);
            if config.feature_peripheral {
                let p_feature = p.name.to_sanitized_snake_case();
                feature_attribute.extend(quote! { #[cfg(feature = #p_feature)] })
            };
            per_to_tokens(&mut out, &feature_attribute, &doc, &p_ty, doc_alias, address);

            if derive_regs {
                out.extend(quote! {
                    #[doc = #doc]
                    #feature_attribute
                    pub use self::#base as #mod_ty;
                });
                return Ok(out);
            }
        }
    }

    let description = util::escape_special_chars(
        util::respace(p.description.as_ref().unwrap_or(&p.name)).as_ref(),
    );

    // Build up an alternate erc list by expanding any derived registers/clusters
    // erc: *E*ither *R*egister or *C*luster
    let mut ercs = p.registers.take().unwrap_or_default();

    // No `struct RegisterBlock` can be generated
    if ercs.is_empty() {
        // Drop the definition of the peripheral
        return Ok(TokenStream::new());
    }

    debug!("Checking derivation information");
    let derive_infos = check_erc_derive_infos(&mut ercs, &path, index, config)?;

    debug!("Pushing cluster & register information into output");
    let mod_items = render_ercs(&mut ercs, &derive_infos, &path, index, config)?;

    // Push any register or cluster blocks into the output
    debug!(
        "Pushing {} register or cluster blocks into output",
        ercs.len()
    );
    let reg_block = register_or_cluster_block(&ercs, &derive_infos, None, "Register block", None, config)?;

    let open = Punct::new('{', Spacing::Alone);
    let close = Punct::new('}', Spacing::Alone);

    out.extend(quote! {
        #[doc = #description]
        #feature_attribute
        pub mod #mod_ty #open
    });

    out.extend(reg_block);
    out.extend(mod_items);

    close.to_tokens(&mut out);

    Ok(out)
}

fn derive_peripheral(
    p: &mut Peripheral,
    dpath: &str,
    index: &Index,
) -> Result<Option<BlockPath>> {
    let mut path = None;
    let mut dpath = dpath.to_string();
    loop {
        let derived = index
            .peripherals
            .get(&BlockPath::new(&dpath))
            .ok_or_else(|| anyhow!("peripheral {dpath} not found"))?;
        path = if p.registers.is_none() {
            Some(BlockPath::new(&dpath))
        } else {
            None
        };
        let dim = p.dim().cloned();
        let info = p.derive_from(derived);
        *p = match dim {
            Some(d) => MaybeArray::Array(info, d),
            None => MaybeArray::Single(info),
        };
        if let Some(d) = derived.derived_from.as_ref() {
            dpath = d.clone();
        } else {
            break;
        }
    }
    Ok(path)
}

#[derive(Clone, Debug, PartialEq, Eq)]
pub enum DeriveInfo {
    Root,
    Explicit(RegisterPath),
    Implicit(RegisterPath),
    Cluster, // don't do anything different for clusters
}

impl std::fmt::Display for DeriveInfo {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            DeriveInfo::Root => write!(f, "Root"),
            DeriveInfo::Explicit(rp) => write!(f, "Explicit({rp})"),
            DeriveInfo::Implicit(rp) => write!(f, "Implicit({rp})"),
            DeriveInfo::Cluster => write!(f, "Cluster"),
        }
    }
}

fn check_erc_derive_infos(
    ercs: &mut [RegisterCluster],
    path: &BlockPath,
    index: &Index,
    config: &Config,
) -> Result<Vec<DeriveInfo>> {
    let mut derive_infos: Vec<DeriveInfo> = vec![];
    let mut ercs_type_info: Vec<(String, Option<DimElement>, &RegisterCluster, &DeriveInfo)> = vec![];
    let _ = config;
    for erc in ercs.iter_mut() {
        let derive_info = match erc {
            RegisterCluster::Register(register) => {
                let mut derive_info = DeriveInfo::Root;
                let reg_name = &register.name;
                let ty_name = if register.is_single() {
                    reg_name.clone()
                } else {
                    replace_suffix(reg_name, "")
                };
                let _ = ty_name;
                if let Some(dpath) = register.derived_from.as_ref().cloned() {
                    let rpath = derive_register(register, &dpath, path, index)?;
                    derive_info = DeriveInfo::Explicit(rpath);
                }
                derive_info
            }
            RegisterCluster::Cluster(cluster) => {
                if let Some(dpath) = cluster.derived_from.as_ref().cloned() {
                    derive_cluster(cluster, &dpath, path, index)?;
                }
                DeriveInfo::Cluster
            }
        };
        derive_infos.push(derive_info);
    }
    let _ = &mut ercs_type_info;
    Ok(derive_infos)
}

fn derive_register(
    r: &mut Register,
    dpath: &str,
    path: &BlockPath,
    index: &Index,
) -> Result<RegisterPath> {
    let mut rpath = None;
    let mut dpath = dpath.to_string();
    loop {
        let (dblock, dname) = RegisterPath::parse_str(&dpath);
        let rdpath = if let Some(dblock) = dblock {
            dblock.new_register(dname)
        } else {
            path.new_register(dname)
        };
        let derived = index
            .registers
            .get(&rdpath)
            .ok_or_else(|| anyhow!("register {dpath} not found"))?;
        let dim = r.dim().cloned();
        let info = r.derive_from(derived);
        *r = match dim {
            Some(d) => MaybeArray::Array(info, d),
            None => MaybeArray::Single(info),
        };
        rpath = Some(rdpath);
        if let Some(d) = derived.derived_from.as_ref() {
            dpath = d.clone();
        } else {
            break;
        }
    }
    Ok(rpath.unwrap())
}

fn derive_cluster(
    c: &mut Cluster,
    dpath: &str,
    path: &BlockPath,
    index: &Index,
) -> Result<BlockPath> {
    let mut cpath = None;
    let mut dpath = dpath.to_string();
    loop {
        let (dblock, dname) = BlockPath::parse_str(&dpath);
        let cdpath = if let Some(dblock) = dblock {
            dblock.new_cluster(dname)
        } else {
            path.new_cluster(dname)
        };
        let derived = index
            .clusters
            .get(&cdpath)
            .ok_or_else(|| anyhow!("cluster {dpath} not found"))?;
        let dim = c.dim().cloned();
        let info = c.derive_from(derived);
        *c = match dim {
            Some(d) => MaybeArray::Array(info, d),
            None => MaybeArray::Single(info),
        };
        cpath = Some(cdpath);
        if let Some(d) = derived.derived_from.as_ref() {
            dpath = d.clone();
        } else {
            break;
        }
    }
    Ok(cpath.unwrap())
}

fn render_ercs(
    ercs: &mut [RegisterCluster],
    derive_infos: &[DeriveInfo],
    path: &BlockPath,
    index: &Index,
    config: &Config,
) -> Result<TokenStream> {
    let mut mod_items = TokenStream::new();

    for (erc, derive_info) in ercs.iter_mut().zip(derive_infos) {
        match erc {
            // Generate the sub-cluster blocks.
            RegisterCluster::Cluster(c) => {
                trace!("Cluster: {}", c.name);
                mod_items.extend(cluster_block(c, path, index, config)?);
            }

            // Generate definition for each of the registers.
            RegisterCluster::Register(reg) => {
                trace!("Register: {}, DeriveInfo: {}", reg.name, derive_info);
                let mut rpath = None;
                if let DeriveInfo::Implicit(rp) = derive_info {
                    rpath = Some(rp.clone());
                } else if let DeriveInfo::Explicit(rp) = derive_info {
                    rpath = Some(rp.clone());
                }
                let rendered_reg = register::render(reg, path, rpath, index, config)
                    .with_context(|| format!("can't render register '{}'", reg.name))?;
                mod_items.extend(rendered_reg);
            }
        }
    }
    Ok(mod_items)
}

fn cluster_block(
    c: &mut Cluster,
    path: &BlockPath,
    index: &Index,
    config: &Config,
) -> Result<TokenStream> {
    let description = util::escape_special_chars(&util::respace(
        c.description.as_ref().unwrap_or(&c.name),
    ));
    let mod_name = replace_suffix(&c.name, "");

    // name_snake_case needs to take into account array type.
    let span = Span::call_site();
    let mod_ty = ident(&mod_name, config, "cluster_mod", span);
    let block_ty = ident(&mod_name, config, "cluster", span);

    if let Some(dpath) = c.derived_from.take() {
        let cpath = derive_cluster(c, &dpath, path, index)?;
        let dparent = cpath.parent().unwrap();
        let mut derived = if &dparent == path {
            type_path(Punctuated::new())
        } else {
            util::block_path_to_ty(&dparent, config, span)
        };
        let dname = replace_suffix(&cpath.name(), "");
        let mut mod_derived = derived.clone();
        derived
            .path
            .segments
            .push(path_segment(ident(&dname, config, "cluster", span)));
        mod_derived
            .path
            .segments
            .push(path_segment(ident(&dname, config, "cluster_mod", span)));

        Ok(quote! {
            pub use #derived as #block_ty;
            pub use #mod_derived as #mod_ty;
        })
    } else {
        let cpath = path.new_cluster(&c.name);
        let mut children = std::mem::take(&mut c.children);
        let derive_infos = check_erc_derive_infos(&mut children, &cpath, index, config)?;
        let mod_items = render_ercs(&mut children, &derive_infos, &cpath, index, config)?;

        // Generate the register block.
        let cluster_size = match c {
            MaybeArray::Array(_, array_info) if config.max_cluster_size => {
                Some(array_info.dim_increment)
            }
            _ => None,
        };
        let reg_block = register_or_cluster_block(
            &children,
            &derive_infos,
            Some(&mod_name),
            &description,
            cluster_size,
            config,
        )?;
        c.children = children;

        let mod_items = quote! {
            #reg_block
            #mod_items
        };

        Ok(quote! {
            #[doc = #description]
            pub use self::#mod_ty::#block_ty;

            ///Cluster
            #[doc = #description]
            pub mod #mod_ty {
                #mod_items
            }
        })
    }
}

// ---------------------------------------------------------------------------
// Register block

#[derive(Clone, Debug)]
struct RegisterBlockField {
    syn_field: syn::Field,
    offset: u32,
    size: u32,
    accessors: Vec<AccessType>,
}

#[derive(Clone, Debug)]
struct Region {
    rbfs: Vec<RegisterBlockField>,
    offset: u32,
    end: u32,
    /// This is only used for regions with `rbfs.len() > 1`
    pub ident: Option<String>,
}

impl Region {
    fn shortest_ident(&self) -> Option<String> {
        let mut idents: Vec<_> = self
            .rbfs
            .iter()
            .filter_map(|f| f.syn_field.ident.as_ref().map(ToString::to_string))
            .collect();
        if idents.is_empty() {
            return None;
        }
        idents.sort_by(|a, b| {
            // Sort by length and then content
            match a.len().cmp(&b.len()) {
                Ordering::Equal => a.cmp(b),
                cmp => cmp,
            }
        });
        Some(idents[0].to_owned())
    }

    fn common_ident(&self) -> Option<String> {
        // https://stackoverflow.com/a/40296745/4284367
        fn split_keep(text: &str) -> Vec<&str> {
            let mut result = Vec::new();
            let mut last = 0;
            for (index, matched) in
                text.match_indices(|c: char| c.is_numeric() || !(c.is_alphabetic() || c == '_'))
            {
                if last != index {
                    result.push(&text[last..index]);
                }
                result.push(matched);
                last = index + matched.len();
            }
            if last < text.len() {
                result.push(&text[last..]);
            }

            result
        }

        let idents: Vec<_> = self
            .rbfs
            .iter()
            .filter_map(|f| f.syn_field.ident.as_ref().map(ToString::to_string))
            .collect();

        if idents.is_empty() {
            return None;
        }

        let x: Vec<_> = idents.iter().map(|i| split_keep(i)).collect();
        let mut index = 0;
        let first = &x[0];
        // Get first elem, check against all other, break on mismatch
        'outer: while index < first.len() {
            for ident_match in x.iter().skip(1) {
                if let Some(match_) = ident_match.get(index) {
                    if match_ != &first[index] {
                        break 'outer;
                    }
                } else {
                    break 'outer;
                }
            }
            index += 1;
        }
        if index <= 1 {
            None
        } else {
            Some(match first.get(index) {
                Some(elem) if elem.chars().all(|c| c.is_numeric()) => {
                    first.iter().take(index).cloned().collect()
                }
                _ => first.iter().take(index - 1).cloned().collect(),
            })
        }
    }

    fn compute_ident(&self) -> Option<String> {
        if let Some(ident) = self.common_ident() {
            Some(ident)
        } else {
            self.shortest_ident()
        }
    }

    fn is_union(&self) -> bool {
        self.rbfs.len() > 1
    }
}

/// FieldRegions keeps track of overlapping field regions,
/// merging fields into appropriate regions as we process them.
/// This allows us to reason about when to create a union
/// rather than a struct.
#[derive(Default, Debug)]
struct FieldRegions {
    /// The set of regions we know about.  This is maintained
    /// in sorted order, keyed by Region::offset.
    regions: Vec<Region>,
}

impl FieldRegions {
    /// Track a field.  If the field overlaps with 1 or more existing
    /// entries, they will be merged together.
    fn add(&mut self, rbf: &RegisterBlockField) -> Result<()> {
        // When merging, this holds the indices in self.regions
        // that the input `rbf` will be merging with.
        let mut indices = Vec::new();

        let rbf_start = rbf.offset;
        let rbf_end = rbf.offset + (rbf.size + BITS_PER_BYTE - 1) / BITS_PER_BYTE;

        // The region that we're going to insert
        let mut new_region = Region {
            rbfs: vec![rbf.clone()],
            offset: rbf.offset,
            end: rbf_end,
            ident: None,
        };

        for (idx, f) in self.regions.iter_mut().enumerate() {
            // Compute intersection range
            let begin = f.offset.max(rbf_start);
            let end = f.end.min(rbf_end);

            if end > begin {
                // We're going to remove this element and fold it
                // into our new region
                indices.push(idx);
                new_region.rbfs.append(&mut f.rbfs);
                new_region.offset = new_region.offset.min(f.offset);
                new_region.end = new_region.end.max(f.end);
            }
        }

        // Remove the entries that we collapsed together.
        // We do this in reverse order to ensure that the indices
        // are stable in the face of removal.
        for idx in indices.iter().rev() {
            self.regions.remove(*idx);
        }

        new_region.rbfs.sort_by_key(|f| f.offset);
        self.regions.push(new_region);
        self.regions.sort_by_key(|r| r.offset);
        Ok(())
    }

    /// Resolves type name conflicts
    pub fn resolve_idents(&mut self) -> Result<()> {
        let idents: Vec<_> = {
            self.regions
                .iter_mut()
                .filter(|r| r.rbfs.len() > 1)
                .map(|r| {
                    r.ident = r.compute_ident();
                    r.ident.clone()
                })
                .collect()
        };
        self.regions
            .iter_mut()
            .filter(|r| r.ident.is_some())
            .filter(|r| {
                r.rbfs.len() > 1 && (idents.iter().filter(|&ident| ident == &r.ident).count() > 1)
            })
            .for_each(|r| {
                let new_ident = r.shortest_ident();
                warn!(
                    "Found type name conflict with region {:?}, renamed to {:?}",
                    r.ident, new_ident
                );
                r.ident = new_ident;
            });
        Ok(())
    }
}

fn make_comment(size: u32, offset: u32, description: &str) -> String {
    let desc = util::escape_special_chars(&util::respace(description));
    if size > 32 {
        let end = offset + size / 8;
        format!("0x{offset:02x}..0x{end:02x} - {desc}")
    } else {
        format!("0x{offset:02x} - {desc}")
    }
}

fn register_or_cluster_block(
    ercs: &[RegisterCluster],
    derive_infos: &[DeriveInfo],
    name: Option<&str>,
    doc: &str,
    size: Option<u32>,
    config: &Config,
) -> Result<TokenStream> {
    let mut rbfs = TokenStream::new();
    let mut accessors = TokenStream::new();

    let ercs_expanded = expand(ercs, derive_infos, config)
        .with_context(|| "Could not expand register or cluster block")?;

    // Locate conflicting regions; we'll need to use unions to represent them.
    let mut regions = FieldRegions::default();

    for reg_block_field in &ercs_expanded {
        regions.add(reg_block_field)?;
    }

    // We need to compute the idents of each register/union block first to make sure no conflicts exists.
    regions.resolve_idents()?;
    // The end of the region for which we previously emitted a rbf into `rbfs`
    let mut last_end = 0;

    let span = Span::call_site();
    for (i, region) in regions.regions.iter().enumerate() {
        // Check if we need padding
        let pad = region.offset - last_end;
        if pad != 0 {
            let name = Ident::new(&format!("_reserved{i}"), span);
            let pad = util::hex(pad as u64);
            rbfs.extend(quote! {
                #name : [u8; #pad],
            });
        }

        let mut region_rbfs = TokenStream::new();
        let is_region_a_union = region.is_union();

        for reg_block_field in &region.rbfs {
            if is_region_a_union {
                for acc in &reg_block_field.accessors {
                    accessors.extend(acc.raw_if(is_region_a_union).to_token_stream());
                }
            } else {
                reg_block_field.syn_field.to_tokens(&mut region_rbfs);
                Punct::new(',', Spacing::Alone).to_tokens(&mut region_rbfs);
                for acc in &reg_block_field.accessors {
                    accessors.extend(acc.to_token_stream());
                }
            }
        }

        if !is_region_a_union {
            rbfs.extend(region_rbfs);
        } else {
            // Emit padding for the items that we're not emitting
            // as rbfs so that other rbfs have the correct names
            let name = Ident::new(
                &format!(
                    "_reserved_{}_{}",
                    i,
                    region.ident.as_ref().unwrap_or(&String::new())
                ),
                span,
            );
            let pad = util::hex((region.end - region.offset) as u64);
            rbfs.extend(quote! {
                #name: [u8; #pad],
            });
        }
        last_end = region.end;
    }

    if let Some(size) = size {
        let pad = size
            .checked_sub(last_end)
            .ok_or_else(|| anyhow!("Cluster size {size} is less than its members size {last_end}"))?;
        if pad > 0 {
            let pad = util::hex(pad as u64);
            rbfs.extend(quote! {
                _reserved_end : [u8; #pad],
            });
        }
    }

    let derive_debug = if config.impl_debug {
        if let Some(feature_name) = &config.impl_debug_feature {
            quote!(#[cfg_attr(feature = #feature_name, derive(Debug))])
        } else {
            quote!(#[derive(Debug)])
        }
    } else {
        quote!()
    };

    let (name, doc_alias) = match name {
        Some(name) => {
            let block_ty = ident(name, config, "cluster", span);
            let doc_alias = (block_ty.to_string().as_str() != name).then(|| quote!(#[doc(alias = #name)]));
            (block_ty, doc_alias)
        }
        None => (Ident::new("RegisterBlock", span), None),
    };

    let accessors = if accessors.is_empty() {
        quote!()
    } else {
        quote!(impl #name { #accessors })
    };

    Ok(quote! {
        ///Register block
        #[repr(C)]
        #derive_debug
        #[doc = #doc]
        #doc_alias
        pub struct #name {
            #rbfs
        }

        #accessors
    })
}

/// Expand a list of parsed `Register`s or `Cluster`s, and render them to
/// `RegisterBlockField`s containing `Field`s.
fn expand(
    ercs: &[RegisterCluster],
    derive_infos: &[DeriveInfo],
    config: &Config,
) -> Result<Vec<RegisterBlockField>> {
    let mut ercs_expanded = vec![];

    debug!("Expanding registers or clusters into Register Block Fields");
    for (erc, derive_info) in ercs.iter().zip(derive_infos) {
        match &erc {
            RegisterCluster::Register(register) => {
                let reg_name = &register.name;
                let expanded_reg = expand_register(register, derive_info, config)
                    .with_context(|| format!("can't expand register {reg_name}"))?;
                trace!("Register: {reg_name}");
                ercs_expanded.extend(expanded_reg);
            }
            RegisterCluster::Cluster(cluster) => {
                let cluster_name = &cluster.name;
                let expanded_cluster = expand_cluster(cluster, config)
                    .with_context(|| format!("can't expand cluster {cluster_name}"))?;
                trace!("Cluster: {cluster_name}");
                ercs_expanded.extend(expanded_cluster);
            }
        };
    }

    ercs_expanded.sort_by_key(|x| x.offset);

    Ok(ercs_expanded)
}

/// Calculate the size of a Cluster.  If it is an array, then the dimensions
/// tell us the size of the array.  Otherwise, inspect the contents using
/// [cluster_info_size_in_bits].
fn cluster_size_in_bits(cluster: &Cluster, config: &Config) -> Result<u32> {
    match cluster {
        MaybeArray::Single(info) => cluster_info_size_in_bits(info, config),
        // If the contained array cluster has a mismatch between the
        // dimIncrement and the size of the array items, then the array
        // will get expanded in expand_cluster below.  The overall size
        // then ends at the last array entry.
        MaybeArray::Array(info, dim) => {
            if dim.dim == 0 {
                return Ok(0); // Special case!
            }
            let last_offset = (dim.dim - 1) * dim.dim_increment * BITS_PER_BYTE;
            let last_size = cluster_info_size_in_bits(info, config);
            Ok(last_offset + last_size?)
        }
    }
}

/// Recursively calculate the size of a cluster. A cluster's size is the maximum
/// end position of its recursive children.
fn cluster_info_size_in_bits(info: &ClusterInfo, config: &Config) -> Result<u32> {
    let mut size = 0;

    for c in &info.children {
        let end = match c {
            RegisterCluster::Register(reg) => {
                let reg_size: u32 = expand_register(reg, &DeriveInfo::Root, config)?
                    .iter()
                    .map(|rbf| rbf.size)
                    .sum();

                (reg.address_offset * BITS_PER_BYTE) + reg_size
            }
            RegisterCluster::Cluster(clust) => {
                (clust.address_offset * BITS_PER_BYTE) + cluster_size_in_bits(clust, config)?
            }
        };

        size = size.max(end);
    }
    Ok(size)
}

fn name_to_ty(name: &str, config: &Config, fmt: &str) -> syn::Type {
    let span = Span::call_site();
    syn::Type::Path(util::ident_to_path(ident(name, config, fmt, span)))
}

fn array_ty(ty: syn::Type, len: u32) -> syn::Type {
    util::array_ty(ty, len, Span::call_site())
}

fn new_syn_field(ident: Ident, ty: syn::Type) -> syn::Field {
    util::new_field(ident, ty)
}

/// Render a given cluster (and any children) into `RegisterBlockField`s
fn expand_cluster(cluster: &Cluster, config: &Config) -> Result<Vec<RegisterBlockField>> {
    let mut cluster_expanded = vec![];

    let cluster_size = cluster_info_size_in_bits(cluster, config)
        .with_context(|| format!("Can't calculate cluster {} size", cluster.name))?;
    let description = cluster.description.as_ref().unwrap_or(&cluster.name);

    let span = Span::call_site();
    let ty_name = replace_suffix(&cluster.name, "");
    let ty = name_to_ty(&ty_name, config, "cluster");

    match cluster {
        MaybeArray::Single(info) => {
            let doc = make_comment(cluster_size, info.address_offset, description);
            let name: Ident = ident(&ty_name, config, "cluster_accessor", span);
            let syn_field = new_syn_field(name.clone(), ty.clone());
            cluster_expanded.push(RegisterBlockField {
                syn_field,
                offset: info.address_offset,
                size: cluster_size,
                accessors: vec![AccessType::Reg(Accessor {
                    doc,
                    name,
                    ty,
                    offset: info.address_offset,
                })],
            })
        }
        MaybeArray::Array(info, array_info) => {
            let sequential_addresses = (array_info.dim == 1)
                || (cluster_size == array_info.dim_increment * BITS_PER_BYTE);

            let convert_list = match config.keep_list {
                true => match &array_info.dim_name {
                    Some(dim_name) => dim_name.contains("[%s]"),
                    None => info.name.contains("[%s]"),
                },
                false => true,
            };

            let array_convertible = sequential_addresses && convert_list;

            if array_convertible || (config.max_cluster_size && convert_list) {
                let cluster_size = if config.max_cluster_size {
                    array_info.dim_increment * BITS_PER_BYTE
                } else {
                    cluster_size
                };
                let accessor_name = ident(&ty_name, config, "cluster_accessor", span);
                let doc = make_comment(
                    cluster_size * array_info.dim,
                    info.address_offset,
                    description,
                );
                let mut accessors = Vec::with_capacity((array_info.dim + 1) as _);
                let first_name = replace_suffix(&info.name, &array_info.indexes()[0]);
                let note = (array_info.indexes_as_range().map(|r| *r.start()) != Some(0)).then(|| {
                    format!("<div class=\"warning\">`n` is the index of cluster in the array. `n == 0` corresponds to `{first_name}` cluster.</div>")
                });
                accessors.push(AccessType::Array(ArrayAccessor {
                    doc,
                    name: accessor_name.clone(),
                    ty: ty.clone(),
                    offset: info.address_offset,
                    dim: array_info.dim,
                    increment: array_info.dim_increment,
                    note,
                }));
                if array_info.indexes_as_range().map(|r| *r.start()) != Some(0) || !sequential_indexes_from0(array_info) {
                    for (i, idx) in array_info.indexes().iter().enumerate() {
                        let doc = make_comment(
                            cluster_size,
                            info.address_offset + (i as u32) * array_info.dim_increment,
                            &description.replace("%s", idx),
                        );
                        let name = ident(&replace_suffix(&info.name, idx), config, "cluster_accessor", span);
                        accessors.push(AccessType::ArrayElem(ArrayElemAccessor {
                            doc,
                            name,
                            ty: ty.clone(),
                            basename: accessor_name.clone(),
                            i,
                        }));
                    }
                }
                let array_ty = array_ty(ty, array_info.dim);
                let syn_field = new_syn_field(accessor_name, array_ty);
                cluster_expanded.push(RegisterBlockField {
                    syn_field,
                    offset: info.address_offset,
                    size: cluster_size * array_info.dim,
                    accessors,
                });
            } else if sequential_indexes_from0(array_info) && config.keep_list == false && false {
                unreachable!()
            } else if sequential_addresses || !config.keep_list {
                // RawArray accessor with zero-sized placeholder when not convertible
                // (used when addresses are not sequential)
                let accessor_name = ident(&ty_name, config, "cluster_accessor", span);
                let doc = make_comment(
                    cluster_size * array_info.dim,
                    info.address_offset,
                    description,
                );
                let first_name = replace_suffix(&info.name, &array_info.indexes()[0]);
                let note = (array_info.indexes_as_range().map(|r| *r.start()) != Some(0)).then(|| {
                    format!("<div class=\"warning\">`n` is the index of cluster in the array. `n == 0` corresponds to `{first_name}` cluster.</div>")
                });
                let mut accessors = vec![AccessType::RawArray(ArrayAccessor {
                    doc,
                    name: accessor_name.clone(),
                    ty: ty.clone(),
                    offset: info.address_offset,
                    dim: array_info.dim,
                    increment: array_info.dim_increment,
                    note,
                })];
                if !sequential_indexes_from0(array_info) {
                    for (i, idx) in array_info.indexes().iter().enumerate() {
                        let doc = make_comment(
                            cluster_size,
                            info.address_offset + (i as u32) * array_info.dim_increment,
                            &description.replace("%s", idx),
                        );
                        let name = ident(&replace_suffix(&info.name, idx), config, "cluster_accessor", span);
                        accessors.push(AccessType::ArrayElem(ArrayElemAccessor {
                            doc,
                            name,
                            ty: ty.clone(),
                            basename: accessor_name.clone(),
                            i,
                        }));
                    }
                }
                let syn_field = new_syn_field(accessor_name, zst_type());
                cluster_expanded.push(RegisterBlockField {
                    syn_field,
                    offset: info.address_offset,
                    size: 0,
                    accessors,
                });
            } else {
                for (i, idx) in array_info.indexes().iter().enumerate() {
                    let nb_name = replace_suffix(&info.name, idx);
                    let name = ident(&nb_name, config, "cluster_accessor", span);
                    let offset = info.address_offset + (i as u32) * array_info.dim_increment;
                    let doc = make_comment(cluster_size, offset, &description.replace("%s", idx));
                    let syn_field = new_syn_field(name.clone(), ty.clone());
                    cluster_expanded.push(RegisterBlockField {
                        syn_field,
                        offset,
                        size: cluster_size,
                        accessors: vec![AccessType::Reg(Accessor {
                            doc,
                            name,
                            ty: ty.clone(),
                            offset,
                        })],
                    });
                }
            }
        }
    }

    Ok(cluster_expanded)
}

fn sequential_indexes_from0(dim: &DimElement) -> bool {
    match dim.indexes_as_range() {
        Some(r) => *r.start() == 0,
        None => false,
    }
}

/// If svd register arrays can't be converted to rust arrays (non sequential addresses, non
/// numeral indexes, or not containing all elements from 0 to size) they will be expanded
fn expand_register(
    register: &Register,
    derive_info: &DeriveInfo,
    config: &Config,
) -> Result<Vec<RegisterBlockField>> {
    let mut register_expanded = vec![];

    let register_size = register
        .properties
        .size
        .ok_or_else(|| anyhow!("Register {} has no `size` field", register.name))?;
    let description = register.description.clone().unwrap_or_default();

    let info_name = name_of(&**register, config.ignore_groups).into_owned();
    let mut ty_name = if register.is_single() {
        info_name.to_string()
    } else {
        replace_suffix(&info_name, "")
    };
    let _ = derive_info;
    let span = Span::call_site();

    match register {
        MaybeArray::Single(info) => {
            let doc = make_comment(register_size, info.address_offset, &description);
            let ty = name_to_ty(&ty_name, config, "register");
            let name = ident(&info_name, config, "register_accessor", span);
            let syn_field = new_syn_field(name.clone(), ty.clone());
            register_expanded.push(RegisterBlockField {
                syn_field,
                offset: info.address_offset,
                size: register_size,
                accessors: vec![AccessType::Reg(Accessor {
                    doc,
                    name,
                    ty,
                    offset: info.address_offset,
                })],
            })
        }
        MaybeArray::Array(info, array_info) => {
            let sequential_addresses = (array_info.dim == 1)
                || (register_size == array_info.dim_increment * BITS_PER_BYTE);
            let convert_list = match config.keep_list {
                true => match &array_info.dim_name {
                    Some(dim_name) => dim_name.contains("[%s]"),
                    None => info.name.contains("[%s]"),
                },
                false => true,
            };
            let array_convertible = sequential_addresses && convert_list;
            if let DeriveInfo::Implicit(_) = derive_info {
                ty_name = replace_suffix(&info.fullname(config.ignore_groups), "");
            }
            let ty = name_to_ty(&ty_name, config, "register");

            if array_convertible {
                let accessor_name = ident(&ty_name, config, "register_accessor", span);
                let doc = make_comment(
                    register_size * array_info.dim,
                    info.address_offset,
                    &description,
                );
                let mut accessors = Vec::with_capacity((array_info.dim + 1) as _);
                let first_name = replace_suffix(&info_name, &array_info.indexes()[0]);
                let note = (!sequential_indexes_from0(array_info)).then(|| {
                    format!("<div class=\"warning\">`n` is the index of register in the array. `n == 0` corresponds to `{first_name}` register.</div>")
                });
                accessors.push(AccessType::Array(ArrayAccessor {
                    doc,
                    name: accessor_name.clone(),
                    ty: ty.clone(),
                    offset: info.address_offset,
                    dim: array_info.dim,
                    increment: array_info.dim_increment,
                    note,
                }));
                if !sequential_indexes_from0(array_info) {
                    for (i, idx) in array_info.indexes().iter().enumerate() {
                        let doc = make_comment(
                            register_size,
                            info.address_offset + (i as u32) * array_info.dim_increment,
                            &description.replace("%s", idx),
                        );
                        let name = ident(&replace_suffix(&info_name, idx), config, "register_accessor", span);
                        accessors.push(AccessType::ArrayElem(ArrayElemAccessor {
                            doc,
                            name,
                            ty: ty.clone(),
                            basename: accessor_name.clone(),
                            i,
                        }));
                    }
                }
                let array_ty = array_ty(ty, array_info.dim);
                let syn_field = new_syn_field(accessor_name, array_ty);
                register_expanded.push(RegisterBlockField {
                    syn_field,
                    offset: info.address_offset,
                    size: register_size * array_info.dim,
                    accessors,
                });
            } else if !config.keep_list {
                let accessor_name = ident(&ty_name, config, "register_accessor", span);
                let doc = make_comment(
                    register_size * array_info.dim,
                    info.address_offset,
                    &description,
                );
                let first_name = replace_suffix(&info_name, &array_info.indexes()[0]);
                let note = (!sequential_indexes_from0(array_info)).then(|| {
                    format!("<div class=\"warning\">`n` is the index of register in the array. `n == 0` corresponds to `{first_name}` register.</div>")
                });
                let mut accessors = vec![AccessType::RawArray(ArrayAccessor {
                    doc,
                    name: accessor_name.clone(),
                    ty: ty.clone(),
                    offset: info.address_offset,
                    dim: array_info.dim,
                    increment: array_info.dim_increment,
                    note,
                })];
                if !sequential_indexes_from0(array_info) {
                    for (i, idx) in array_info.indexes().iter().enumerate() {
                        let doc = make_comment(
                            register_size,
                            info.address_offset + (i as u32) * array_info.dim_increment,
                            &description.replace("%s", idx),
                        );
                        let name = ident(&replace_suffix(&info_name, idx), config, "register_accessor", span);
                        accessors.push(AccessType::ArrayElem(ArrayElemAccessor {
                            doc,
                            name,
                            ty: ty.clone(),
                            basename: accessor_name.clone(),
                            i,
                        }));
                    }
                }
                let syn_field = new_syn_field(accessor_name, zst_type());
                register_expanded.push(RegisterBlockField {
                    syn_field,
                    offset: info.address_offset,
                    size: 0,
                    accessors,
                });
            } else {
                for (i, idx) in array_info.indexes().iter().enumerate() {
                    let nb_name = replace_suffix(&info_name, idx);
                    let doc = make_comment(
                        register_size,
                        info.address_offset,
                        &description.replace("%s", idx),
                    );
                    let name = ident(&nb_name, config, "register_accessor", span);
                    let syn_field = new_syn_field(name.clone(), ty.clone());
                    let offset = info.address_offset + (i as u32) * array_info.dim_increment;
                    register_expanded.push(RegisterBlockField {
                        syn_field,
                        offset,
                        size: register_size,
                        accessors: vec![AccessType::Reg(Accessor {
                            doc,
                            name,
                            ty: ty.clone(),
                            offset,
                        })],
                    });
                }
            }
        }
    }

    Ok(register_expanded)
}

// ---------------------------------------------------------------------------
// Accessors

#[derive(Clone, Debug)]
pub enum AccessType {
    Reg(Accessor),
    Raw(Accessor),
    Array(ArrayAccessor),
    RawArray(ArrayAccessor),
    ArrayElem(ArrayElemAccessor),
}

impl AccessType {
    fn raw_if(&self, flag: bool) -> Self {
        match self {
            Self::Reg(a) if flag => Self::Raw(a.clone()),
            Self::Array(a) if flag => Self::RawArray(a.clone()),
            _ => self.clone(),
        }
    }
}

impl ToTokens for AccessType {
    fn to_tokens(&self, tokens: &mut TokenStream) {
        match self {
            Self::Reg(a) => a.to_tokens(tokens),
            Self::Raw(a) => RawAccessor(a).to_tokens(tokens),
            Self::Array(a) => a.to_tokens(tokens),
            Self::RawArray(a) => RawArrayAccessor(a).to_tokens(tokens),
            Self::ArrayElem(a) => a.to_tokens(tokens),
        }
    }
}

#[derive(Clone, Debug)]
pub struct Accessor {
    pub doc: String,
    pub name: Ident,
    pub ty: syn::Type,
    pub offset: u32,
}

impl ToTokens for Accessor {
    fn to_tokens(&self, tokens: &mut TokenStream) {
        let Self { doc, name, ty, .. } = self;
        quote! {
            #[doc = #doc]
            #[inline(always)]
            pub const fn #name(&self) -> &#ty {
                &self.#name
            }
        }
        .to_tokens(tokens);
    }
}

struct RawAccessor<'a>(&'a Accessor);

impl ToTokens for RawAccessor<'_> {
    fn to_tokens(&self, tokens: &mut TokenStream) {
        let Accessor { doc, name, ty, offset } = self.0;
        let offset = (*offset != 0).then(|| {
            let offset = unsuffixed(*offset as u64);
            quote!(.add(#offset))
        });
        quote! {
            #[doc = #doc]
            #[inline(always)]
            pub const fn #name(&self) -> &#ty {
                unsafe { &*core::ptr::from_ref(self).cast::<u8>() #offset .cast() }
            }
        }
        .to_tokens(tokens);
    }
}

#[derive(Clone, Debug)]
pub struct ArrayAccessor {
    pub doc: String,
    pub name: Ident,
    pub ty: syn::Type,
    pub offset: u32,
    pub dim: u32,
    pub increment: u32,
    pub note: Option<String>,
}

impl ToTokens for ArrayAccessor {
    fn to_tokens(&self, tokens: &mut TokenStream) {
        let Self { doc, name, ty, note, .. } = self;
        let name_iter = Ident::new(&format!("{name}_iter"), Span::call_site());
        let note = note.as_ref().map(|note| {
            quote! {
                #[doc = ""]
                #[doc = #note]
            }
        });
        quote! {
            #[doc = #doc]
            #note
            #[inline(always)]
            pub const fn #name(&self, n: usize) -> &#ty {
                &self.#name[n]
            }
            #[doc = "Iterator for array of:"]
            #[doc = #doc]
            #[inline(always)]
            pub fn #name_iter(&self) -> impl Iterator<Item=&#ty> {
                self.#name.iter()
            }
        }
        .to_tokens(tokens);
    }
}

struct RawArrayAccessor<'a>(&'a ArrayAccessor);

impl ToTokens for RawArrayAccessor<'_> {
    fn to_tokens(&self, tokens: &mut TokenStream) {
        let ArrayAccessor {
            doc,
            name,
            ty,
            offset,
            dim,
            increment,
            note,
        } = self.0;
        let name_iter = Ident::new(&format!("{name}_iter"), Span::call_site());
        let offset = (*offset != 0).then(|| {
            let offset = unsuffixed(*offset as u64);
            quote!(.add(#offset))
        });
        let dim = unsuffixed(*dim as u64);
        let increment = (*increment != 1).then(|| {
            let increment = unsuffixed(*increment as u64);
            quote!(#increment *)
        });
        let note = note.as_ref().map(|note| {
            quote! {
                #[doc = ""]
                #[doc = #note]
            }
        });
        let cast = quote! { unsafe { &*core::ptr::from_ref(self).cast::<u8>() #offset .add(#increment n).cast() } };
        quote! {
            #[doc = #doc]
            #note
            #[inline(always)]
            pub const fn #name(&self, n: usize) -> &#ty {
                #[allow(clippy::no_effect)]
                [(); #dim][n];
                #cast
            }
            #[doc = "Iterator for array of:"]
            #[doc = #doc]
            #[inline(always)]
            pub fn #name_iter(&self) -> impl Iterator<Item=&#ty> {
                (0..#dim).map(move |n| #cast)
            }
        }
        .to_tokens(tokens);
    }
}

#[derive(Clone, Debug)]
pub struct ArrayElemAccessor {
    pub doc: String,
    pub name: Ident,
    pub ty: syn::Type,
    pub basename: Ident,
    pub i: usize,
}

impl ToTokens for ArrayElemAccessor {
    fn to_tokens(&self, tokens: &mut TokenStream) {
        let Self {
            doc,
            name,
            ty,
            basename,
            i,
        } = &self;
        let i = unsuffixed(*i as u64);
        quote! {
            #[doc = #doc]
            #[inline(always)]
            pub const fn #name(&self) -> &#ty {
                self.#basename(#i)
            }
        }
        .to_tokens(tokens);
    }
}

