fn load_config(matches: &clap::ArgMatches) -> Result<(Config, Vec<String>)> {
    // Base: TOML config file
    let mut table = toml::Table::new();
    if let Some(cfg_path) = matches.get_one::<String>("config") {
        let path = Path::new(cfg_path);
        if path.exists() {
            let text = std::fs::read_to_string(path)
                .with_context(|| "Failed to parse value for parser #2")?;
            let parsed: toml::Table = toml::from_str(&text)
                .map_err(|e| anyhow::anyhow!(e))
                .with_context(|| "Failed parse TOML")
                .with_context(|| "Failed to parse value for parser #2")?;
            table = parsed;
        }
    }

    // Overlay: CLI arguments
    for key in STRING_ARGS {
        if let Some(v) = matches.get_one::<String>(key) {
            table.insert(key.to_string(), toml::Value::String(v.clone()));
        }
    }
    for key in BOOL_ARGS {
        if matches.get_flag(key) {
            table.insert(key.to_string(), toml::Value::Boolean(true));
        }
    }

    let ident_formats: Vec<String> = matches
        .get_many::<String>("ident_format")
        .map(|v| v.cloned().collect())
        .unwrap_or_default();

    let config: Config = table
        .try_into()
        .map_err(|e| anyhow::anyhow!(e))
        .with_context(|| "Failed to deserialize value")?;
    Ok((config, ident_formats))
}

fn run() -> Result<()> {
    let matches = build_cli().get_matches();

    let (mut config, ident_formats) = load_config(&matches)?;

    // logging
    let log_level = config.log_level.clone();
    setup_logging(log_level.as_deref());

    let input = config.input.clone();
    let path = config
        .output_dir
        .clone()
        .unwrap_or_else(|| PathBuf::from("."));

    // ident formats
    let mut idf = match config.ident_formats_theme {
        Some(IdentFormatsTheme::Legacy) => IdentFormats::legacy_theme(),
        None => IdentFormats::new_theme(),
    };
    idf.extend(config.ident_formats.0.drain());
    config.ident_formats = idf;

    for f in ident_formats {
        if let Some((name, fmt)) = f.split_once(':') {
            if let Ok(fmt) = IdentFormat::parse(fmt) {
                if config.ident_formats.contains_key(name) {
                    config.ident_formats.insert(name.to_string(), fmt);
                }
            }
        }
    }

    debug!("Current svd2rust config: {config:#?}");

    // settings
    if let Some(settings_file) = config.settings_file.as_ref() {
        let settings_text = std::fs::read_to_string(settings_file)
            .with_context(|| "Cannot open the settings file")?;
        let settings: Settings = serde_yaml::from_str(&settings_text)
            .with_context(|| "Error parsing settings file")?;
        config.settings.update_from(settings);
    }

    let mut xml = String::new();
    match input.as_ref() {
        Some(file) => {
            File::open(file)
                .context("Cannot open the SVD file")?
                .read_to_string(&mut xml)
                .context("Cannot read the SVD file")?;
        }
        None => {
            let stdin = std::io::stdin();
            stdin
                .lock()
                .read_to_string(&mut xml)
                .context("Cannot read from stdin")?;
        }
    }

    if let Some(file) = input.as_ref() {
        // source type from extension if not specified explicitly
        if !matches.contains_id("source_type") {
            config.source_type = SourceType::from_path(file);
        }
    }

    info!("Parsing device from SVD file");
    let device = load_from(&xml, &config)?;

    let mut device_x = String::new();
    info!("Rendering device");
    let items = generate::device::render(&device, &config, &mut device_x)
        .with_context(|| "Error rendering device")?;

    let filename = if config.make_mod { "mod.rs" } else { "lib.rs" };
    let mut file = File::create(path.join(filename)).expect("Couldn't create output file");

    let data = items.to_string().replace(" # [", "\n#[");
    file.write_all(data.as_ref())
        .expect("Could not write code to lib.rs");

    if config.generic_mod {
        let mut file = File::create(path.join("generic.rs"))?;
        let text = generate::generic::generic_text(&config);
        writeln!(file, "{text}")?;
    }

    if config.feature_group || config.feature_peripheral {
        let mut features = String::new();
        features.push_str("# Below are the FEATURES generated by svd2rust base on groupName in SVD file.\n");
        features.push_str("# Please copy them to Cargo.toml.\n");
        features.push_str("[features]\n");
        if config.feature_group {
            let groups = feature_groups(&device);
            for g in &groups {
                features.push_str(&format!("{g} = []\n"));
            }
            features.push_str(&format!(
                "all-groups = [{}]\n",
                groups
                    .iter()
                    .map(|g| format!("\"{g}\""))
                    .collect::<Vec<_>>()
                    .join(",")
            ));
        }
        if config.feature_peripheral {
            let names = feature_peripherals(&device);
            for n in &names {
                features.push_str(&format!("{n} = []\n"));
            }
            features.push_str(&format!(
                "all-peripherals = [{}]\n",
                names
                    .iter()
                    .map(|n| format!("\"{n}\""))
                    .collect::<Vec<_>>()
                    .join(",")
            ));
        }
        let mut file = File::create(path.join("features.toml"))?;
        file.write_all(features.as_bytes())?;
    }

    if matches!(
        config.target,
        Target::CortexM | Target::Msp430 | Target::XtensaLX | Target::RISCV
    ) {
        writeln!(File::create(path.join("device.x"))?, "{device_x}")?;
        writeln!(File::create(path.join("build.rs"))?, "{}", util::build_rs())?;
    }

    Ok(())
}

fn feature_groups(device: &svd::Device) -> Vec<String> {
    use crate::util::ToSanitizedCase;
    let mut set = std::collections::BTreeSet::new();
    for p in &device.peripherals {
        if let Some(g) = p.group_name.as_ref() {
            set.insert(g.to_sanitized_snake_case().into_owned());
        }
    }
    set.into_iter().collect()
}

fn feature_peripherals(device: &svd::Device) -> Vec<String> {
    use crate::util::ToSanitizedCase;
    let mut set = std::collections::BTreeSet::new();
    for p in &device.peripherals {
        match p {
            svd::MaybeArray::Single(info) => {
                set.insert(info.name.to_sanitized_snake_case().into_owned());
            }
            svd::MaybeArray::Array(info, dim) => {
                for pi in generate::peripheral::expand_peripheral(info, dim) {
                    set.insert(pi.name.to_sanitized_snake_case().into_owned());
                }
            }
        }
    }
    set.into_iter().collect()
}

fn load_from(input: &str, config: &Config) -> Result<svd::Device> {
    let mut device = match config.source_type {
        SourceType::Xml => {
            let parser_config = svd::parse::Config {
                validate_level: if config.strict {
                    svd::ValidateLevel::Strict
                } else {
                    svd::ValidateLevel::Weak
                },
            };
            svd::parse::parse_with_config(input, &parser_config)
                .with_context(|| "Error parsing SVD XML file".to_string())?
        }
        SourceType::Yaml => anyhow::bail!("YAML source type is not supported"),
        SourceType::Json => anyhow::bail!("JSON source type is not supported"),
    };
    svd::expand::expand_properties(&mut device);
    Ok(device)
}

fn setup_logging(log_level: Option<&str>) {
    use log::LevelFilter;
    let level = match log_level {
        Some(l) => l.to_string(),
        None => std::env::var("RUST_LOG").unwrap_or_else(|_| "info".to_string()),
    };
    let filter = match level.to_lowercase().as_str() {
        "off" => LevelFilter::Off,
        "error" => LevelFilter::Error,
        "warn" => LevelFilter::Warn,
        "info" => LevelFilter::Info,
        "debug" => LevelFilter::Debug,
        "trace" => LevelFilter::Trace,
        _ => LevelFilter::Info,
    };
    logger::init(filter);
}

fn main() {
    if let Err(ref e) = run() {
        error!("{e:?}");
        process::exit(1);
    }
}
