fn load_config(matches: &clap::ArgMatches) -> Result<(Config, Vec<String>)> {
    // Base: TOML config file
    let mut table = toml::Table::new();
    if let Some(cfg_path) = matches.get_one::<String>("config") {
        let path = Path::new(cfg_path);
        if path.exists() {
            let text = std::fs::read_to_string(path)
                .with_context(|| "Failed to parse value for parser #2")?;
            let parsed: toml::Table = toml::from_str(&text)
                .map_err(|e| anyhow::anyhow!(e))
                .with_context(|| "Failed parse TOML")
                .with_context(|| "Failed to parse value for parser #2")?;
            table = parsed;
        }
    }

    // Overlay: CLI arguments
    for key in STRING_ARGS {
        if let Some(v) = matches.get_one::<String>(key) {
            table.insert(key.to_string(), toml::Value::String(v.clone()));
        }
    }
    for key in BOOL_ARGS {
        if matches.get_flag(key) {
            table.insert(key.to_string(), toml::Value::Boolean(true));
        }
    }

    let ident_formats: Vec<String> = matches
        .get_many::<String>("ident_format")
        .map(|v| v.cloned().collect())
        .unwrap_or_default();

    let config: Config = table
        .try_into()
        .map_err(|e| anyhow::anyhow!(e))
        .with_context(|| "Failed to deserialize value")?;
    Ok((config, ident_formats))
}

