actions.command:
cd /workspace && python3 - <<'EOF'
s=open("src/generate/register.rs").read()
start = s.find("#[allow(clippy::too_many_arguments)]\npub fn fields(")
end = s.find("fn unsafety(write_constraint")
new_fields = r'''#[allow(clippy::too_many_arguments)]
pub fn fields(
    mut fields: Vec<&Field>,
    regspec_ty: &Ident,
    rmwv: Option<ModifiedWriteValues>,
    access: Access,
    properties: &RegisterProperties,
    mod_items: &mut TokenStream,
    rpath: &RegisterPath,
    index: &Index,
    config: &Config,
) -> Result<(TokenStream, TokenStream, u64, u64)> {
    let mut r_impl_items = TokenStream::new();
    let mut w_impl_items = TokenStream::new();
    let mut zero_to_modify_fields_bitmap = 0u64;
    let mut one_to_modify_fields_bitmap = 0u64;

    let span = Span::call_site();
    let can_read = access.can_read();
    let can_write = access.can_write();

    fields.sort_by_key(|f| f.bit_range.offset);

    // Hack for #625
    let mut enum_derives = HashSet::new();
    let mut read_enum_derives = HashSet::new();
    let mut write_enum_derives = HashSet::new();

    let inline = quote! { #[inline(always)] };
    for &f in fields.iter() {
        let mut f = f.clone();
        let mut fpath = None;
        let dpath = f.derived_from.take();
        if let Some(dpath) = dpath {
            fpath = derive_field(&mut f, &dpath, rpath, index)?;
        }
        let fpath = fpath.unwrap_or_else(|| rpath.new_field(&f.name));
        let BitRange { offset, width, .. } = f.bit_range;

        if f.bit_range.width == 0 {
            return Err(anyhow!("Field {} has zero width", f.name));
        }

        let name = util::replace_suffix(&f.name, "");
        let name_snake_case = field_accessor(&name, config, span);
        let description_raw = f.description.as_deref().unwrap_or(""); // raw description, if absent using empty string
        let description = util::respace(&util::escape_special_chars(description_raw));

        let can_read = can_read
            && (f.access != Some(Access::WriteOnly))
            && (f.access != Some(Access::WriteOnce));
        let can_write = can_write && (f.access != Some(Access::ReadOnly));

        let mask = u64::MAX >> (64 - width);
        let hexmask = &util::digit_or_hex(mask);
        let offset = u64::from(offset);
        let rv = properties.reset_value.map(|rv| (rv >> offset) & mask);
        let fty = width.to_ty()?;

        let use_mask;
        let use_cast;
        if let Some(size) = properties.size {
            let size = size.to_ty_width()?;
            use_cast = size != width.to_ty_width()? && width != 1;
            use_mask = size != width;
        } else {
            use_cast = width != 1;
            use_mask = true;
        }

        let mut lookup_results = Vec::new();
        for mut ev in f.enumerated_values.clone().into_iter() {
            let mut epath = None;
            let dpath = ev.derived_from.take();
            if let Some(dpath) = dpath {
                epath = Some(derive_enumerated_values(&mut ev, &dpath, &fpath, index)?);
                // TODO: remove this hack
                if let Some(epath) = epath.as_ref() {
                    ev = (*index.evs.get(epath).unwrap()).clone();
                }
            }
            lookup_results.push((ev, epath));
        }

        let brief_suffix = if let MaybeArray::Array(_, de) = &f {
            if let Some(range) = de.indexes_as_range() {
                format!("({}-{})", *range.start(), *range.end())
            } else {
                let suffixes: Vec<_> = de.indexes();
                format!("({})", suffixes.join(","))
            }
        } else {
            String::new()
        };

        // path to the module of a base register (for derived items)
        let derived_mod_path = |r: &RegisterPath| -> Option<syn::TypePath> {
            if r == rpath {
                None
            } else if r.block == rpath.block {
                let mut segments = Punctuated::new();
                segments.push(path_segment(Ident::new("super", span)));
                segments.push(path_segment(ident(
                    &util::replace_suffix(&r.name, ""),
                    config,
                    "register_mod",
                    span,
                )));
                Some(type_path(segments))
            } else {
                let mut derived = util::block_path_to_ty(&r.block, config, span);
                derived.path.segments.push(path_segment(ident(
                    &util::replace_suffix(&r.name, ""),
                    config,
                    "register_mod",
                    span,
                )));
                Some(derived)
            }
        };

        let mut enum_items = TokenStream::new();

        // If this field can be read, generate read proxy structure
        if can_read {
            // name of read proxy type
            let reader_ty = ident(&name, config, "field_reader", span);

            let readerdoc = if let Some(action) = f.read_action {
                format!(
                    "Field `{name}{brief_suffix}` reader - {description}\n\n<div class=\"warning\">{}</div>",
                    match action {
                        ReadAction::Clear => "The field is <b>cleared</b> (set to zero) following a read operation.",
                        ReadAction::Set => "The field is <b>set</b> (set to ones) following a read operation.",
                        ReadAction::Modify => "The field is <b>modified</b> in some way after a read operation.",
                        ReadAction::ModifyExternal => "One or more dependent resources other than the current field are immediately affected by a read operation.",
                    }
                )
            } else {
                format!("Field `{name}{brief_suffix}` reader - {description}")
            };

            // if this is an enumeratedValues not derived from base, generate the enum structure
            // and implement functions for each value in enumeration.
            let mut derived_reader: Option<(Option<syn::TypePath>, Ident)> = None;
            let value_read_ty = if let Some((evs, epath)) = lookup_filter(&lookup_results, Usage::Read) {
                let ename = if config.field_names_for_enums {
                    name.clone()
                } else {
                    evs.name.clone().unwrap_or_else(|| name.clone())
                };
                let fmt_type = if evs.usage == Some(Usage::Read) {
                    "enum_read_name"
                } else {
                    "enum_name"
                };
                let value_read_ty = ident(&ename, config, fmt_type, span);
                let lookup = if evs.usage == Some(Usage::Read) {
                    &mut read_enum_derives
                } else {
                    &mut enum_derives
                };

                if let Some(epath) = epath {
                    // derived from another field
                    let base_field_name = util::replace_suffix(&epath.field().name, "");
                    let base_ename = if config.field_names_for_enums {
                        base_field_name.clone()
                    } else {
                        evs.name.clone().unwrap_or_else(|| base_field_name.clone())
                    };
                    let base_ty = ident(&base_ename, config, fmt_type, span);
                    let mod_path = derived_mod_path(epath.register());
                    if (mod_path.is_some() || base_ty != value_read_ty)
                        && lookup.insert(value_read_ty.to_string())
                    {
                        match &mod_path {
                            Some(p) => {
                                let mut p = p.clone();
                                p.path.segments.push(path_segment(base_ty.clone()));
                                mod_items.extend(quote! {
                                    #[doc = #description]
                                    pub use #p as #value_read_ty;
                                });
                            }
                            None => {
                                mod_items.extend(quote! {
                                    #[doc = #description]
                                    pub use #base_ty as #value_read_ty;
                                });
                            }
                        }
                    }
                    derived_reader = Some((
                        mod_path,
                        ident(&base_field_name, config, "field_reader", span),
                    ));
                } else {
                    let (variants, mut def, full) = enum_variants(evs, width, config)?;

                    if lookup.insert(value_read_ty.to_string()) {
                        let desc = if let Some(rv) = rv {
                            format!("{description}\n\nValue on reset: {rv}")
                        } else {
                            description.clone()
                        };
                        let defmt = config
                            .impl_defmt
                            .as_ref()
                            .map(|feature| quote!(#[cfg_attr(feature = #feature, derive(defmt::Format))]));
                        mod_items.extend(quote! {
                            #[doc = #desc]
                            #defmt
                            #[derive(Clone, Copy, Debug, PartialEq, Eq)]
                        });
                        add_from_variants(
                            mod_items,
                            variants.iter().chain(def.as_ref()),
                            &value_read_ty,
                            &fty,
                        );
                    }

                    // generate `variant` function to get enumerated value for the field
                    let has_reserved_variant = def.is_none() && !full;

                    if !variants.is_empty() || def.is_some() {
                        let mut arms = TokenStream::new();
                        arms.extend(variants.iter().map(|v| {
                            let i = util::unsuffixed_or_bool(v.value, width);
                            let pc = &v.pc;

                            if has_reserved_variant {
                                quote! { #i => Some(#value_read_ty::#pc), }
                            } else {
                                quote! { #i => #value_read_ty::#pc, }
                            }
                        }));

                        if let Some(v) = def.as_ref() {
                            let pc = &v.pc;
                            arms.extend(quote! { _ => #value_read_ty::#pc, });
                        } else if has_reserved_variant {
                            arms.extend(quote! { _ => None, });
                        } else if width > 1 {
                            // all values covered
                            arms.extend(quote! { _ => unreachable!(), });
                        }

                        if has_reserved_variant {
                            enum_items.extend(quote! {
                                #[doc = "Get enumerated values variant"]
                                #inline
                                pub const fn variant(&self) -> Option<#value_read_ty> {
                                    match self.bits {
                                        #arms
                                    }
                                }
                            });
                        } else {
                            enum_items.extend(quote! {
                                #[doc = "Get enumerated values variant"]
                                #inline
                                pub const fn variant(&self) -> #value_read_ty {
                                    match self.bits {
                                        #arms
                                    }
                                }
                            });
                        }

                        // generate `is_variant` functions for each variant in enumeration
                        for v in &variants {
                            let pc = &v.pc;
                            let is_variant = enum_value_accessor(&v.sc_raw, config, span, false);

                            let doc = util::escape_special_chars(&util::respace(&v.doc));
                            enum_items.extend(quote! {
                                #[doc = #doc]
                                #inline
                                pub fn #is_variant(&self) -> bool {
                                    *self == #value_read_ty::#pc
                                }
                            });
                        }
                        if let Some(v) = def.take() {
                            let pc = &v.pc;
                            let is_variant = enum_value_accessor(&v.sc_raw, config, span, false);

                            let doc = util::escape_special_chars(&util::respace(&v.doc));
                            enum_items.extend(quote! {
                                #[doc = #doc]
                                #inline
                                pub fn #is_variant(&self) -> bool {
                                    matches!(self.variant(), #value_read_ty::#pc)
                                }
                            });
                        }
                    }
                }

                Some(value_read_ty)
            } else {
                None
            };

            if let Some((mod_path, base_reader)) = derived_reader {
                match mod_path {
                    Some(mut p) => {
                        p.path.segments.push(path_segment(base_reader));
                        mod_items.extend(quote! {
                            #[doc = #readerdoc]
                            pub use #p as #reader_ty;
                        });
                    }
                    None => {
                        mod_items.extend(quote! {
                            #[doc = #readerdoc]
                            pub use #base_reader as #reader_ty;
                        });
                    }
                }
            } else {
                // generate reader structure by type alias to generic read proxy structure.
                if let Some(value_read_ty) = &value_read_ty {
                    if width == 1 {
                        mod_items.extend(quote! {
                            #[doc = #readerdoc]
                            pub type #reader_ty = crate::BitReader<#value_read_ty>;
                        });
                    } else {
                        mod_items.extend(quote! {
                            #[doc = #readerdoc]
                            pub type #reader_ty = crate::FieldReader<#value_read_ty>;
                        });
                    }
                } else if width == 1 {
                    mod_items.extend(quote! {
                        #[doc = #readerdoc]
                        pub type #reader_ty = crate::BitReader;
                    });
                } else if fty == "u8" {
                    mod_items.extend(quote! {
                        #[doc = #readerdoc]
                        pub type #reader_ty = crate::FieldReader;
                    });
                } else {
                    mod_items.extend(quote! {
                        #[doc = #readerdoc]
                        pub type #reader_ty = crate::FieldReader<#fty>;
                    });
                }

                // generate variant functions
                if !enum_items.is_empty() {
                    mod_items.extend(quote! {
                        impl #reader_ty {
                            #enum_items
                        }
                    });
                }
            }

            // Generate field reader accessors
            if let MaybeArray::Array(_, de) = &f {
                let increment = de.dim_increment;
                let doc = description.replace("%s", &brief_suffix);
                let first_name = util::replace_suffix(&f.name, &de.indexes()[0]);
                let note = format!("<div class=\"warning\">`n` is number of field in register. `n == 0` corresponds to `{first_name}` field.</div>");
                let offset_calc = calculate_offset(increment, offset, true);
                let value = quote! { (self.bits >> #offset_calc) };
                let value = field_value_expr(value, width, true, use_cast, hexmask, &fty);
                let dim = de.dim as u64;
                let dim_lit = unsuffixed(dim);
                r_impl_items.extend(quote! {
                    #[doc = #doc]
                    #[doc = ""]
                    #[doc = #note]
                    #inline
                    pub fn #name_snake_case(&self, n: u8) -> #reader_ty {
                        #[allow(clippy::no_effect)]
                        [(); #dim_lit][n as usize];
                        #reader_ty::new(#value)
                    }
                });
                let iter_name = Ident::new(&format!("{name_snake_case}_iter"), span);
                r_impl_items.extend(quote! {
                    #[doc = "Iterator for array of:"]
                    #[doc = #doc]
                    #inline
                    pub fn #iter_name(&self) -> impl Iterator<Item = #reader_ty> + '_ {
                        (0..#dim_lit).map(move |n| #reader_ty::new(#value))
                    }
                });

                for (i, suffix) in de.indexes().iter().enumerate() {
                    let sub_offset = offset + (i as u64) * (increment as u64);
                    let value = if sub_offset != 0 {
                        let sub_offset = &unsuffixed(sub_offset);
                        quote! { (self.bits >> #sub_offset) }
                    } else {
                        quote! { self.bits }
                    };
                    let value = field_value_expr(value, width, use_mask, use_cast, hexmask, &fty);
                    let name_snake_case_n =
                        field_accessor(&util::replace_suffix(&f.name, suffix), config, span);
                    let doc = description_with_bits(
                        &description_raw.replace("%s", suffix),
                        sub_offset,
                        width,
                    );
                    r_impl_items.extend(quote! {
                        #[doc = #doc]
                        #inline
                        pub fn #name_snake_case_n(&self) -> #reader_ty {
                            #reader_ty::new(#value)
                        }
                    });
                }
            } else {
                let value = if offset != 0 {
                    let offset = &unsuffixed(offset);
                    quote! { (self.bits >> #offset) }
                } else {
                    quote! { self.bits }
                };
                let value = field_value_expr(value, width, use_mask, use_cast, hexmask, &fty);
                let doc = description_with_bits(description_raw, offset, width);
                r_impl_items.extend(quote! {
                    #[doc = #doc]
                    #inline
                    pub fn #name_snake_case(&self) -> #reader_ty {
                        #reader_ty::new(#value)
                    }
                });
            }
        }

        // If this field can be written, generate write proxy. Generate write value if it differs from
        // the read value, or else we reuse read value.
        if can_write {
            let mwv = f.modified_write_values.or(rmwv).unwrap_or_default();
            // gets a brief of write proxy
            let writer_doc = format!("Field `{name}{brief_suffix}` writer - {description}");

            // name of write proxy type
            let writer_ty = ident(&name, config, "field_writer", span);

            let mut proxy_items = TokenStream::new();
            let mut unsafety = unsafety(f.write_constraint.as_ref(), width);

            let mut derived_writer: Option<(Option<syn::TypePath>, Ident)> = None;
            // if we writes to enumeratedValues, generate its structure if it differs from read structure.
            let value_write_ty = if let Some((evs, epath)) = lookup_filter(&lookup_results, Usage::Write) {
                let writer_reader_different_enum = evs.usage == Some(Usage::Write);
                let ename = if config.field_names_for_enums {
                    name.clone()
                } else {
                    evs.name.clone().unwrap_or_else(|| name.clone())
                };
                let fmt_type = if writer_reader_different_enum {
                    "enum_write_name"
                } else {
                    "enum_name"
                };
                let value_write_ty = ident(&ename, config, fmt_type, span);
                let lookup = if writer_reader_different_enum {
                    &mut write_enum_derives
                } else {
                    &mut enum_derives
                };

                let (variants, def, _full) = enum_variants(evs, width, config)?;
                let variants_len = variants.len() + def.iter().count();
                if variants_len as u64 == 1 << width || def.is_some() {
                    unsafety = false;
                }

                if let Some(epath) = epath {
                    let base_field_name = util::replace_suffix(&epath.field().name, "");
                    let base_ename = if config.field_names_for_enums {
                        base_field_name.clone()
                    } else {
                        evs.name.clone().unwrap_or_else(|| base_field_name.clone())
                    };
                    let base_ty = ident(&base_ename, config, fmt_type, span);
                    let mod_path = derived_mod_path(epath.register());
                    if (mod_path.is_some() || base_ty != value_write_ty)
                        && lookup.insert(value_write_ty.to_string())
                    {
                        match &mod_path {
                            Some(p) => {
                                let mut p = p.clone();
                                p.path.segments.push(path_segment(base_ty.clone()));
                                mod_items.extend(quote! {
                                    #[doc = #description]
                                    pub use #p as #value_write_ty;
                                });
                            }
                            None => {
                                mod_items.extend(quote! {
                                    #[doc = #description]
                                    pub use #base_ty as #value_write_ty;
                                });
                            }
                        }
                    }
                    derived_writer = Some((
                        mod_path,
                        ident(&base_field_name, config, "field_writer", span),
                    ));
                } else {
                    if lookup.insert(value_write_ty.to_string()) {
                        let desc = if let Some(rv) = rv {
                            format!("{description}\n\nValue on reset: {rv}")
                        } else {
                            description.clone()
                        };
                        let defmt = config
                            .impl_defmt
                            .as_ref()
                            .map(|feature| quote!(#[cfg_attr(feature = #feature, derive(defmt::Format))]));
                        mod_items.extend(quote! {
                            #[doc = #desc]
                            #defmt
                            #[derive(Clone, Copy, Debug, PartialEq, Eq)]
                        });
                        add_from_variants(
                            mod_items,
                            variants.iter().chain(def.as_ref()),
                            &value_write_ty,
                            &fty,
                        );
                    }

                    // generate write proxy functions for each variant
                    for v in variants.iter().chain(def.as_ref()) {
                        let pc = &v.pc;
                        let sc = enum_value_accessor(&v.sc_raw, config, span, true);

                        let doc = util::escape_special_chars(&util::respace(&v.doc));
                        proxy_items.extend(quote! {
                            #[doc = #doc]
                            #inline
                            pub fn #sc(self) -> &'a mut crate::W<REG> {
                                self.variant(#value_write_ty::#pc)
                            }
                        });
                    }
                }

                Some(value_write_ty)
            } else {
                None
            };

            let mwv = match mwv {
                ModifiedWriteValues::Modify => None,
                _ => Some(mwv),
            };
            let (bitmap_zero, bitmap_one) = match mwv {
                Some(ModifiedWriteValues::OneToClear)
                | Some(ModifiedWriteValues::OneToSet)
                | Some(ModifiedWriteValues::OneToToggle) => (false, true),
                Some(ModifiedWriteValues::ZeroToClear)
                | Some(ModifiedWriteValues::ZeroToSet)
                | Some(ModifiedWriteValues::ZeroToToggle) => (true, false),
                _ => (false, false),
            };
            if let MaybeArray::Array(_, de) = &f {
                for i in 0..de.dim as u64 {
                    let bitmask = mask << (offset + i * de.dim_increment as u64);
                    if bitmap_zero {
                        zero_to_modify_fields_bitmap |= bitmask;
                    }
                    if bitmap_one {
                        one_to_modify_fields_bitmap |= bitmask;
                    }
                }
            } else {
                let bitmask = mask << offset;
                if bitmap_zero {
                    zero_to_modify_fields_bitmap |= bitmask;
                }
                if bitmap_one {
                    one_to_modify_fields_bitmap |= bitmask;
                }
            }

            if let Some((mod_path, base_writer)) = derived_writer {
                match mod_path {
                    Some(mut p) => {
                        p.path.segments.push(path_segment(base_writer));
                        mod_items.extend(quote! {
                            #[doc = #writer_doc]
                            pub use #p as #writer_ty;
                        });
                    }
                    None => {
                        mod_items.extend(quote! {
                            #[doc = #writer_doc]
                            pub use #base_writer as #writer_ty;
                        });
                    }
                }
            } else {
                let proxy = if width == 1 {
                    use ModifiedWriteValues::*;
                    let wproxy = Ident::new(
                        match mwv {
                            Some(Modify) | None => "BitWriter",
                            Some(OneToSet) => "BitWriter1S",
                            Some(ZeroToClear) => "BitWriter0C",
                            Some(OneToClear) => "BitWriter1C",
                            Some(ZeroToSet) => "BitWriter0S",
                            Some(OneToToggle) => "BitWriter1T",
                            Some(ZeroToToggle) => "BitWriter0T",
                            Some(Clear) | Some(Set) => "BitWriter",
                        },
                        span,
                    );
                    if let Some(value_write_ty) = &value_write_ty {
                        quote! { crate::#wproxy<'a, REG, #value_write_ty> }
                    } else {
                        quote! { crate::#wproxy<'a, REG> }
                    }
                } else {
                    let wproxy = Ident::new("FieldWriter", span);
                    let width = &unsuffixed(width as u64);
                    if let Some(value_write_ty) = &value_write_ty {
                        if unsafety {
                            quote! { crate::#wproxy<'a, REG, #width, #value_write_ty> }
                        } else {
                            quote! { crate::#wproxy<'a, REG, #width, #value_write_ty, crate::Safe> }
                        }
                    } else if unsafety {
                        if fty == "u8" {
                            quote! { crate::#wproxy<'a, REG, #width> }
                        } else {
                            quote! { crate::#wproxy<'a, REG, #width, #fty> }
                        }
                    } else {
                        quote! { crate::#wproxy<'a, REG, #width, #fty, crate::Safe> }
                    }
                };
                mod_items.extend(quote! {
                    #[doc = #writer_doc]
                    pub type #writer_ty<'a, REG> = #proxy;
                });

                // generate proxy items from collected information
                if !proxy_items.is_empty() {
                    mod_items.extend(if width == 1 {
                        quote! {
                            impl<'a, REG> #writer_ty<'a, REG>
                            where
                                REG: crate::Writable + crate::RegisterSpec,
                            {
                                #proxy_items
                            }
                        }
                    } else {
                        quote! {
                            impl<'a, REG> #writer_ty<'a, REG>
                            where
                                REG: crate::Writable + crate::RegisterSpec,
                                REG::Ux: From<#fty>
                            {
                                #proxy_items
                            }
                        }
                    });
                }
            }

            if let MaybeArray::Array(_, de) = &f {
                let increment = de.dim_increment;
                let doc = &description.replace("%s", &brief_suffix);
                let first_name = util::replace_suffix(&f.name, &de.indexes()[0]);
                let note = format!("<div class=\"warning\">`n` is number of field in register. `n == 0` corresponds to `{first_name}` field.</div>");
                let offset_calc = calculate_offset(increment, offset, false);
                let dim = unsuffixed(de.dim as u64);
                w_impl_items.extend(quote! {
                    #[doc = #doc]
                    #[doc = ""]
                    #[doc = #note]
                    #inline
                    pub fn #name_snake_case(&mut self, n: u8) -> #writer_ty<'_, #regspec_ty> {
                        #[allow(clippy::no_effect)]
                        [(); #dim][n as usize];
                        #writer_ty::new(self, #offset_calc)
                    }
                });

                for (i, suffix) in de.indexes().iter().enumerate() {
                    let sub_offset = offset + (i as u64) * (increment as u64);
                    let name_snake_case_n =
                        field_accessor(&util::replace_suffix(&f.name, suffix), config, span);
                    let doc = description_with_bits(
                        &description_raw.replace("%s", suffix),
                        sub_offset,
                        width,
                    );
                    let sub_offset = unsuffixed(sub_offset);

                    w_impl_items.extend(quote! {
                        #[doc = #doc]
                        #inline
                        pub fn #name_snake_case_n(&mut self) -> #writer_ty<'_, #regspec_ty> {
                            #writer_ty::new(self, #sub_offset)
                        }
                    });
                }
            } else {
                let doc = description_with_bits(description_raw, offset, width);
                let offset = unsuffixed(offset);
                w_impl_items.extend(quote! {
                    #[doc = #doc]
                    #inline
                    pub fn #name_snake_case(&mut self) -> #writer_ty<'_, #regspec_ty> {
                        #writer_ty::new(self, #offset)
                    }
                });
            }
        }
    }

    Ok((
        r_impl_items,
        w_impl_items,
        zero_to_modify_fields_bitmap,
        one_to_modify_fields_bitmap,
    ))
}

