    peripherals: &[Peripheral],
    device_x: &mut String,
    config: &Config,
) -> Result<TokenStream> {
    let mut mod_items = TokenStream::new();

    let riscv_config = config.settings.riscv_config.as_ref().unwrap();

    if !riscv_config.core_interrupts.is_empty() {
        debug!("Rendering target-specific core interrupts");
        writeln!(device_x, "/* Core interrupt sources and trap handlers */")?;
        let mut interrupts = vec![];
        for i in riscv_config.core_interrupts.iter() {
            let name = TokenStream::from_str(&i.name).unwrap();
            let description = i.description();
            let value = util::unsuffixed(i.value as u64);

            interrupts.push(quote! {
                #[doc = #description]
                #name = #value,
            });

            writeln!(device_x, "PROVIDE({} = DefaultHandler);", i.name)?;
            writeln!(
                device_x,
                "PROVIDE(_start_{}_trap = _start_DefaultHandler_trap);",
                i.name
            )?;
        }
        mod_items.extend(quote! {
            /// Core interrupts. These interrupts are handled by the core itself.
            #[riscv::pac_enum(unsafe CoreInterruptNumber)]
            #[derive(Debug, Clone, Copy, PartialEq, Eq)]
            pub enum CoreInterrupt {
                #(#interrupts)*
            }
        });
    } else {
        mod_items.extend(quote! {
            pub use riscv::interrupt::Interrupt as CoreInterrupt;
        });
    }

    if !riscv_config.exceptions.is_empty() {
        debug!("Rendering target-specific exceptions");
        writeln!(device_x, "/* Exception sources */")?;
        let mut exceptions = vec![];
        for e in riscv_config.exceptions.iter() {
            let name = TokenStream::from_str(&e.name).unwrap();
            let description = e.description();
            let value = util::unsuffixed(e.value as u64);

            exceptions.push(quote! {
                #[doc = #description]
                #name = #value,
            });

            writeln!(device_x, "PROVIDE({} = ExceptionHandler);", e.name)?;
        }
        mod_items.extend(quote! {
            /// Exception sources in the device.
            #[riscv::pac_enum(unsafe ExceptionNumber)]
            #[derive(Debug, Clone, Copy, PartialEq, Eq)]
            pub enum Exception {
                #(#exceptions)*
            }
        });
    } else {
        mod_items.extend(quote! {
            pub use riscv::interrupt::Exception;
        });
    }

    if !riscv_config.priorities.is_empty() {
        debug!("Rendering target-specific priority levels");
        let mut priorities = vec![];
        for p in riscv_config.priorities.iter() {
            let name = TokenStream::from_str(&p.name).unwrap();
            let description = p.description();
            let value = util::unsuffixed(p.value as u64);

            priorities.push(quote! {
                #[doc = #description]
                #name = #value,
            });
        }
        mod_items.extend(quote! {
            /// Priority levels in the device
            #[riscv::pac_enum(unsafe PriorityNumber)]
            #[derive(Debug, Clone, Copy, PartialEq, Eq)]
            pub enum Priority {
                #(#priorities)*
            }
        });
    }

    if !riscv_config.harts.is_empty() {
        debug!("Rendering target-specific HART IDs");
        let mut harts = vec![];
        for h in riscv_config.harts.iter() {
            let name = TokenStream::from_str(&h.name).unwrap();
            let description = h.description();
            let value = util::unsuffixed(h.value as u64);

            harts.push(quote! {
                #[doc = #description]
                #name = #value,
            });
        }
        mod_items.extend(quote! {
            /// HARTs in the device
            #[riscv::pac_enum(unsafe HartIdNumber)]
            #[derive(Debug, Clone, Copy, PartialEq, Eq)]
            pub enum Hart {
                #(#harts)*
            }
        });
    }

    mod_items.extend(quote! {
        pub use riscv::{
            InterruptNumber, ExceptionNumber, PriorityNumber, HartIdNumber,
            interrupt::{enable, disable, free, nested}
        };

        pub type Trap = riscv::interrupt::Trap<CoreInterrupt, Exception>;

        /// Retrieves the cause of a trap in the current hart.
        ///
        /// If the raw cause is not a valid interrupt or exception for the target, it returns an error.
        #[inline]
        pub fn try_cause() -> riscv::result::Result<Trap> {
            riscv::interrupt::try_cause()
        }

        /// Retrieves the cause of a trap in the current hart (machine mode).
        ///
        /// If the raw cause is not a valid interrupt or exception for the target, it panics.
        #[inline]
        pub fn cause() -> Trap {
            try_cause().unwrap()
        }
    });

    let external_interrupts = peripherals
        .iter()
        .flat_map(|p| p.interrupt.iter())
        .map(|i| (i.value, i))
        .collect::<BTreeMap<_, _>>();
    let external_interrupts = external_interrupts.into_values().collect::<Vec<_>>();
    if !external_interrupts.is_empty() {
        debug!("Rendering target-specific external interrupts");
        writeln!(device_x, "/* External interrupt sources */")?;
        let mut interrupts = vec![];
        for i in external_interrupts.iter() {
            let name = TokenStream::from_str(&i.name).unwrap();
            let description = i
                .description
                .as_ref()
                .map(|s| util::respace(s))
                .as_ref()
                .map(|s| util::escape_special_chars(s))
                .unwrap_or_else(|| i.name.clone());
            let value = util::unsuffixed(i.value as u64);

            interrupts.push(quote! {
                #[doc = #description]
                #name = #value,
            });

            writeln!(device_x, "PROVIDE({} = DefaultHandler);", i.name)?;
        }
        mod_items.extend(quote! {
            /// External interrupts. These interrupts are handled by the external peripherals.
            #[riscv::pac_enum(unsafe ExternalInterruptNumber)]
            #[derive(Debug, Clone, Copy, PartialEq, Eq)]
            pub enum ExternalInterrupt {
                #(#interrupts)*
            }
        });
    }

    if let Some(plic) = &riscv_config.plic {
        if let Some(core_interrupt) = &plic.core_interrupt {
            let core_interrupt = TokenStream::from_str(core_interrupt).unwrap();
            let ctx = if let Some(hart_id) = &plic.hart_id {
                let hart_id = TokenStream::from_str(hart_id).unwrap();
                quote! { plic.ctx(Hart::#hart_id) }
            } else {
                quote! { plic.ctx_mhartid() }
            };
            let plic_ty = ident(&plic.name, config, "peripheral", Span::call_site());
            mod_items.extend(quote! {
                #[cfg(feature = "rt")]
                #[riscv_rt::core_interrupt(CoreInterrupt::#core_interrupt)]
                unsafe fn plic_handler() {
                    let plic = unsafe { crate::#plic_ty::steal() };
                    let claim = #ctx.claim();
                    if let Some(s) = claim.claim::<ExternalInterrupt>() {
                        unsafe { _dispatch_external_interrupt(s.number()) }
                        claim.complete(s);
                    }
                }
            });
        }
    }

    let mut out = quote! {
        /// Interrupt numbers, priority levels, and HART IDs.
        pub mod interrupt {
            #mod_items
        }
    };

    let harts = riscv_config
        .harts
        .iter()
        .map(|h| {
            let name = TokenStream::from_str(&h.name).unwrap();
            let value = util::unsuffixed(h.value as u64);
            quote! { crate::interrupt::Hart::#name => #value }
        })
        .collect::<Vec<_>>();
    let harts = if harts.is_empty() {
        quote! {}
    } else {
        quote! { harts [#(#harts),*] }
    };

    let steal_fn = quote! {
        /// Steal an instance of this peripheral
        ///
        /// # Safety
        ///
        /// Ensure that the new instance of the peripheral cannot be used in a way
        /// that may race with any existing instances, for example by only
        /// accessing read-only or write-only registers, or by consuming the
        /// original peripheral and using critical sections to coordinate
        /// access between multiple new instances.
        ///
        /// Additionally, other software such as HALs may rely on only one
        /// peripheral instance existing to ensure memory safety; ensure
        /// no stolen instances are passed to such software.
        #[inline]
        pub unsafe fn steal() -> Self {
            Self::new()
        }
    };

    if let Some(clint) = &riscv_config.clint {
        let p = peripherals.iter().find(|&p| p.name == clint.name).unwrap();
        let base = TokenStream::from_str(&format!("0x{:X}", p.base_address)).unwrap();
        let freq = util::unsuffixed(clint.mtime_freq as u64);
        let clint_ty = ident(&clint.name, config, "peripheral", Span::call_site());
        out.extend(quote! {
            riscv_peripheral::clint_codegen!(#clint_ty, base #base, mtime_freq #freq, #harts);
            impl #clint_ty {
                #steal_fn
            }
        });
    }

    if let Some(plic) = &riscv_config.plic {
        let p = peripherals.iter().find(|&p| p.name == plic.name).unwrap();
        let base = TokenStream::from_str(&format!("0x{:X}", p.base_address)).unwrap();
        let plic_ty = ident(&plic.name, config, "peripheral", Span::call_site());
        out.extend(quote! {
            riscv_peripheral::plic_codegen!(#plic_ty, base #base, #harts);
            impl #plic_ty {
                #steal_fn
            }
        });
    }

    Ok(out)
}

