                                if let (Some(prefix), Some(prev_info)) = (re, prev_info) {
                                    if matches_array_pattern(prefix, &info_name)
                                        && is_derivable(prev_info, info)
                                    {
                                        found = Some(prev_rpath.clone());
                                        break;
                                    }
                                }
                            }
                            match found {
                                Some(root) => DeriveInfo::Implicit(root),
                                None => DeriveInfo::Root,
                            }
                        }
                        Some(rpath) => DeriveInfo::Explicit(rpath),
                    },
                    MaybeArray::Array(info, _) => {
                        let prefix = replace_suffix(&info_name, "");
                        match explicit_rpath {
                            None => {
