/// `^{prefix}[0-9]+$`
fn matches_array_pattern(prefix: &str, name: &str) -> bool {
    match name.strip_prefix(prefix) {
        Some(rest) => !rest.is_empty() && rest.chars().all(|c| c.is_ascii_digit()),
        None => false,
    }
}

fn is_derivable(potential_base: &RegisterInfo, register: &RegisterInfo) -> bool {
    (potential_base.properties == register.properties)
