#[derive(Deserialize)]
#[serde(rename_all = "camelCase")]
struct DeDimElement {
    dim: Option<u32>,
    dim_increment: Option<u32>,
    dim_index: Option<Vec<String>>,
    dim_name: Option<String>,
    dim_array_index: Option<DeDimArrayIndex>,
}

#[derive(Deserialize)]
#[serde(rename_all = "camelCase")]
struct DeDimArrayIndex {
    header_enum_name: Option<String>,
    #[serde(default)]
    values: Vec<DeEnumeratedValue>,
}

fn maybe_array<T>(info: T, dim: DeDimElement) -> Result<MaybeArray<T>, String> {
    match (dim.dim, dim.dim_increment) {
        (Some(d), Some(inc)) => Ok(MaybeArray::Array(
            info,
            DimElement {
                dim: d,
                dim_increment: inc,
                dim_index: dim.dim_index,
                dim_name: dim.dim_name,
                dim_array_index: dim.dim_array_index.map(|d| DimArrayIndex {
                    header_enum_name: d.header_enum_name,
                    values: d.values.into_iter().map(Into::into).collect(),
                }),
            },
        )),
        (None, None) => Ok(MaybeArray::Single(info)),
        (Some(_), None) => Err("missing field `dimIncrement`".into()),
        (None, Some(_)) => Err("missing field `dim`".into()),
    }
}

