#[derive(Deserialize)]
#[serde(rename_all = "camelCase")]
struct DeBitRange {
    bit_range: Option<String>,
    bit_offset: Option<u32>,
    bit_width: Option<u32>,
    lsb: Option<u32>,
    msb: Option<u32>,
}

impl DeBitRange {
    fn into_bit_range(self) -> Result<BitRange, String> {
        if let Some(text) = self.bit_range {
            let text = text.trim();
            let inner = text
                .strip_prefix('[')
                .and_then(|t| t.strip_suffix(']'))
                .ok_or_else(|| "Bit range invalid, Syntax".to_string())?;
            let mut parts = inner.split(':');
            let end: u32 = parts
                .next()
                .ok_or_else(|| "Bit range invalid, Syntax".to_string())?
                .trim()
                .parse()
                .map_err(|_| "Bit range invalid, ParseError".to_string())?;
            let start: u32 = parts
                .next()
                .ok_or_else(|| "Bit range invalid, Syntax".to_string())?
                .trim()
                .parse()
                .map_err(|_| "Bit range invalid, ParseError".to_string())?;
            if end < start {
                return Err("Bit range invalid, Size".into());
            }
            Ok(BitRange {
                offset: start,
                width: end - start + 1,
                range_type: BitRangeType::BitRange,
            })
        } else if let (Some(lsb), Some(msb)) = (self.lsb, self.msb) {
            if msb < lsb {
                return Err("Bit range invalid, Size".into());
            }
            Ok(BitRange {
                offset: lsb,
                width: msb - lsb + 1,
                range_type: BitRangeType::MsbLsb,
            })
        } else if let (Some(offset), Some(width)) = (self.bit_offset, self.bit_width) {
            Ok(BitRange {
                offset,
                width,
                range_type: BitRangeType::OffsetWidth,
            })
        } else {
            Err("Bit range invalid, Syntax".into())
        }
    }
}

