#[serde(rename_all = "camelCase")]
struct DeField {
    name: String,
    description: Option<String>,
    #[serde(flatten)]
    bit_range: DeBitRange,
    access: Option<Access>,
    modified_write_values: Option<ModifiedWriteValues>,
    write_constraint: Option<DeWriteConstraint>,
    read_action: Option<ReadAction>,
    #[serde(default)]
    enumerated_values: Vec<DeEnumeratedValues>,
    derived_from: Option<String>,
    #[serde(flatten)]
    dim: DeDimElement,
}

impl<'de> Deserialize<'de> for Field {
    fn deserialize<D: serde::Deserializer<'de>>(d: D) -> Result<Self, D::Error> {
        let f = DeField::deserialize(d)?;
        let bit_range = f.bit_range.into_bit_range().map_err(serde::de::Error::custom)?;
        let info = FieldInfo {
            name: f.name,
            description: f.description,
            bit_range,
