// ---------------------------------------------------------------------------
// Post-deserialization validation (svd-rs `validate_all`)

#[derive(Debug)]
pub struct SvdRsError {
    kind: &'static str,
    msg: String,
}

#[derive(Debug)]
struct Inner(String);

impl std::fmt::Display for Inner {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.write_str(&self.0)
    }
}
impl std::error::Error for Inner {}

impl std::fmt::Display for SvdRsError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        write!(f, "`{} error: {}", self.kind, self.msg)
    }
}

impl std::error::Error for SvdRsError {
    fn source(&self) -> Option<&(dyn std::error::Error + 'static)> {
        // leak a boxed inner to provide a source with the plain message
        let inner: &'static Inner = Box::leak(Box::new(Inner(self.msg.clone())));
        Some(inner)
    }
}

fn conv(r: validate::VResult) -> Result<(), SvdRsError> {
    r.map_err(|(kind, msg)| SvdRsError { kind, msg })
}

pub fn validate_all(d: &Device, lvl: ValidateLevel) -> Result<(), SvdRsError> {
    for p in &d.peripherals {
        validate_peripheral(p, lvl)?;
    }
    conv(validate::device(d, lvl))
}

fn validate_peripheral(p: &Peripheral, lvl: ValidateLevel) -> Result<(), SvdRsError> {
    for i in &p.interrupt {
        conv(validate::interrupt(i, lvl))?;
    }
    if let Some(regs) = p.registers.as_ref() {
        validate_ercs(regs, lvl)?;
    }
    if let Some(dim) = p.dim() {
        conv(validate::dim_element(dim, lvl))?;
    }
    conv(validate::peripheral(p, lvl))
}

fn validate_ercs(ercs: &[RegisterCluster], lvl: ValidateLevel) -> Result<(), SvdRsError> {
    for rc in ercs {
        match rc {
            RegisterCluster::Register(r) => {
                if let Some(fields) = r.fields.as_ref() {
                    for f in fields {
                        for evs in &f.enumerated_values {
                            for ev in &evs.values {
                                conv(validate::enumerated_value(ev, lvl))?;
                            }
                            conv(validate::enumerated_values(evs, lvl))?;
                        }
                        if let Some(dim) = f.dim() {
                            conv(validate::dim_element(dim, lvl))?;
                        }
                        conv(validate::field(f, lvl))?;
                    }
                }
                if let Some(dim) = r.dim() {
                    conv(validate::dim_element(dim, lvl))?;
                }
                conv(validate::register(r, lvl))?;
            }
            RegisterCluster::Cluster(c) => {
                validate_ercs(&c.children, lvl)?;
                if let Some(dim) = c.dim() {
                    conv(validate::dim_element(dim, lvl))?;
                }
                conv(validate::cluster(c, lvl))?;
            }
        }
    }
    Ok(())
}
