use log::{Level, LevelFilter, Log, Metadata, Record};
use std::io::Write;
use std::sync::Mutex;

#[derive(Clone, Debug)]
struct Directive {
    name: Option<String>,
    level: LevelFilter,
}

pub struct Logger {
    directives: Mutex<Vec<Directive>>,
