fn parse_level(s: &str) -> Option<LevelFilter> {
    match s.to_lowercase().as_str() {
        "off" => Some(LevelFilter::Off),
        "error" => Some(LevelFilter::Error),
        "warn" => Some(LevelFilter::Warn),
        "info" => Some(LevelFilter::Info),
        "debug" => Some(LevelFilter::Debug),
        "trace" => Some(LevelFilter::Trace),
        _ => None,
    }
}

/// Parse an env_logger-style filter specification
fn parse_spec(spec: &str) -> Vec<Directive> {
    let mut dirs = Vec::new();
    let mut parts = spec.split('/');
    let mods = parts.next();
    if let Some(m) = mods {
        for s in m.split(',').map(|s| s.trim()) {
            if s.is_empty() {
                continue;
            }
            let mut parts = s.split('=');
            let (log_level, name) = match (parts.next(), parts.next().map(|s| s.trim()), parts.next()) {
                (Some(part0), None, None) => {
                    // if the single argument is a log-level string or number,
                    // treat that as a global fallback
                    match parse_level(part0) {
                        Some(num) => (num, None),
                        None => (LevelFilter::max(), Some(part0)),
                    }
                }
                (Some(part0), Some(""), None) => (LevelFilter::max(), Some(part0)),
                (Some(part0), Some(part1), None) => match parse_level(part1) {
                    Some(num) => (num, Some(part0)),
                    _ => {
                        eprintln!("warning: invalid logging spec '{part1}', ignoring it");
                        continue;
                    }
                },
                _ => {
                    eprintln!("warning: invalid logging spec '{s}', ignoring it");
                    continue;
                }
            };
            dirs.push(Directive {
                name: name.map(|s| s.to_string()),
                level: log_level,
            });
        }
    }
    if dirs.is_empty() {
        dirs.push(Directive {
            name: None,
            level: LevelFilter::Error,
        });
    }
    // Sort the directives by name length (longest last)
    dirs.sort_by(|a, b| {
        let alen = a.name.as_ref().map(|a| a.len()).unwrap_or(0);
        let blen = b.name.as_ref().map(|b| b.len()).unwrap_or(0);
        alen.cmp(&blen)
    });
    dirs
}

fn enabled_by(directives: &[Directive], level: Level, target: &str) -> bool {
    // Search for the longest match, the vector is assumed to be pre-sorted.
    for directive in directives.iter().rev() {
        match directive.name {
            Some(ref name) if !target.starts_with(&**name) => {}
            Some(..) | None => return level <= directive.level,
        }
    }
    false
}

impl Log for Logger {
    fn enabled(&self, metadata: &Metadata) -> bool {
        let dirs = self.directives.lock().unwrap();
        enabled_by(&dirs, metadata.level(), metadata.target())
    }

    fn log(&self, record: &Record) {
        if !self.enabled(record.metadata()) {
            return;
        }
        let level = match record.level() {
            Level::Error => "ERROR",
            Level::Warn => "WARN ",
            Level::Info => "INFO ",
            Level::Debug => "DEBUG",
            Level::Trace => "TRACE",
        };
        let msg = format!("{}", record.args());
        let mut out = String::new();
        out.push_str(&format!("[{} {}] ", level, record.target()));
        let mut first = true;
        for line in msg.split('\n') {
            if !first {
                out.push('\n');
                out.push_str("    ");
            }
            out.push_str(line);
            first = false;
        }
        out.push('\n');
        let stderr = std::io::stderr();
        let mut lock = stderr.lock();
        let _ = lock.write_all(out.as_bytes());
    }

    fn flush(&self) {}
}

static LOGGER: Logger = Logger {
    directives: Mutex::new(Vec::new()),
};

fn max_level(dirs: &[Directive]) -> LevelFilter {
    dirs.iter()
        .map(|d| d.level)
        .max()
        .unwrap_or(LevelFilter::Off)
}

/// Initialize the logger with an env_logger-style filter spec
pub fn init(spec: &str) {
    let dirs = parse_spec(spec);
    log::set_max_level(max_level(&dirs));
    *LOGGER.directives.lock().unwrap() = dirs;
    let _ = log::set_logger(&LOGGER);
}

/// Change the filter spec (e.g. from the config file)
pub fn set_spec(spec: &str) {
    let dirs = parse_spec(spec);
    log::set_max_level(max_level(&dirs));
    *LOGGER.directives.lock().unwrap() = dirs;
}
