def name(prefix, i): return f"{prefix}{i}"
words = ["Control","Status","Data","Enable","Mode","Clock","Timer","Flag","Count","Value"]
def desc(): return " ".join(random.sample(words, random.randint(1,3))) + random.choice(["", " (x)", " [n]", " %s", " a/b", "\n  multi line"])
def access(): return random.choice([None,None,"read-write","read-only","write-only","read-writeOnce","writeOnce"])
def mwv(): return random.choice([None]*4+["oneToClear","oneToSet","oneToToggle","zeroToClear","zeroToSet","zeroToToggle","clear","set","modify"])
def ra(): return random.choice([None]*6+["clear","set","modify","modifyExternal"])
lines = []
def w(s): lines.append(s)
def enum_values(width, allow_default=True):
    nvals = random.randint(1, min(2**width, 6))
    vals = random.sample(range(2**width), nvals)
    w("<enumeratedValues>")
    if random.random()<0.6: w(f"<name>EV_{random.choice(['A','B','C'])}{random.randint(0,99)}</name>")
    if random.random()<0.3: w(f"<usage>{random.choice(['read','write','read-write'])}</usage>")
    for k,v in enumerate(vals):
        w("<enumeratedValue>")
        w(f"<name>{random.choice(['Val','val','VAL','Opt','mode','x_y','Reserved','RESERVED'])}{k}</name>")
        if random.random()<0.8: w(f"<description>{desc()}</description>")
        w(f"<value>{random.choice([str(v), hex(v), '#'+bin(v)[2:]])}</value>")
        w("</enumeratedValue>")
    if allow_default and random.random()<0.2:
        w("<enumeratedValue><name>Other</name><description>other</description><isDefault>true</isDefault></enumeratedValue>")
    w("</enumeratedValues>")
def field(i, maxbits, used):
    width = random.choice([1,1,1,2,3,4,8,16])
    free = [b for b in range(maxbits-width+1) if all(not (used & (1<<x)) for x in range(b,b+width))]
    if not free: return
    off = random.choice(free)
    isarr = random.random()<0.15 and width <= 2
    dim = random.randint(2,4) if isarr else 1
    inc = width if isarr else 0
    if isarr:
        if off + dim*inc > maxbits: return
        for d in range(dim):
            for x in range(off+d*inc, off+d*inc+width):
                if used & (1<<x): return
    for d in range(dim):
        for x in range(off+d*inc, off+d*inc+width): used |= (1<<x)
    w("<field>")
    nm = random.choice(["F","FLD","Bit","en","MODE","_x","f%d"%i,"Match","type","in","set","bits"]) + (str(i) if random.random()<0.7 else "")
    if isarr: nm = nm + "%s"
    w(f"<name>{nm}</name>")
    if random.random()<0.85: w(f"<description>{desc()}</description>")
    form = random.choice(["ow","ow","lsb","range"])
    if form=="ow": w(f"<bitOffset>{off}</bitOffset><bitWidth>{width}</bitWidth>")
    elif form=="lsb": w(f"<lsb>{off}</lsb><msb>{off+width-1}</msb>")
    else: w(f"<bitRange>[{off+width-1}:{off}]</bitRange>")
    if isarr:
        w(f"<dim>{dim}</dim><dimIncrement>{inc}</dimIncrement>")
        if random.random()<0.3: w("<dimIndex>" + ",".join(str(x) for x in range(random.randint(0,3), random.randint(0,3)+dim)) + "</dimIndex>")
    a = access()
    if a: w(f"<access>{a}</access>")
    m = mwv()
    if m: w(f"<modifiedWriteValues>{m}</modifiedWriteValues>")
    r = ra()
    if r: w(f"<readAction>{r}</readAction>")
    if random.random()<0.15:
        c = random.choice(["<writeAsRead>true</writeAsRead>","<useEnumeratedValues>true</useEnumeratedValues>",f"<range><minimum>0</minimum><maximum>{2**width-1}</maximum></range>",f"<range><minimum>1</minimum><maximum>{max(1,2**width-2)}</maximum></range>"])
        w(f"<writeConstraint>{c}</writeConstraint>")
    if random.random()<0.5 and width<=8:
        enum_values(width)
        if random.random()<0.2:
            enum_values(width, False)
    w("</field>")
    return used
def register(i, off):
    size = random.choice([32,32,32,8,16,64])
    isarr = random.random()<0.2
    dim = random.randint(2,4) if isarr else 1
    inc = (size//8) * random.choice([1,1,2]) if isarr else 0
    w("<register>")
    if isarr:
        w(f"<dim>{dim}</dim><dimIncrement>{inc}</dimIncrement>")
        if random.random()<0.4: w("<dimIndex>" + ",".join(random.choice([str(x) for x in range(dim)]) if False else str(x+random.randint(0,2)) for x in range(dim)) + "</dimIndex>")
    nm = random.choice(["REG","CR","SR","DR","ctrl","Data","ISR","x","mod"]) + str(i) + ("%s" if isarr else "")
    w(f"<name>{nm}</name>")
    if random.random()<0.9: w(f"<description>{desc()}</description>")
    if random.random()<0.1: w("<alternateGroup>ALT</alternateGroup>")
    w(f"<addressOffset>{hex(off)}</addressOffset>")
    if size != 32 or random.random()<0.3: w(f"<size>{size}</size>")
    a = access()
    if a: w(f"<access>{a}</access>")
    if random.random()<0.5: w(f"<resetValue>{hex(random.getrandbits(size) & ((1<<size)-1))}</resetValue>")
    m = mwv()
    if m: w(f"<modifiedWriteValues>{m}</modifiedWriteValues>")
    r = ra()
    if r: w(f"<readAction>{r}</readAction>")
    if random.random()<0.8:
        w("<fields>")
        used = 0
        for k in range(random.randint(1,5)):
            res = field(k, size, used)
            if res is not None: used = res
        w("</fields>")
    w("</register>")
