    w(f"<name>{nm}</name>")
    if random.random()<0.8: w(f"<description>{desc()}</description>")
    w(f"<addressOffset>{hex(off)}</addressOffset>")
    inner = 0
    body_start = len(lines)
    nregs = random.randint(1,3)
