    w(f"<baseAddress>{hex(0x40000000 + p*0x10000)}</baseAddress>")
    for q in range(random.randint(0,2)):
        w(f"<interrupt><name>IRQ_{p}_{q}</name><description>irq</description><value>{random.randint(0,40)}</value></interrupt>")
    w("<registers>")
